INSERT INTO `books` VALUES (1,'Maîtriser Laravel 12 et Volt','maitriser-laravel-12-et-volt','Un guide complet pour créer des applications web modernes et réactives très rapidement sans se prendre la tête.',NULL,0,'covers/blEgpksnhBUnDjJDYLhhiLzhWeAwjXjDKVSrtwGp.png','books/jbSHDt0BAHnxit83XD0vpiade2YxQkW31N1gqllr.pdf',10,2026,1,2,'2026-03-30 17:45:38','2026-05-11 10:33:16'),(2,'Le Guide du Développeur Freelance','le-guide-du-developpeur-freelance','Comment trouver des clients, structurer ses projets et intégrer des paiements Mobile Money facilement.',NULL,0,'covers/ToC1YzvWBq5y0N2Ve538MLBS3g2OrBBOgd5Ky6WY.jpg','books/ihPbIHXsEsLXCp2gsPlNpYW3SbjWUyXBZWbcRBw5.pdf',10,2026,1,1,'2026-03-30 17:45:38','2026-05-11 10:33:35'),(3,'Design UI/UX avec TailwindCSS','design-uiux-avec-tailwindcss','Créez des interfaces magnifiques et responsives sans jamais quitter vos fichiers Blade.','John Doe',0,'covers/CIVtvMsSzN6VCpBVpWSb5zJ82dliSZ79AYVP8GVG.png','books/ZrbSZx395zsOqs9uLNhnjSQGVi0k18797Fb66g4Q.pdf',10,2026,1,3,'2026-03-30 17:45:38','2026-05-11 10:33:48'),(4,'Java par la pratique','java-par-la-pratique','Apprendre le Java de A à Z par la pratique','FONHOUO GAUS',0,'covers/HQjSoHlvhDDnx3PED8uaRI52p4EsbCcMxl4JpVoF.png','books/70uVs1ujJnA8jku8O7qWvTiIcoPvvUGlOi1Em1x4.pdf',125,2023,1,1,'2026-04-21 01:00:46','2026-04-21 01:02:47'),(5,'Tout savoir sur python','tout-savoir-sur-python','Tout savoir sur la programmation python','Edithson',2500,'covers/K4vvM5MJVEOpsR7OGrt8ec0MXdclQlwOmAtJsYK1.jpg','books/Bh4Xjh5H80TL4U595Ecjc4nAIUIFQRb5bEYlSTDi.pdf',256,2024,1,NULL,'2026-05-11 12:59:04','2026-05-11 12:59:04'),(6,'Rédiger correctement un Cahier des Charges','rediger-correctement-un-cahier-des-charges','Fatigué des projets informatiques qui dérapent faute de clarté ? Ce guide pratique est votre allié pour maîtriser l\'art de rédiger un Cahier des Charges (CDC) efficace, qu\'il s\'agisse d\'un projet personnel ou professionnel. Découvrez comment structurer vos idées, définir les fonctionnalités et anticiper les contraintes, avec des exemples concrets couvrant la programmation, le développement web et le design CSS. Vous apprendrez l\'importance de cet outil fondamental pour mieux vous organiser et assurer la réussite de vos réalisations. Transformez vos concepts en applications solides en vous dotant d\'une méthodologie indispensable à tout concepteur.','Les Validateurs',0,'covers/rediger-correctement-un-cahier-des-charges.png','books/Rediger correctement un cahier des charges.pdf',12,2012,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:24'),(7,'Faire de son programme un Logiciel Libre','faire-de-son-programme-un-logiciel-libre','Vous avez achevé votre programme et désirez le distribuer en tant que Logiciel Libre, mais ne savez pas par où commencer ? Ce livre pratique est votre guide incontournable pour transformer votre code en une œuvre libre et collaborative. Il vous introduira aux principes fondamentaux du Logiciel Libre, vous présentera les licences majeures comme GPL, LGPL et BSD, et vous aidera à choisir celle qui convient le mieux à vos ambitions. Apprenez étape par étape comment appliquer la licence choisie, garantissant ainsi le partage, la modification et la réutilisation de votre programme en toute légalité.','GuilOooo',0,'covers/faire-de-son-programme-un-logiciel-libre.png','books/Faire de son programme un logiciel libre.pdf',10,2010,1,7,'2026-05-12 09:35:58','2026-07-29 08:53:24'),(8,'Créez des applications pour Windows 8 en HTML et JavaScript','creez-des-applications-pour-windows-8-en-html-et-javascript','Donnez une nouvelle dimension à vos compétences de développeur web en vous lançant dans la création d\'applications Windows 8 natives avec HTML et JavaScript. Ce guide complet vous accompagne pas à pas pour maîtriser l\'environnement de développement Visual Studio, concevoir des interfaces tactiles intuitives et exploiter la puissance de WinRT et WinJS. Vous apprendrez à gérer les données, intégrer les contrats de recherche et de partage, et dynamiser vos applications avec des vignettes interactives, afin de les publier avec succès sur le Windows Store.','XavierBoubert',0,'covers/creez-des-applications-pour-windows-8-en-html-et-javascript.png','books/Creez des applications pour windows 8 en html et javascript.pdf',240,2012,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:07'),(9,'Concevez votre site web avec PHP et MySQL','concevez-votre-site-web-avec-php-et-mysql','Découvrez comment transformer vos idées en sites web dynamiques et interactifs grâce à ce guide complet sur PHP et MySQL. Que vous soyez débutant ou désireux de solidifier vos bases, vous apprendrez à maîtriser les fondamentaux de PHP – des variables aux fonctions en passant par la gestion des formulaires et des sessions. Ce livre vous accompagnera pas à pas, de la mise en place de votre environnement de développement à l\'intégration des bases de données MySQL, vous offrant toutes les clés pour concevoir des applications web robustes et sécurisées.','Mathieu Nebra (Mateo21)',0,'covers/concevez-votre-site-web-avec-php-et-mysql.png','books/Concevez votre site web avec php et mysql.pdf',307,2013,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:13'),(10,'Centrer en CSS','centrer-en-css','Centrer des éléments en CSS est un défi récurrent pour de nombreux développeurs web. Ce guide exhaustif vous propose de maîtriser toutes les techniques modernes pour un centrage parfait, qu\'il soit horizontal ou vertical, et ce, pour tous types d\'éléments, dans le flux ou hors du flux. Fini les hacks obsolètes : apprenez à exploiter les propriétés natives de CSS pour des mises en page élégantes et maintenables. Idéal pour les niveaux intermédiaires, ce tutoriel complet vous permettra de transformer une source de frustration en une compétence solide et indispensable.','nightmat',0,'covers/centrer-en-css.png','books/Centrer en css.pdf',20,2012,1,5,'2026-05-12 09:35:58','2026-07-29 08:53:06'),(11,'Améliorez la visibilité de votre site grâce au référencement','ameliorez-la-visibilite-de-votre-site-grace-au-referencement','Vous souhaitez propulser votre site web en tête des résultats de recherche Google et attirer un trafic qualifié ? Ce livre est votre allié indispensable pour maîtriser toutes les facettes du référencement. Il vous guidera pas à pas, de l\'optimisation technique de vos pages (SEO on-page) et la stratégie de mots-clés, à la construction de la notoriété de votre site (SEO off-page) via les backlinks et les réseaux sociaux. Découvrez les pratiques essentielles pour communiquer efficacement avec les robots de Google et transformer durablement votre présence en ligne.','Nassoub',0,'covers/ameliorez-la-visibilite-de-votre-site-grace-au-referencement.png','books/Ameliorez la visibilite de votre site grace au referencement.pdf',129,2013,1,5,'2026-05-12 09:35:58','2026-07-29 08:53:06'),(12,'Les applications web avec JavaFX','les-applications-web-avec-javafx','Découvrez comment donner vie à vos applications web grâce à JavaFX, la technologie Java dédiée aux interfaces riches et interactives. Ce livre vous guidera pas à pas pour créer des *Rich Internet Applications (RIA)* dotées d\'animations fluides, de capacités multimédias avancées et d\'une interface utilisateur captivante. Conçu pour les développeurs ayant des bases en Java, cet ouvrage vous accompagnera de l\'installation de votre environnement jusqu\'au déploiement de vos applications web interactives, à travers des projets concrets. Transformez vos idées en des expériences web dynamiques et engageantes, prêtes à être déployées.','reemy',0,'covers/les-applications-web-avec-javafx.png','books/Les applications web avec javafx.pdf',96,2012,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:07'),(13,'PDO : comprendre et corriger les erreurs les plus fréquentes','pdo-comprendre-et-corriger-les-erreurs-les-plus-frequentes','Développeurs PHP, si PDO vous donne du fil à retordre avec ses messages d\'erreur énigmatiques, ce guide est fait pour vous ! Plongez au cœur des problèmes les plus fréquents et apprenez à les comprendre en profondeur pour les corriger durablement. De la configuration des options à la sécurisation de vos requêtes préparées, maîtrisez les astuces pour écrire un code robuste et sans faille. Ne laissez plus les erreurs PDO ralentir vos projets et développez vos applications avec confiance et sérénité.','Guillaume Ch. (cGuille)',0,'covers/pdo-comprendre-et-corriger-les-erreurs-les-plus-frequentes.png','books/Pdo comprendre et corriger les erreurs les plus frequentes.pdf',14,2011,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:07'),(14,'Apprenez à programmer en Python','apprenez-a-programmer-en-python','Découvrez les bases de la programmation et lancez-vous dans l\'apprentissage de Python, le langage incontournable pour les développeurs d\'aujourd\'hui. Ce guide complet vous accompagne pas à pas, des fondamentaux aux concepts clés tels que les variables, les structures de contrôle, les fonctions et la gestion de modules. Vous y explorerez également la modularité du code, la gestion des exceptions, ainsi que la manipulation avancée des données via les listes, tuples et dictionnaires, le tout soutenu par des exemples pratiques et un projet de TP concret. Que vous soyez novice ou désireux d\'approfondir vos connaissances, cet ouvrage est votre allié idéal pour coder efficacement et créer vos propres applications.','prolixe',0,'covers/apprenez-a-programmer-en-python.png','books/Apprenez a programmer en python.pdf',266,2013,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:17'),(15,'Poursuite d\'études après un DUT','poursuite-detudes-apres-un-dut','Le Diplôme Universitaire de Technologie en poche, vous vous interrogez sur votre avenir professionnel ou académique ? Ce guide exhaustif vous éclaire sur toutes les avenues possibles, de l\'insertion professionnelle immédiate à la poursuite d\'études en Licence Professionnelle, écoles d\'ingénieurs, ou via le cycle LMD, sans oublier les options à l\'international ou la réorientation. Découvrez également les critères de sélection des établissements et des conseils précieux pour optimiser vos choix et réussir votre transition. Cet ouvrage est l\'outil indispensable pour planifier sereinement votre parcours et faire un choix éclairé pour votre futur.','Julien Rosset (Darkelfe)',0,'covers/poursuite-d-etudes-apres-un-dut.png','books/Poursuite d etudes apres un dut.pdf',9,2011,1,6,'2026-05-12 09:35:58','2026-07-29 08:53:20'),(16,'Choisir les bons types de colonne SQL','choisir-les-bons-types-de-colonne-sql','Vous en avez assez de tables SQL lourdes et lentes ? Ce guide essentiel vous révèle comment réduire drastiquement la taille de vos bases de données MySQL en choisissant les types de colonne appropriés et en optimisant vos structures. Découvrez l\'art de maîtriser les formats numériques, dates, textes et champs à choix multiples comme `SET` et `ENUM`, ainsi que les règles d\'or pour des tables performantes. Transformez votre approche du design de bases de données et gagnez en efficacité et en rapidité, même si vous n\'utilisez aujourd\'hui que les types `INT` et `TEXT`. Optimisez vos BDD et divisez par dix la taille de vos données stockées !','Kyle Katarn',0,'covers/choisir-les-bons-types-de-colonne-sql.png','books/Choisir les bons types de colonne sql.pdf',16,2012,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:18'),(17,'Mettre des PC en réseau','mettre-des-pc-en-reseau','Envie de connecter vos ordinateurs pour un partage de fichiers fluide et efficace ? Ce guide pratique est votre allié idéal pour maîtriser la mise en réseau de vos PC sous Windows Vista ou XP, même si vous partez de zéro. Vous y découvrirez pas à pas les secrets de la connectique, de la configuration des adresses IP et du partage de ressources. Transformez vos machines isolées en un réseau domestique fonctionnel et performant en toute simplicité.','ShigeruM',0,'covers/mettre-des-pc-en-reseau.png','books/Mettre des pc en reseau.pdf',10,2011,1,7,'2026-05-12 09:35:58','2026-07-29 08:53:19'),(18,'Créez des applications pour iPhone, iPad et iPod Touch','creez-des-applications-pour-iphone-ipad-et-ipod-touch','Plongez dans l\'univers passionnant de la création d\'applications pour iPhone, iPad et iPod Touch avec ce guide complet. Conçu pour les débutants, il vous accompagne pas à pas, de l\'installation de votre environnement de développement Xcode aux fondamentaux du langage Objective-C et de la programmation orientée objet. Apprenez à concevoir des interfaces graphiques intuitives, à manipuler les principaux objets et à implémenter des fonctionnalités variées grâce à de nombreux exercices pratiques, dont un projet de Mastermind. Ce livre est la ressource idéale pour transformer vos idées en applications fonctionnelles et démarrer votre parcours de développeur iOS.','MichelMartin',0,'covers/creez-des-applications-pour-iphone-ipad-et-ipod-touch.png','books/Creez des applications pour iphone ipad et ipod touch.pdf',461,2013,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:13'),(19,'Apprenez à créer votre site web avec HTML5 et CSS3','apprenez-a-creer-votre-site-web-avec-html5-et-css3','Vous rêvez de concevoir et de donner vie à votre propre site web ? Ce guide complet est votre passeport pour l\'univers de la création web, même sans aucune expérience préalable. Apprenez à structurer le contenu avec les toutes dernières fonctionnalités de HTML5 et à le sublimer grâce aux puissantes mises en forme de CSS3. Lancez-vous et transformez vos idées en sites internet modernes et fonctionnels.','Mathieu Nebra (Mateo21)',0,'covers/apprenez-a-creer-votre-site-web-avec-html5-et-css3.png','books/apprenez-a-creer-votre-site-web-avec-html5-et-css3.pdf',248,2013,1,4,'2026-05-12 09:35:58','2026-05-12 11:51:20'),(20,'Créer un espace membre pour son site','creer-un-espace-membre-pour-son-site','Dynamisez votre site web et créez une communauté engagée grâce à un espace membre sur mesure. Cet ouvrage pratique vous guide étape par étape dans l\'implémentation des fonctionnalités essentielles : inscription, connexion sécurisée, gestion des profils et administration. Conçu pour les développeurs à l\'aise avec PHP/MySQL et les bases du front-end, il vous fournit les outils et les connaissances pour transformer vos visiteurs en membres actifs et dynamiser votre plateforme.','Mr. Black',0,'covers/creer-un-espace-membre-pour-son-site.png','books/Creer un espace membre pour son site.pdf',97,2012,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:23'),(21,'Comment créer un jeu vidéo ?','comment-creer-un-jeu-video','N\'avez-vous jamais rêvé de transformer votre passion de joueur en une réalité créative ? Ce guide essentiel vous accompagne pas à pas pour concevoir votre propre jeu vidéo, de l\'étincelle de l\'idée à sa concrétisation technique. Dédicacé aux débutants, il démystifie les composants d\'un jeu, les rôles clés et les choix essentiels, sans nécessiter aucune connaissance préalable en informatique. Lancez-vous dans cette aventure passionnante et découvrez les fondations indispensables pour donner vie à vos mondes virtuels.','Rastagong',0,'covers/comment-creer-un-jeu-video.png','books/Comment creer un jeu video.pdf',12,2012,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:19'),(22,'Créez votre propre package','creez-votre-propre-package','Si la répétition de commandes et d\'environnements dans vos préambules LaTeX vous épuise, ce guide est fait pour vous ! Découvrez comment créer vos propres packages (extensions) pour centraliser vos macros favorites et simplifier radicalement votre processus de rédaction. De la structure minimale à la gestion des options et des langues, en passant par les conditions TeX/LaTeX, ce livre vous équipe pour maîtriser la création d\'extensions personnalisées et transformer votre expérience LaTeX. Gagnez en efficacité et personnalisez entièrement votre environnement de travail, franchissant un nouveau pas dans la maîtrise de ce merveilleux système.','sp.conductos',0,'covers/creez-votre-propre-package.png','books/Creez votre propre package.pdf',13,2009,1,6,'2026-05-12 09:35:58','2026-07-29 08:53:13'),(23,'[TP] Pendu','tp-pendu','Plongez au cœur de la programmation graphique avec ce TP complet pour créer votre propre jeu du Pendu en SDL. Ce tutoriel pratique vous guide pas à pas, de la gestion des événements et l\'affichage d\'images jusqu\'à la logique du jeu, en s\'appuyant sur l\'utilisation de SDL_ttf. Profitez de ressources prêtes à l\'emploi et d\'un plan de code détaillé pour construire une version fonctionnelle, puis explorez de nombreuses pistes d\'améliorations pour pousser votre projet plus loin. Idéal pour mettre en pratique vos connaissances en C et SDL, et transformer un concept classique en une expérience interactive et visuellement enrichie.','Triviak',0,'covers/tp-pendu.png','books/Tp pendu.pdf',29,2010,1,7,'2026-05-12 09:35:58','2026-07-29 08:53:17'),(24,'jQuery, dynamisez vos pages plus simplement !','jquery-dynamisez-vos-pages-plus-simplement','Face à la complexité du JavaScript et aux incessants défis de compatibilité inter-navigateurs, jQuery s\'impose comme la solution idéale pour des pages web plus dynamiques et simples à construire. Ce guide vous invite à maîtriser cette bibliothèque légère et puissante, vous enseignant comment simplifier vos codes, gérer les sélecteurs, manipuler le DOM et dynamiser vos interfaces utilisateur avec une élégance remarquable. Grâce à une syntaxe intuitive et une gestion transparente des spécificités navigateurs, vous développerez plus vite et plus sereinement. Rejoignez les millions de développeurs qui, comme Google ou Twitter, ont choisi jQuery pour une création web plus fluide et performante.','Alex-D',0,'covers/jquery-dynamisez-vos-pages-plus-simplement.png','books/Jquery dynamisez vos pages plus simplement.pdf',30,2012,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:06'),(25,'Programmez en orienté objet en PHP','programmez-en-oriente-objet-en-php','Maîtrisez l\'art de la programmation orientée objet en PHP grâce à ce guide exhaustif et pratique. Des bases solides de la POO, incluant la création de classes, l\'héritage et les méthodes magiques, aux techniques avancées comme les interfaces, les exceptions et la réflexivité, ce livre couvre tout ce dont vous avez besoin. Conçu pour vous permettre de développer des applications PHP modernes, structurées et professionnelles, il vous accompagne à travers une approche progressive enrichie de nombreux exemples et travaux pratiques. Transformez votre code et propulsez vos compétences PHP à un niveau supérieur.','Victor Thuillier (vyk12)',0,'covers/programmez-en-oriente-objet-en-php.png','books/Programmez en oriente objet en php.pdf',332,2013,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:19'),(26,'[CSS] Les compteurs','css-les-compteurs','Fini la numérotation manuelle fastidieuse de vos chapitres et paragraphes ! Ce livre vous plonge au cœur des compteurs CSS, une fonctionnalité puissante pour automatiser et structurer élégamment le contenu de vos pages web. Apprenez à initialiser, incrémenter et insérer des numérotations complexes sans jamais toucher à votre code HTML. Offrez à vos articles et documents une présentation professionnelle et évolutive grâce à cette technique CSS indispensable.','Itello',0,'covers/css-les-compteurs.png','books/Css les compteurs.pdf',9,2012,1,5,'2026-05-12 09:35:58','2026-07-29 08:53:17'),(27,'La balise <canvas> avec JavaScript','la-balise-canvas-avec-javascript','Plongez dans l\'univers passionnant du dessin et de l\'animation web grâce à cet ouvrage essentiel dédié à la balise `<canvas>` d\'HTML5, exploitée avec JavaScript. Idéal pour les débutants, ce livre vous guide pas à pas, de la mise en place du code minimal à la création de formes variées et l\'initiation aux techniques d\'animation. Maîtrisez les fondamentaux de la création graphique interactive et transformez vos idées en expériences visuelles dynamiques sur le web, avec un projet pratique à la clé.','Renan Gehan (rgehan)',0,'covers/la-balise-canvas-avec-javascript.png','books/La balise canvas avec javascript.pdf',14,2012,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:18'),(28,'Le JavaScript moderne','le-javascript-moderne','Loin de son image passée, JavaScript s\'est imposé comme un pilier incontournable du développement moderne, étendant son influence bien au-delà du simple navigateur. Plongez dans son histoire mouvementée et explorez comment il est devenu l\'« assembleur du web », capable de propulser des applications complètes, côté client comme côté serveur ou sur le bureau. Découvrez les dernières avancées d\'ECMAScript Harmony, ses modules et ses templates, qui font de JavaScript un langage résolument tourné vers l\'avenir. Indispensable pour tout programmeur ou décideur, cet ouvrage vous offre une vision complète de ses possibilités actuelles et futures.','artragis',0,'covers/le-javascript-moderne.png','books/Le javascript moderne.pdf',17,2012,1,4,'2026-05-12 09:35:58','2026-07-29 08:53:18'),(29,'[SQL] Sélection multi- tables','sql-selection-multi-tables','Maîtrisez l\'art d\'interroger plusieurs tables SQL simultanément pour récupérer des informations corrélées de manière efficace. Cet ouvrage vous guide depuis la préparation et la modélisation de vos bases de données (MCD, clés primaires et étrangères) jusqu\'à l\'application de techniques avancées telles que les requêtes imbriquées. Idéal pour les développeurs et administrateurs qui souhaitent optimiser leurs sélections, il explore des approches innovantes pour manipuler les données multi-tables, au-delà des jointures classiques. Plongez dans ce tutoriel clair et pratique pour affiner vos compétences en SQL.','FlYos',0,'covers/sql-selection-multi-tables.png','books/Sql selection multi tables.pdf',8,2011,1,7,'2026-05-12 09:35:58','2026-07-29 08:53:13'),(30,'Analysez des données avec Excel','analysez-des-donnees-avec-excel','Découvrez comment transformer vos données brutes en informations stratégiques grâce à ce guide complet sur l\'analyse avec Excel. Que vous soyez novice ou désireux d\'approfondir vos connaissances, ce livre vous accompagnera des fondamentaux de l\'interface et de la saisie, aux techniques d\'analyse avancées telles que les tableaux croisés dynamiques, les graphiques percutants et les outils de simulation. Vous explorerez également les bases du langage VBA pour automatiser vos tâches et créer vos propres fonctions, optimisant ainsi votre productivité. Maîtrisez Excel et débloquez tout le potentiel de cet outil incontournable pour une prise de décision éclairée.','bat538 ,',0,'covers/analysez-des-donnees-avec-excel.png','books/Analysez des donnees avec excel.pdf',249,2013,1,6,'2026-05-12 09:35:59','2026-07-29 08:53:18'),(31,'Stop aux pourriels (spams)','stop-aux-pourriels-spams','Marre des pourriels qui inondent votre boîte de réception ? Si vous exposez votre adresse e-mail sur votre site, ce livre est votre bouclier indispensable. Il vous dévoile une multitude de techniques ingénieuses, allant du XHTML/CSS et JavaScript au PHP, pour masquer efficacement votre adresse aux robots spammeurs tout en la rendant parfaitement accessible à vos visiteurs légitimes. Protégez-vous dès aujourd\'hui et retrouvez une sérénité numérique.','Dark Lemon',0,'covers/stop-aux-pourriels-spams.png','books/Stop aux pourriels spams.pdf',13,2013,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:18'),(32,'Maîtrisez les bases de données avec QtSQL','maitrisez-les-bases-de-donnees-avec-qtsql','Développeurs C++ et Qt, optimisez vos applications en maîtrisant l\'intégration des bases de données grâce à ce guide pratique et accessible. Apprenez pas à pas à connecter vos projets aux systèmes de gestion de bases de données, à effectuer des requêtes simples et préparées, et à récupérer efficacement les informations. De la préparation initiale à la manipulation avancée des données avec QtSQL, vous acquerrez les compétences essentielles pour construire des applications Qt robustes et performantes.','Dadouchi A.',0,'covers/maitrisez-les-bases-de-donnees-avec-qtsql.png','books/Maitrisez les bases de donnees avec qtsql.pdf',8,2010,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:06'),(33,'Les espaces de noms en PHP','les-espaces-de-noms-en-php','Optimisez la robustesse de vos applications PHP en explorant en profondeur les espaces de noms, une fonctionnalité essentielle pour éviter les conflits de noms. Ce guide complet vous mènera de la déclaration simple à l\'organisation avancée de vos constantes, fonctions et classes, en passant par la création d\'alias pour une lisibilité accrue. Apprenez à structurer votre code avec efficacité, garantissant une meilleure maintenabilité et une intégration harmonieuse de bibliothèques tierces. Un ouvrage indispensable pour tout développeur PHP souhaitant écrire des applications plus claires et sans accroc.','Victor Thuillier (vyk12)',0,'covers/les-espaces-de-noms-en-php.png','books/Les espaces de noms en php.pdf',12,2010,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:17'),(34,'Simplifiez-vous la vie avec LESS','simplifiez-vous-la-vie-avec-less','Le CSS répétitif et fastidieux vous ralentit ? Découvrez comment LESS peut transformer votre manière de styliser vos pages web en simplifiant drastiquement votre code. Ce guide pratique vous introduit aux variables, à l\'imbrication de sélecteurs, aux classes abstraites et aux fonctions, rendant vos feuilles de style plus dynamiques et maintenables. De l\'installation côté client et serveur à la compilation, maîtrisez LESS pour développer des CSS propres et efficaces, quel que soit votre environnement. Simplifiez-vous la vie et optimisez votre flux de travail dès aujourd\'hui !','Iso',0,'covers/simplifiez-vous-la-vie-avec-less.png','books/Simplifiez vous la vie avec less.pdf',10,2011,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:07'),(35,'Comment contribuer à un projet libre sans écrire une ligne de code ?','comment-contribuer-a-un-projet-libre-sans-ecrire-une-ligne-de-code','Vous utilisez et appréciez les logiciels libres mais pensez qu\'il faut être développeur pour y contribuer ? Détrompez-vous ! Ce livre révolutionnaire vous révèle une multitude de manières concrètes et impactantes de participer activement à vos projets favoris, sans jamais écrire une ligne de code. Que ce soit en améliorant la qualité, en rédigeant de la documentation, en aidant les nouveaux utilisateurs ou en soutenant financièrement, découvrez comment apporter votre pierre à l\'édifice et devenir un membre essentiel de la communauté du libre. Préparez-vous à transformer votre passion en action et à faire une réelle différence.','Sithran',0,'covers/comment-contribuer-a-un-projet-libre-sans-ecrire-une-ligne-de-code.png','books/Comment contribuer a un projet libre sans ecrire une ligne de code.pdf',5,2010,1,7,'2026-05-12 09:35:59','2026-07-29 08:53:19'),(36,'Apprenez le fonctionnement des réseaux TCP/IP','apprenez-le-fonctionnement-des-reseaux-tcpip','Plongez au cœur des technologies qui font fonctionner Internet et maîtrisez les rouages des réseaux TCP/IP grâce à cet ouvrage didactique et complet. Explorez en profondeur chaque couche, du modèle OSI aux protocoles clés comme IP, TCP, UDP, DNS et DHCP, en passant par les fondements de la communication locale et inter-réseaux. Enrichi d\'explications claires, d\'exercices pratiques et de mises en situation concrètes (routage, Wireshark, configuration de services), ce livre vous dotera des compétences essentielles pour comprendre, configurer et diagnostiquer n\'importe quel réseau. Une référence incontournable pour tous ceux qui souhaitent percer les mystères du web.','Romain Guichard (Caelifer) ,',0,'covers/apprenez-le-fonctionnement-des-reseaux-tcp-ip.png','books/Apprenez le fonctionnement des reseaux tcp ip.pdf',219,2013,1,5,'2026-05-12 09:35:59','2026-07-29 08:53:06'),(37,'Créer un mini-RPG en JavaScript avec canvas','creer-un-mini-rpg-en-javascript-avec-canvas','Transformez vos compétences en développement web en créant un mini-RPG captivant grâce à cet ouvrage pratique, qui exploite la puissance de JavaScript et de l\'élément Canvas. Vous serez guidé à travers toutes les étapes, de la mise en place de la carte avec des tilesets dynamiques à l\'intégration de personnages animés et la gestion fluide de leurs déplacements. Conçu pour les développeurs ayant des bases en HTML, JavaScript et AJAX, ce livre vous offre une méthode concrète pour bâtir les fondations d\'un jeu fonctionnel. Lancez-vous dans l\'univers passionnant de la programmation ludique et donnez vie à votre propre aventure interactive.','Sébastien CAPARROS (sebcap26)',0,'covers/creer-un-mini-rpg-en-javascript-avec-canvas.png','books/Creer un mini rpg en javascript avec canvas.pdf',34,2012,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:18'),(38,'Des applications ultra-rapides avec Node.js','des-applications-ultra-rapides-avec-nodejs','Plongez au cœur de Node.js et maîtrisez l\'art de créer des applications web ultra-rapides et réactives, de la compréhension de son architecture non bloquante et du moteur V8 jusqu\'à l\'implémentation d\'un serveur HTTP robuste. Vous apprendrez à structurer vos projets avec le framework Express.js, à gérer efficacement les modules via NPM et à développer des interfaces dynamiques grâce aux templates EJS et aux middlewares. Allez encore plus loin en intégrant la communication temps réel via Socket.io pour offrir des expériences utilisateur fluides et interactives. Ce livre s\'adresse aux développeurs confirmés, à l\'aise avec les concepts avancés de JavaScript, souhaitant propulser leurs compétences et bâtir des applications web de pointe.','Mathieu Nebra (Mateo21)',0,'covers/des-applications-ultra-rapides-avec-node-js.png','books/Des applications ultra rapides avec node js.pdf',81,2013,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:19'),(39,'Un livre d\'or','un-livre-dor','Découvrez le guide essentiel pour intégrer un \"Livre d\'or\" fonctionnel et sécurisé à votre site web. Ce tutoriel pratique, conçu par Mathieu Nebra, vous accompagnera pas à pas dans la création d\'un système où vos visiteurs pourront laisser leurs avis, depuis la conception de la base de données MySQL jusqu\'à la mise en place d\'une pagination dynamique. Idéal pour les débutants, ce livre vous offre les compétences clés pour développer des interactions utilisateur engageantes et valoriser votre présence en ligne.','Mathieu Nebra (Mateo21)',0,'covers/un-livre-d-or.png','books/Un livre d or.pdf',9,2013,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:18'),(40,'Votre site PHP (presque) complet : architecture MVC et bonnes pratiques','votre-site-php-presque-complet-architecture-mvc-et-bonnes-pratiques','Passez à la vitesse supérieure en PHP ! Ce guide pratique vous accompagne dans la création d\'un site web sécurisé et performant, en vous initiant à l\'architecture MVC et aux bonnes pratiques de développement. Maîtrisez la gestion des bases de données avec PDO et la manipulation des formulaires, tout en construisant des modules essentiels comme un espace membre complet et un livre d\'or. Un ouvrage indispensable pour tout développeur désireux d\'adopter des méthodes professionnelles et d\'écrire un code propre et maintenable.','Savageman',0,'covers/votre-site-php-presque-complet-architecture-mvc-et-bonnes-pratiques.png','books/Votre site php presque complet architecture mvc et bonnes pratiques.pdf',54,2010,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:19'),(41,'Modélisation par révolution','modelisation-par-revolution','Envie de créer des objets 3D symétriques et élégants sans effort ? Ce livre vous dévoile la technique puissante et accessible de la modélisation par révolution. Apprenez pas à pas à transformer une simple courbe 2D en verres, vases, pièces d\'échecs ou toute autre forme arrondie, obtenant des résultats professionnels avec une étonnante facilité. Idéal pour les débutants, ce guide pratique, basé notamment sur 3ds Max, vous évitera les pièges de la modélisation complexe et donnera vie à vos créations en un tour de main.','révolution',0,'covers/modelisation-par-revolution.png','books/Modelisation par revolution.pdf',6,2010,1,7,'2026-05-12 09:35:59','2026-07-29 08:53:24'),(42,'Créer son forum de toutes pièces','creer-son-forum-de-toutes-pieces','Oubliez les solutions toutes faites et lancez-vous dans l\'aventure passionnante de la création de votre propre communauté en ligne ! Ce livre vous guide pas à pas pour concevoir un forum web entièrement sur mesure, de la structure de la base de données aux fonctionnalités les plus avancées. Vous y découvrirez comment développer les pages membres (inscription, connexion, profils, messagerie privée) et les outils d\'administration essentiels (gestion des forums, des membres, bannissement), tout en explorant des ajouts comme le système lu/non-lu, la gestion d\'amis et l\'affichage des utilisateurs en ligne. Conçu pour les développeurs PHP qui souhaitent maîtriser les rouages internes d\'une plateforme d\'échange, cet ouvrage vous offre les clés pour bâtir une solution robuste, évolutive et entièrement personnalisable, vous affranchissant des contraintes des CMS classiques.','Tadzoa',0,'covers/creer-son-forum-de-toutes-pieces.png','books/Creer son forum de toutes pieces.pdf',164,2011,1,4,'2026-05-12 09:35:59','2026-07-29 08:52:53'),(43,'La gestion des erreurs et des problèmes HTML','la-gestion-des-erreurs-et-des-problemes-html','Découvrez la solution ultime pour démystifier et corriger les problèmes récurrents dans vos créations HTML et CSS. Cet ouvrage, conçu pour les développeurs expérimentés, aborde en profondeur les erreurs de mise en page, de positionnement, d\'espacement et bien d\'autres, en vous guidant vers une compréhension approfondie de leur origine. Apprenez à utiliser efficacement des outils clés comme le validateur XHTML et la barre d\'outils Web Developer pour diagnostiquer et résoudre vos défis techniques. Transformez vos frustrations en compétences de débogage avancées et optimisez considérablement votre temps de développement.','Ciphered',0,'covers/la-gestion-des-erreurs-et-des-problemes-html.png','books/La gestion des erreurs et des problemes html.pdf',17,2010,1,5,'2026-05-12 09:35:59','2026-07-29 08:53:17'),(44,'Créez votre menu interactif en images en HTML/CSS !','creez-votre-menu-interactif-en-images-en-htmlcss','Vous souhaitez offrir à vos visiteurs une navigation web dynamique et visuellement époustouflante ? Ce livre vous apprend à concevoir un menu interactif en images, entièrement réalisé en HTML5 et CSS3, sans le moindre recours à JavaScript. Maîtrisez la structure HTML, les techniques de mise en forme avancées, les transitions CSS3 et les effets de survol et de focus pour une expérience utilisateur fluide et accessible (au clavier comme à la souris). Explorez également des compléments et des variantes pour personnaliser vos créations et repousser les limites de vos menus.','Dwayn ,',0,'covers/creez-votre-menu-interactif-en-images-en-html-css.png','books/Creez votre menu interactif en images en html css.pdf',30,2012,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:12'),(45,'Introduction à l\'injection de dépendances en PHP','introduction-a-linjection-de-dependances-en-php','Découvrez l\'Injection de Dépendances (DI) en PHP, un concept fondamental pour tout développeur souhaitant optimiser la flexibilité et la maintenabilité de ses applications. Ce livre vous guide à travers la théorie, la présentation du problème qu\'elle résout et des solutions concrètes, notamment via l\'utilisation des conteneurs de services. Approfondissez vos connaissances avec des exemples pratiques, de la création d\'un conteneur simple à l\'exploitation de bibliothèques reconnues comme Pimple. Idéal pour les développeurs PHP confirmés en POO, cet ouvrage est votre clé pour écrire un code plus robuste, adaptable et facilement testable.','vincent1870',0,'covers/introduction-a-l-injection-de-dependances-en-php.png','books/Introduction a l injection de dependances en php.pdf',16,2011,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:24'),(46,'Adopter un style de programmation clair avec le modèle MVC','adopter-un-style-de-programmation-clair-avec-le-modele-mvc','Vous souhaitez structurer votre code de manière élégante et maintenable ? Ce livre vous guide pas à pas pour maîtriser le modèle MVC (Modèle-Vue-Contrôleur), une approche essentielle pour une programmation claire et organisée. De la présentation théorique des composants à une application pratique concrète de système de news, découvrez comment optimiser l\'organisation de vos fichiers et explorer des solutions avancées comme les templates et les frameworks. Adoptez un style de programmation professionnel et rendez vos projets plus lisibles et plus faciles à gérer.','vincent1870',0,'covers/adopter-un-style-de-programmation-clair-avec-le-modele-mvc.png','books/Adopter un style de programmation clair avec le modele mvc.pdf',11,2011,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:18'),(47,'Propulsez votre site avec WordPress','propulsez-votre-site-avec-wordpress','De la première installation à l\'optimisation avancée, ce guide complet vous offre toutes les clés pour maîtriser WordPress, le CMS le plus populaire du web. Apprenez à manipuler son interface d\'administration, à gérer publications et médias, et à personnaliser son apparence avec des thèmes et des extensions. Allez bien au-delà de l\'utilisation de base en développant vos propres thèmes et plugins sur mesure, et en optimisant votre site pour le référencement et la performance avant de le mettre en production. Grâce à des explications claires et de nombreux travaux pratiques, vous serez armé pour créer et propulser un site WordPress unique, professionnel et performant.','Midnight Falcon',0,'covers/propulsez-votre-site-avec-wordpress.png','books/propulsez-votre-site-avec-wordpress.pdf',112,2014,1,4,'2026-05-12 09:35:59','2026-05-12 11:51:21'),(48,'Triggers et vues matérialisées (MySQL)','triggers-et-vues-materialisees-mysql','Optimisez vos bases de données MySQL et maîtrisez la gestion proactive des données avec ce guide complet sur les triggers et les vues matérialisées. Découvrez comment ces puissants outils peuvent transformer la performance de vos requêtes grâce à des vues matérialisées agissant comme des caches, et automatiser des tâches cruciales telles que l\'historisation des données ou le calcul de valeurs par défaut via des triggers. À travers des exemples concrets et des cas d\'usage réels, ce tutoriel intermédiaire vous guidera pas à pas, tout en vous éclairant sur les spécificités de MySQL et les précautions à prendre face aux mécanismes de verrouillage pour une implémentation robuste et efficace.','Lord Casque Noir',0,'covers/triggers-et-vues-materialisees-mysql.png','books/Triggers et vues materialisees mysql.pdf',26,2012,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:24'),(49,'Atomik Framework : un framework PHP simple et léger','atomik-framework-un-framework-php-simple-et-leger','Plongez dans l\'univers d\'Atomik Framework, un framework PHP ultra-léger et intuitif, idéal pour le développement rapide de vos projets web. Ce guide vous révèle comment exploiter la puissance de cet outil performant, développé en France, qui mise sur la simplicité et la modularité grâce à un système de plugins efficace. De son installation à la configuration avancée, en passant par la maîtrise de ses fonctions clés, vous apprendrez à construire des sites réactifs de petite à moyenne envergure. Optimisez votre workflow et découvrez une approche minimaliste mais complète pour vos applications PHP.','Warshadow',0,'covers/atomik-framework-un-framework-php-simple-et-leger.png','books/Atomik-framework-un-framework-php-simple-et-leger.pdf',11,2011,1,4,'2026-05-12 09:35:59','2026-05-12 11:51:21'),(50,'Comment faire une page ayant la même hauteur que le navigateur ?','comment-faire-une-page-ayant-la-meme-hauteur-que-le-navigateur','Vous aspirez à des pages web dont les éléments s\'ajustent parfaitement à la hauteur de la fenêtre du navigateur de vos visiteurs ? Ce guide pratique vous dévoile des techniques éprouvées pour maîtriser cette intégration essentielle, assurant une expérience utilisateur fluide et visuellement harmonieuse. Explorez pas à pas des solutions robustes en CSS et en JavaScript, conçues pour optimiser la réactivité de vos designs. Indispensable pour tout développeur soucieux de créer des interfaces modernes et dynamiques.','Anonyme',0,'covers/comment-faire-une-page-ayant-la-meme-hauteur-que-le-navigateur.png','books/Comment faire une page ayant la meme hauteur que le navigateur.pdf',8,2010,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:13'),(51,'Calcul d\'une expression mathématique','calcul-dune-expression-mathematique','Découvrez les rouages fascinants de l\'interprétation informatique avec ce guide pratique pour construire votre propre calculateur d\'expressions mathématiques. De l\'analyse lexicale à la création d\'un Arbre Syntaxique Abstrait (AST) gérant priorités et parenthèses, chaque étape est détaillée pour une compréhension approfondie. Ce tutoriel, illustré par des exemples concrets, vous mène à la réalisation d\'un interpréteur fonctionnel, offrant une première approche solide des concepts de la compilation. Idéal pour les développeurs désireux d\'appliquer leurs connaissances en récursivité et en structures arborescentes à un projet stimulant.','robocop',0,'covers/calcul-d-une-expression-mathematique.png','books/Calcul d une expression mathematique.pdf',11,2010,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:12'),(52,'jQuery : écrivez moins pour faire plus !','jquery-ecrivez-moins-pour-faire-plus','Maîtrisez jQuery et concrétisez la promesse d\'« écrire moins pour faire plus » sur vos projets web. Ce guide complet vous mènera de la manipulation du DOM et des attributs à la création d\'animations fluides et la gestion sophistiquée des événements, vous équipant des compétences essentielles pour des interfaces dynamiques. Apprenez à utiliser cette bibliothèque JavaScript, reconnue pour sa syntaxe courte, logique et sa compatibilité navigateur, et rejoignez les millions de développeurs qui l\'utilisent pour bâtir des expériences utilisateur modernes et réactives. Idéal pour les professionnels désireux de simplifier leur code et d\'accélérer le développement de leurs applications web interactives.','tit_toinou',0,'covers/jquery-ecrivez-moins-pour-faire-plus.png','books/Jquery ecrivez moins pour faire plus.pdf',86,2012,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:07'),(53,'Un compte à rebours en PHP','un-compte-a-rebours-en-php','Découvrez comment créer un compte à rebours dynamique et entièrement fonctionnel en PHP, avec une approche claire et accessible. À travers l\'exemple ludique d\'un compte à rebours avant Noël, ce livre vous guide pas à pas pour maîtriser les timestamps, les conversions de durées et la logique de gestion du temps. Vous apprendrez à structurer votre script en PHP et même à l\'agrémenter d\'une pointe de JavaScript pour une interactivité accrue. Idéal pour ceux qui cherchent à transformer des notions complexes en un outil pratique et amusant.','SpriteWare',0,'covers/un-compte-a-rebours-en-php.png','books/Un compte a rebours en php.pdf',9,2012,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:17'),(54,'Simplifiez vos développements JavaScript avec jQuery','simplifiez-vos-developpements-javascript-avec-jquery','Maîtrisez jQuery et transformez la complexité de vos développements JavaScript en une simplicité déconcertante avec ce guide indispensable. De l\'installation et la sélection d\'éléments à la gestion événementielle avancée et aux animations spectaculaires, vous explorerez toutes les fonctionnalités clés de cette bibliothèque incontournable. Grâce à des explications claires et des travaux pratiques concrets, vous serez rapidement autonome pour créer des interfaces dynamiques et réactives, optimisant ainsi votre productivité et la qualité de vos projets web.','MichelMartin',0,'covers/simplifiez-vos-developpements-javascript-avec-jquery.png','books/Simplifiez vos developpements javascript avec jquery.pdf',266,2013,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:19'),(55,'Découvrez la puissance de jQuery UI','decouvrez-la-puissance-de-jquery-ui','Découvrez comment transformer vos interfaces web en expériences utilisateur dynamiques et intuitives grâce à la puissance de jQuery UI. Ce guide complet vous mènera à travers l\'implémentation des interactions avancées, comme le glisser-déposer et le redimensionnement, et vous enseignera la maîtrise de widgets essentiels tels que les menus accordéon, les barres de progression et l\'autocomplétion. Idéal pour les développeurs soucieux d\'optimiser leur temps de développement et de garantir la compatibilité, ce livre vous fournira toutes les clés pour créer des applications web modernes, professionnelles et réactives.','Sainior',0,'covers/decouvrez-la-puissance-de-jquery-ui.png','books/Decouvrez la puissance de jquery ui.pdf',67,2012,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:19'),(56,'Apprenez à programmer en Java','apprenez-a-programmer-en-java','Découvrez l\'univers captivant de la programmation Java avec ce guide exhaustif, idéal pour les débutants désireux de maîtriser un langage puissant et polyvalent. Vous serez guidé pas à pas depuis l\'installation des outils et les fondamentaux du langage, jusqu\'à l\'exploration approfondie des concepts de la Programmation Orientée Objet (POO) comme l\'héritage et l\'encapsulation. Le parcours vous mènera ensuite à la conception d\'interfaces graphiques interactives avec Swing, à la gestion des événements, et à l\'exploitation de fonctionnalités avancées telles que les collections d\'objets, les flux d\'entrée/sortie et la réflexivité. Pratique et pédagogique, cet ouvrage vous offre toutes les clés pour développer des applications Java robustes et modernes.','cysboy',0,'covers/apprenez-a-programmer-en-java.png','books/Apprenez a programmer en java.pdf',534,2013,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:07'),(57,'Autour de la fonction exponentielle et ses constructions','autour-de-la-fonction-exponentielle-et-ses-constructions','Plongez au cœur de la fonction exponentielle et explorez ses multiples facettes au-delà des définitions habituelles. Cet ouvrage propose un approfondissement stimulant, révélant comment diverses constructions (équations différentielles, logarithmes, séries) convergent vers cette fonction essentielle et comment ses propriétés fondamentales en découlent. Idéal pour les lecteurs ayant déjà des bases en analyse et souhaitant enrichir leur compréhension, il tisse des liens entre différentes approches mathématiques, le tout agrémenté de précieuses notes culturelles. Une lecture indispensable pour maîtriser l\'essence de l\'exponentielle et sa place centrale dans le vaste univers des mathématiques.','louisclem',0,'covers/autour-de-la-fonction-exponentielle-et-ses-constructions.png','books/Autour de la fonction exponentielle et ses constructions.pdf',17,2011,1,6,'2026-05-12 09:35:59','2026-07-29 08:53:06'),(58,'Créer un menu circulaire','creer-un-menu-circulaire','Découvrez comment transformer l\'ergonomie de votre site web avec un menu circulaire attrayant et entièrement animé. Ce guide pratique vous accompagne pas à pas dans la conception de cette interface distinctive, en combinant efficacement xHTML, CSS et Javascript. Idéal pour apporter une touche d\'originalité et de modernité à vos créations, il vous permettra d\'offrir une navigation intuitive et mémorable à vos visiteurs. Élevez l\'esthétique et la fonctionnalité de vos projets web grâce à cette approche innovante.','gp2mv3',0,'covers/creer-un-menu-circulaire.png','books/Creer un menu circulaire.pdf',9,2010,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:17'),(59,'Utiliser l\'API MySQL dans vos programmes','utiliser-lapi-mysql-dans-vos-programmes','Donnez une nouvelle dimension à vos applications C/C++ en y intégrant la puissance des bases de données ! Conçu pour les développeurs ayant des bases en C/C++ et en SQL, ce guide pratique et de difficulté \"Facile\" vous accompagnera pas à pas dans l\'utilisation de l\'API MySQL. Vous apprendrez à installer la librairie sur diverses plateformes, à gérer les connexions et à maîtriser les requêtes SQL pour récupérer et manipuler vos données. Enrichissez vos projets avec des fonctionnalités robustes, de la gestion de scores en ligne aux applications nécessitant une persistance des informations.','Henon Fabien',0,'covers/utiliser-l-api-mysql-dans-vos-programmes.png','books/Utiliser l api mysql dans vos programmes.pdf',18,2012,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:18'),(60,'Créer un petit montage avec Windows Movie Maker','creer-un-petit-montage-avec-windows-movie-maker','Découvrez comment transformer vos vidéos personnelles en montages réussis grâce à ce guide complet et accessible dédié à Windows Movie Maker. Conçu spécialement pour les débutants et les étudiants, ce manuel vous accompagne pas à pas dans la maîtrise de l\'interface, de l\'organisation de la chronologie jusqu\'à l\'exportation finale de vos projets. Vous y apprendrez à manipuler vos séquences avec aisance et à appliquer des astuces pratiques pour donner une dimension professionnelle à toutes vos présentations. C’est l’ouvrage idéal pour s’initier au montage vidéo de manière intuitive, gratuite et rapide.','Norrecix',0,'covers/creer-un-petit-montage-avec-windows-movie-maker.png','books/creer-un-petit-montage-avec-windows-movie-maker.pdf',9,2012,1,6,'2026-05-12 09:35:59','2026-05-12 11:51:22'),(61,'Animez votre site avec CSS3 !','animez-votre-site-avec-css3','Donnez vie à votre site web et captez l\'attention de vos visiteurs grâce aux puissantes animations CSS3 ! Ce livre, conçu pour être accessible, vous guide pas à pas pour maîtriser les transitions fluides et les effets visuels saisissants, du simple survol aux transformations complexes. Apprenez à utiliser les propriétés CSS essentielles et découvrez comment étendre vos créations avec JavaScript pour une interactivité avancée. Offrez à vos utilisateurs une expérience moderne et dynamique qui les marquera durablement.','Adrien Guéret (KorHosik)',0,'covers/animez-votre-site-avec-css3.png','books/Animez votre site avec css3.pdf',21,2011,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:18'),(62,'Bien utiliser les sprites CSS','bien-utiliser-les-sprites-css','Optimisez la performance et la réactivité de vos sites web grâce à une technique CSS incontournable : découvrez comment les sprites transforment plusieurs requêtes d\'images en une seule. Ce guide pratique vous expliquera non seulement les principes fondamentaux, mais aussi comment réduire drastiquement les temps de chargement et garantir des animations fluides, même au survol. De la gestion des icônes simples aux images répétées, en passant par les éléments cliquables et animés, ce livre vous fournira les méthodes essentielles pour maîtriser cette approche et optimiser vos créations web.','warpShadow',0,'covers/bien-utiliser-les-sprites-css.png','books/Bien utiliser les sprites css.pdf',13,2012,1,5,'2026-05-12 09:35:59','2026-07-29 08:53:07'),(63,'register_globals et écrasement de données','register-globals-et-ecrasement-de-donnees','Découvrez les dangers insoupçonnés de la directive PHP `register_globals`, une fonctionnalité qui, malgré son apparente commodité, peut ouvrir des portes dérobées critiques dans vos applications web. Ce guide essentiel explore comment cette directive obsolète peut mener à l\'écrasement de données et à des failles de sécurité majeures, compromettant potentiellement l\'intégrité de vos systèmes. Apprenez non seulement à désactiver `register_globals` efficacement, mais aussi à implémenter des stratégies robustes, comme l\'initialisation correcte des variables ou la suppression programmatique, lorsque cette option n\'est pas disponible. Indispensable pour tout développeur ou administrateur soucieux de la sécurité de ses applications PHP, ce livre vous dotera des connaissances nécessaires pour protéger vos projets contre cette vulnérabilité courante.','luc@s',0,'covers/register-globals-et-ecrasement-de-donnees.png','books/Register globals et ecrasement de donnees.pdf',6,2013,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:19'),(64,'Le référencement de son site web','le-referencement-de-son-site-web','Envie de propulser votre site web au sommet des résultats de recherche ? Ce guide complet est votre allié indispensable pour maîtriser l\'art du référencement et attirer plus de visiteurs qualifiés. Il vous accompagnera depuis les fondamentaux de l\'ergonomie et la recherche de mots-clés stratégiques, jusqu\'à l\'optimisation technique \"in page\" de votre contenu et l\'interaction avec les moteurs de recherche. Que vous soyez novice ou désireux d\'affiner vos compétences, vous y trouverez des conseils pratiques et des outils pour rendre votre site plus visible et efficace, même face aux algorithmes en constante évolution. Transformez votre présence en ligne et captez l\'attention de votre audience cible grâce à des techniques éprouvées.','referenceur',0,'covers/le-referencement-de-son-site-web.png','books/Le referencement de son site web.pdf',58,2012,1,5,'2026-05-12 09:35:59','2026-07-29 08:53:07'),(65,'Administrez vos bases de données avec MySQL','administrez-vos-bases-de-donnees-avec-mysql','Découvrez l\'art d\'administrer vos bases de données avec MySQL grâce à ce guide pratique et exhaustif. Du paramétrage initial sur Windows, Mac OS ou Linux aux commandes SQL fondamentales pour la création et la manipulation de données, chaque étape est abordée de manière claire et progressive. Maîtrisez ensuite les concepts avancés tels que les index, les clés étrangères, les jointures complexes et les sous-requêtes pour optimiser les performances et la structure de vos bases. Que vous soyez débutant ou que vous souhaitiez approfondir vos connaissances, ce livre vous fournira toutes les clés pour devenir un administrateur MySQL accompli.','Chantal Gribaumont (Taguan)',0,'covers/administrez-vos-bases-de-donnees-avec-mysql.png','books/Administrez vos bases de donnees avec mysql.pdf',413,2012,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:08'),(66,'Adapter son site au format mobile avec CSS3','adapter-son-site-au-format-mobile-avec-css3','Votre site web est prêt à conquérir le web, mais qu\'en est-il de son affichage sur mobile ? Ce guide pratique vous révèle les secrets de CSS3 pour offrir une expérience utilisateur fluide et élégante, quel que soit l\'appareil. Maîtrisez les Media Queries et optimisez votre design grâce à des explications claires et un projet pratique complet, abordant même les menus dynamiques et les particularités du zoom. Ne laissez plus l\'affichage mobile être un frein : transformez votre site en une présence web accessible et professionnelle sur tous les écrans.','SdaliM',0,'covers/adapter-son-site-au-format-mobile-avec-css3.png','books/Adapter son site au format mobile avec css3.pdf',47,2013,1,4,'2026-05-12 09:35:59','2026-07-29 08:53:18'),(67,'Chiffrer des données avec TrueCrypt','chiffrer-des-donnees-avec-truecrypt','Vos données sensibles méritent la meilleure protection contre les regards indiscrets. Ce livre vous guide pas à pas pour maîtriser TrueCrypt, un logiciel libre et puissant de chiffrement multiplateforme. Apprenez à créer des volumes chiffrés invisibles, à sécuriser des partitions entières et à renforcer votre protection en utilisant un fichier comme mot de passe. Assurez la confidentialité de vos informations les plus précieuses avec des techniques robustes, accessibles et efficaces, quel que soit votre système d\'exploitation.','Mut',0,'covers/chiffrer-des-donnees-avec-truecrypt.png','books/Chiffrer des donnees avec truecrypt.pdf',10,2009,1,7,'2026-05-12 09:36:00','2026-07-29 08:53:18'),(68,'Créez votre application web avec Java EE','creez-votre-application-web-avec-java-ee','Lancez-vous dans le développement web professionnel avec Java EE grâce à ce guide complet, conçu pour vous accompagner depuis les fondamentaux jusqu\'à la réalisation d\'applications interactives. Vous explorerez le modèle MVC, maîtriserez les Servlets, JSP et JavaBeans, et apprendrez à structurer vos vues efficacement avec la JSTL pour un code propre et maintenable. De la configuration de votre environnement de développement à la création de formulaires dynamiques, suivez un projet fil rouge concret pour bâtir pas à pas votre première application web Java EE fonctionnelle et performante.','Coyote',0,'covers/creez-votre-application-web-avec-java-ee.png','books/Creez votre application web avec java ee.pdf',606,2013,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:12'),(69,'Créer un menu horizontal déroulant en CSS','creer-un-menu-horizontal-deroulant-en-css','Transformez l\'expérience utilisateur de votre site web avec un menu de navigation dynamique et esthétique. Ce guide pratique vous détaille la création pas-à-pas d\'un menu horizontal déroulant multi-niveaux, entièrement structuré en xHTML et stylisé avec la puissance du CSS. Apprenez à concevoir une interface fluide et adaptable, garantissant une compatibilité étendue sur les navigateurs modernes et plus anciens grâce à une touche de JavaScript. Idéal pour les développeurs web ayant déjà des bases en HTML/CSS, cet ouvrage vous offre les clés pour personnaliser et optimiser vos interfaces.','Antoine Estève (Toinouz)',0,'covers/creer-un-menu-horizontal-deroulant-en-css.png','books/Creer un menu horizontal deroulant en css.pdf',14,2009,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:06'),(70,'Générer des miniatures de pages web à la volée sur votre serveur web','generer-des-miniatures-de-pages-web-a-la-volee-sur-votre-serveur-web','Besoin de générer des centaines de miniatures de pages web par jour sans dépendre de services externes coûteux ? Ce livre vous dévoile une méthode robuste pour créer vos vignettes à la volée, directement sur votre serveur web. Apprenez à installer et configurer un serveur graphique X, puis exploitez des outils comme IceWeasel (Firefox), Opera et CutyCapt pour automatiser ce processus complexe. Offrez une nouvelle dimension à vos annuaires et applications web grâce à cette solution puissante et autonome.','Ving',0,'covers/generer-des-miniatures-de-pages-web-a-la-volee-sur-votre-serveur-web.png','books/Generer des miniatures de pages web a la volee sur votre serveur web.pdf',7,2009,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:12'),(71,'[PHP5] Comment gérer l\'absence de surcharge ?','php5-comment-gerer-labsence-de-surcharge','Un défi majeur pour tout développeur PHP5 souhaitant appliquer pleinement les principes de la Programmation Orientée Objet est l\'absence native de surcharge de méthodes. Ce mini-tutoriel expert offre des stratégies concrètes pour contourner cette restriction, notamment pour la gestion des constructeurs. Découvrez des approches ingénieuses telles que le comptage d\'arguments, le passage par tableau de paramètres ou l\'utilisation d\'objets pour écrire un code plus flexible et maintenable. Indispensable pour les profils intermédiaires en PHP et POO, il vous permettra de maîtriser ces techniques essentielles.','Legato',0,'covers/php5-comment-gerer-l-absence-de-surcharge.png','books/Php5 comment gerer l absence de surcharge.pdf',11,2010,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:06'),(72,'Introduction à la logique mathématique','introduction-a-la-logique-mathematique','\"Introduction à la logique mathématique\" vous ouvre les portes d\'une branche fondamentale et passionnante des mathématiques. Cet ouvrage didactique, conçu pour les débutants, vous guide à travers les propositions logiques, les opérateurs de base, les quantificateurs et les méthodes de raisonnement essentielles. Apprenez à établir la valeur de vérité des assertions et à construire des arguments rigoureux, une compétence indispensable bien au-delà des mathématiques. Maîtrisez les clés d\'une pensée logique structurée et aiguisez votre esprit critique avec ce tutoriel complet.','Le Zéro',0,'covers/introduction-a-la-logique-mathematique.png','books/Introduction a la logique mathematique.pdf',24,2012,1,6,'2026-05-12 09:36:00','2026-07-29 08:53:24'),(73,'Les tests unitaires en Java','les-tests-unitaires-en-java','Fatigué de passer des heures à traquer des bugs insaisissables dans votre code Java ? Ce guide pratique vous plonge au cœur des tests unitaires, l\'outil indispensable pour construire des applications robustes et fiables. De la mise en œuvre avec JUnit à la gestion des cas complexes via les mocks et l\'analyse de la couverture de code, maîtrisez chaque étape pour développer avec confiance. Écrivez du code plus propre, détectez les erreurs plus tôt et optimisez durablement votre processus de développement.','Hedi Radhouane (hedi07)',0,'covers/les-tests-unitaires-en-java.png','books/Les tests unitaires en java.pdf',30,2012,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:19'),(74,'Des statistiques pour votre site !','des-statistiques-pour-votre-site','Vous souhaitez comprendre et optimiser l\'audience de votre site web ? Ce guide pratique vous accompagne pas à pas pour mettre en place un système de statistiques performant. Découvrez comment suivre le nombre de visites, identifier vos heures de pointe, savoir qui est connecté en temps réel et, surtout, d\'où proviennent vos visiteurs, des informations précieuses pour affiner vos stratégies marketing. Conçu comme un parcours guidé avec des Travaux Pratiques et leurs corrections, cet ouvrage \"Facile\" vous permettra d\'implémenter concrètement ces outils essentiels en PHP et MySQL.','Serialtueur',0,'covers/des-statistiques-pour-votre-site.png','books/Des statistiques pour votre site.pdf',15,2010,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:06'),(75,'Comprendre l\'USB et bricoler un périphérique','comprendre-lusb-et-bricoler-un-peripherique','Plongez dans l\'univers fascinant de l\'USB avec ce guide complet qui vous révèle tous ses secrets, de son histoire à ses protocoles de communication avancés. Vous démystifierez ses schémas électriques, ses différentes versions et la complexité de la transmission des données, y compris les spécificités du Superspeed. Mettant la théorie en pratique, l\'ouvrage vous accompagnera ensuite pas à pas pour fabriquer votre premier périphérique USB : un ventilateur personnel original et futé, qui saura vous rafraîchir en toute discrétion.','OujA',0,'covers/comprendre-l-usb-et-bricoler-un-peripherique.png','books/Comprendre l usb et bricoler un peripherique.pdf',11,2012,1,7,'2026-05-12 09:36:00','2026-07-29 08:53:17'),(76,'Les closures en Javascript','les-closures-en-javascript','Plongez au cœur des mécanismes avancés de JavaScript avec cet ouvrage essentiel dédié aux closures, une technique de programmation fondamentale pour tout développeur désireux de maîtriser les subtilités du langage. Grâce à une approche pédagogique, l\'auteur revisite les concepts clés de la création de fonctions et de la portée des variables avant de vous guider pas à pas dans l\'univers des closures, illustré par des exemples concrets. Vous apprendrez à exploiter leur puissance pour des cas d\'usage avancés comme la gestion d\'événements ou la conservation d\'états, tout en évitant les pièges courants, afin de développer un code JavaScript plus robuste et performant.','Darkodam',0,'covers/les-closures-en-javascript.png','books/Les closures en javascript.pdf',9,2010,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:24'),(77,'Apostille au MVC : les Delegate','apostille-au-mvc-les-delegate','Pour les développeurs familiers avec l\'architecture Modèle-Vue-Contrôleur (MVC) dans le contexte de Qt, cet ouvrage est l\'apostille indispensable qui éclaire un composant souvent sous-estimé : les Delegates. Là où les ressources traditionnelles se concentrent sur les Modèles et les Vues, ce livre révèle comment les Delegates offrent un contrôle précis et avancé sur l\'affichage et l\'édition des données au sein de vos interfaces. Plongez dans leur mécanique interne et maîtrisez la création de vos propres Delegates pour concevoir des applications Qt d\'une flexibilité et d\'une puissance inégalées.','Mathieu STEFANI (Octal)',0,'covers/apostille-au-mvc-les-delegate.png','books/Apostille au mvc les delegate.pdf',17,2011,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:05'),(78,'Les maths pour tous !','les-maths-pour-tous','Si les mathématiques ont toujours été un défi, ce livre est votre allié pour enfin les apprivoiser ! Loin des approches scolaires traditionnelles, \"Les maths pour tous !\" vous propose un parcours clair et riche en exemples, conçu pour rendre accessibles les notions essentielles de la 6ème à la Terminale. Maîtrisez pas à pas les nombres, les opérations, les fractions et les expressions littérales grâce à une pédagogie rafraîchissante et des explications concrètes. Redécouvrez le plaisir d\'apprendre les maths et développez une solide compréhension, quelle que soit votre appréhension initiale.','Mathieu Nebra (Mateo21)',0,'covers/les-maths-pour-tous.png','books/Les maths pour tous.pdf',77,2011,1,6,'2026-05-12 09:36:00','2026-07-29 08:53:13'),(79,'CodeIgniter, le framework au service des Zéros','codeigniter-le-framework-au-service-des-zeros','Vous en avez assez de repartir de zéro à chaque nouveau projet web ? Ce livre est la solution idéale pour les développeurs désireux de créer des sites performants et robustes, rapidement et sans les contraintes habituelles des frameworks complexes. Plongez dans CodeIgniter et maîtrisez l\'architecture MVC, la programmation orientée objet, ainsi que l\'utilisation des bibliothèques et helpers, pour un développement fluide et efficace. Préparez-vous à transformer votre approche du développement web et à concrétiser vos projets avec ce framework réputé pour sa performance et sa flexibilité.','Nestea',0,'covers/codeigniter-le-framework-au-service-des-zeros.png','books/Codeigniter le framework au service des zeros.pdf',101,2013,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:07'),(80,'Structurez vos données avec XML','structurez-vos-donnees-avec-xml','Maîtrisez l\'art de structurer vos informations numériques avec XML, le langage universel pour décrire et échanger des données. De ses fondements à la création de définitions robustes via les DTD et les Schémas XML, ce guide complet vous équipe pour concevoir des structures de données cohérentes et validées. Découvrez également comment manipuler et traiter ces données avec des API essentielles telles que DOM et XPath, transformant ainsi vos connaissances théoriques en compétences pratiques indispensables.','Ludovic ROLAND (Wapiti89)',0,'covers/structurez-vos-donnees-avec-xml.png','books/Structurez vos donnees avec xml.pdf',208,2014,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:18'),(81,'Gérer son nom de domaine','gerer-son-nom-de-domaine','Le nom de domaine est la pierre angulaire de votre présence en ligne, mais son fonctionnement reste souvent un mystère. Ce livre vous propose de lever le voile sur les mécanismes complexes des adresses IP, des noms d\'hôtes et des serveurs DNS pour une compréhension approfondie. Que vous souhaitiez acquérir, configurer via un registrar ou même installer votre propre serveur de noms, vous trouverez des explications claires et des étapes pratiques. Maîtrisez la gestion de vos zones DNS et prenez enfin le contrôle total de votre identité numérique.','Mathieu Nebra (Mateo21)',0,'covers/gerer-son-nom-de-domaine.png','books/Gerer son nom de domaine.pdf',17,2011,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:06'),(82,'Créer un blog accessible avec HTML5','creer-un-blog-accessible-avec-html5','Vous maîtrisez les bases de HTML5 mais butez sur l\'utilisation sémantique des balises appropriées pour un projet concret comme un blog ? Ce livre est votre guide pratique pour construire une structure HTML5 robuste, en démystifiant l\'emploi des éléments tels que `<header>`, `<aside>`, `<section>` ou `<div>`. Au-delà de la simple mise en page, vous apprendrez à intégrer les règles d\'accessibilité ARIA, trop souvent méconnues, et la spécification Microdata pour enrichir sémantiquement vos contenus. Transformez vos connaissances en compétences concrètes pour créer un blog non seulement fonctionnel, mais aussi performant, accessible et optimisé.','Sébastien de la Marck (Thunderseb)',0,'covers/creer-un-blog-accessible-avec-html5.png','books/Creer un blog accessible avec html5.pdf',21,2012,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:06'),(83,'Upload de fichiers par formulaire','upload-de-fichiers-par-formulaire','Envie d\'offrir à vos utilisateurs la possibilité de personnaliser leur profil avec un avatar ou de partager du contenu sur votre site ? Ce guide pratique vous dévoile toutes les étapes pour maîtriser l\'upload de fichiers par formulaire, une fonctionnalité incontournable pour toute application web dynamique. Vous apprendrez à créer des formulaires robustes, à gérer les fichiers temporaires avec PHP, à implémenter des contrôles de sécurité rigoureux, et même à intégrer des fonctionnalités avancées telles que la création de miniatures ou l\'enregistrement en base de données. Conçu pour les développeurs intermédiaires, cet ouvrage vous fournit les clés pour une implémentation sécurisée et efficace.','formulaire',0,'covers/upload-de-fichiers-par-formulaire.png','books/Upload de fichiers par formulaire.pdf',14,2011,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:24'),(84,'Créez des applications pour Android','creez-des-applications-pour-android','Découvrez l\'art de la création d\'applications Android de A à Z avec cet ouvrage didactique et complet. Des fondamentaux du langage Java et de l\'écosystème Android à la conception d\'interfaces graphiques intuitives avec widgets et layouts, vous développerez une expertise solide. Le livre vous guidera pas à pas à travers l\'intégration de ressources, la gestion d\'événements, la création de vues personnalisées et les concepts avancés comme le cycle de vie des activités et la communication inter-composants. Idéal pour les débutants comme pour les développeurs souhaitant perfectionner leurs compétences, il vous fournira toutes les clés pour transformer vos idées en applications Android réussies.','Frédéric Espiau (Apollidore)',0,'covers/creez-des-applications-pour-android.png','books/Creez des applications pour android.pdf',431,2013,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:06'),(85,'Tours de magie mathématiques','tours-de-magie-mathematiques','Plongez dans l\'univers captivant des \"Tours de magie mathématiques\" et découvrez comment les chiffres et la logique peuvent créer d\'incroyables illusions. Ce livre unique vous propose d\'apprendre des tours bluffants basés sur la combinatoire et les probabilités, accessibles à tous, quel que soit votre niveau en maths ou votre âge. Oubliez la dextérité : ici, la magie opère grâce à une simple compréhension des mécanismes. Vous pourrez ainsi facilement épater vos proches avec des cartes et des dés, tout en développant une nouvelle appréciation pour la beauté des mathématiques.','Mickaël Launay (GéoMl17)',0,'covers/tours-de-magie-mathematiques.png','books/Tours de magie mathematiques.pdf',32,2012,1,6,'2026-05-12 09:36:00','2026-07-29 08:53:06'),(86,'Les noms de domaine','les-noms-de-domaine','Vous avez créé votre site web et rêvez de le rendre accessible au monde entier ? Ce livre \"Les noms de domaine\" est le guide indispensable pour démystifier cet élément fondamental de votre présence en ligne. Il vous expliquera avec clarté ce qu\'est un nom de domaine, son rôle crucial et comment il est résolu, notamment via le DNS. Apprenez également les étapes pratiques pour acquérir le nom parfait pour votre projet, et assurez ainsi une adresse mémorable et professionnelle à votre site.','Pierre-Étienne Crépy (pierreet)',0,'covers/les-noms-de-domaine.png','books/Les noms de domaine.pdf',8,2011,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:06'),(87,'Bonnes pratiques javascript','bonnes-pratiques-javascript','Un script JavaScript peut rapidement devenir un cauchemar de débogage, mais ce guide vous offre la clé d\'un code propre et performant. Découvrez les \"bonnes pratiques\" essentielles, issues de l\'expérience de professionnels du web, pour transformer vos scripts en œuvres robustes et maintenables. Ce livre vous aidera à identifier et à proscrire les erreurs courantes, tout en vous enseignant les techniques modernes d\'écriture de code JavaScript. Du placement optimal de votre code à la gestion avisée des fonctions délicates, chaque chapitre est une mine de conseils pratiques pour élever la qualité de vos projets.','nod_',0,'covers/bonnes-pratiques-javascript.png','books/Bonnes pratiques javascript.pdf',13,2012,1,4,'2026-05-12 09:36:00','2026-07-29 08:53:13'),(89,'Le livre de test','le-livre-de-test','Une description super cool','John Doe',0,'covers/WSTtOGNrnTtrxabBTOrNjd0neMs3CX0apj0Nixxw.webp','books/27OLSP7lCs9WcF8uogGtlvpPoGLQOZvDhGFrvaHi.pdf',10,2026,1,8,'2026-07-06 10:54:51','2026-07-06 10:55:37'),(90,'PyGTK','pygtk','Envie de doter vos applications Python d\'interfaces graphiques modernes et intuitives ? Plongez dans \"PyGTK\", le guide complet qui vous mènera pas à pas à la création de logiciels esthétiques et fonctionnels grâce à la puissance de la librairie GTK. Avec une approche pratique centrée sur le concepteur Glade, vous apprendrez rapidement à manipuler une multitude de widgets, des fenêtres aux boîtes de dialogue complexes. Idéal pour les développeurs intermédiaires et accessible aux débutants sous GNU/Linux, ce livre transformera vos idées en applications PyGTK conviviales en un temps record.','antoyo',0,'covers/pygtk.png','books/Pygtk.pdf',109,2010,1,4,'2026-07-29 08:52:53','2026-07-29 08:52:53'),(91,'Animation facile: les Blend Shapes','animation-facile-les-blend-shapes','Dites adieu aux animations répétitives et donnez vie à vos personnages comme jamais auparavant ! Ce guide vous plonge dans l\'univers fascinant des Blend Shapes sous Maya, une méthode incroyablement simple pour créer des expressions faciales réalistes et des déformations complexes. De la préparation de votre scène à la maîtrise des curseurs de déformation, vous apprendrez pas à pas à manipuler les points de vos objets avec une aisance déconcertante. Préparez-vous à animer les visages de vos créations les yeux fermés et à ajouter une dimension expressive unique à vos projets.','foester',0,'covers/animation-facile-les-blend-shapes.png','books/Animation facile les blend shapes.pdf',8,2011,1,7,'2026-07-29 08:53:05','2026-07-29 08:53:05'),(92,'Manier la trigonométrie','manier-la-trigonometrie','Que vous soyez novice ou désireux d\'approfondir vos connaissances, ce guide complet vous offre les clés pour manier la trigonométrie avec assurance. De l\'essentiel avec le triangle rectangle aux subtilités du cercle unité et des équations trigonométriques, cet ouvrage démystifie chaque concept en privilégiant une compréhension géométrique intuitive. Apprenez à éviter les pièges courants et optimisez vos calculs grâce à des chapitres dédiés à l\'utilisation des calculatrices et à un formulaire indispensable. Idéal pour consolider vos bases ou affiner votre expertise en la matière.','Nath22',0,'covers/manier-la-trigonometrie.png','books/Manier la trigonometrie.pdf',65,2012,1,6,'2026-07-29 08:53:05','2026-07-29 08:53:05'),(93,'Le pathfinding avec Dijkstra','le-pathfinding-avec-dijkstra','Vous êtes-vous déjà demandé comment les systèmes de navigation ou de logistique trouvent le chemin le plus court ? Ce livre vous invite à explorer l\'algorithme de Dijkstra, une pierre angulaire du pathfinding. À travers des explications claires et un exemple concret non codé, maîtrisez pas à pas les principes permettant de calculer les itinéraires optimaux et comprenez les enjeux de cette technique essentielle en informatique.','clemherreman',0,'covers/le-pathfinding-avec-dijkstra.png','books/Le pathfinding avec dijkstra.pdf',14,2011,1,4,'2026-07-29 08:53:05','2026-07-29 08:53:05'),(94,'Utilisation d\'un moteur de templates : Talus\' TPL','utilisation-dun-moteur-de-templates-talus-tpl','Optimisez votre développement web en maîtrisant la séparation cruciale entre logique métier et présentation grâce aux moteurs de templates. Ce guide pratique vous introduit à Talus\' TPL, un moteur léger et puissant à la syntaxe inspirée de XML, parfait pour des projets clairs et maintenables. Vous apprendrez pas à pas à manipuler variables, conditions, boucles et inclusions, culminant avec la création d\'un système de news complet. Adoptez Talus\' TPL pour rendre votre code plus propre et faciliter la collaboration entre développeurs et designers.','Baptiste Clavié (Talus)',0,'covers/utilisation-d-un-moteur-de-templates-talus-tpl.png','books/Utilisation d un moteur de templates talus tpl.pdf',15,2012,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(95,'Utilisation de Twig, un moteur de templates !','utilisation-de-twig-un-moteur-de-templates','Fatigué de mélanger code PHP et HTML dans vos projets ? Plongez dans l\'univers de Twig, le moteur de templates phare de Symfony, et découvrez comment structurer vos interfaces web avec élégance et efficacité. Ce livre vous guide pas à pas, de l\'installation à la maîtrise des filtres, boucles, conditions et de l\'héritage, vous permettant de séparer clairement logique métier et présentation. Adoptez Twig pour un code plus propre, plus maintenable et une productivité décuplée, que vous travailliez avec ou sans framework.','robin850',0,'covers/utilisation-de-twig-un-moteur-de-templates.png','books/Utilisation de twig un moteur de templates.pdf',16,2012,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(96,'Reprenez le contrôle à l\'aide de Linux !','reprenez-le-controle-a-laide-de-linux','Envie de reprendre le contrôle de votre machine et d\'explorer un monde numérique libre ? Ce guide complet vous accompagne pas à pas, des concepts fondamentaux de Linux à l\'installation sécurisée de votre distribution préférée, même en machine virtuelle. Vous apprendrez ensuite à maîtriser la puissante console, à naviguer dans l\'architecture des fichiers et à manipuler les commandes essentielles avec aisance. Idéal pour les débutants désireux de s\'affranchir des systèmes propriétaires et d\'acquérir une véritable autonomie numérique.','Mathieu Nebra (Mateo21)',0,'covers/reprenez-le-controle-a-l-aide-de-linux.png','books/Reprenez le controle a l aide de linux.pdf',409,2013,1,5,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(97,'Allez plus loin avec les variables !','allez-plus-loin-avec-les-variables','Prêt à maîtriser les rouages des variables PHP bien au-delà des fondamentaux ? Ce guide intermédiaire est conçu pour les développeurs souhaitant approfondir leurs connaissances après un premier cours. Vous explorerez en profondeur les références, les variables globales et statiques, ainsi que les subtilités du transtypage et des opérateurs de comparaison stricts. Évitez les pièges courants et optimisez votre code grâce à une compréhension affûtée des mécanismes internes de PHP.','Victor Thuillier (vyk12)',0,'covers/allez-plus-loin-avec-les-variables.png','books/Allez plus loin avec les variables.pdf',21,2010,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(98,'L\'émulation console','lemulation-console','Vous avez toujours rêvé de créer votre propre émulateur de console, mais ne savez pas par où commencer ? Ce guide complet démystifie le processus, vous accompagnant pas à pas de la théorie à la pratique. Explorez les fondations de l\'émulation, de la compréhension des architectures des consoles (mémoire, registres, CPU) à l\'implémentation concrète d\'un premier émulateur fonctionnel, capable de simuler les graphiques, le son et les entrées utilisateur. Mettez vos compétences en programmation à l\'épreuve et redonnez vie à l\'esprit des jeux rétro grâce à cette ressource indispensable.','BestCoder',0,'covers/l-emulation-console.png','books/L emulation console.pdf',80,2012,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(99,'La programmation ? Facile avec Ada 95 !','la-programmation-facile-avec-ada-95','Vous rêvez de programmer mais n\'avez jamais osé vous lancer, faute d\'un guide clair et accessible ? \"La programmation ? Facile avec Ada 95 !\" est le tremplin idéal pour les débutants absolus, ne nécessitant aucune connaissance préalable. Ce livre vous accompagne pas à pas, de l\'installation des outils comme AdaGide aux fondamentaux du langage tels que les variables, les conditions et les boucles, avec des exemples concrets pour coder proprement. Découvrez avec professionnalisme et aisance le monde de la programmation et transformez votre curiosité en compétences concrètes.','Louis-Nicolas Leuillet (Milrer)',0,'covers/la-programmation-facile-avec-ada-95.png','books/La programmation facile avec ada 95.pdf',29,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(100,'Enregistrer et lire des données de fichiers .ini','enregistrer-et-lire-des-donnees-de-fichiers-ini','Marre de surcharger votre base de données pour de simples sauvegardes ? Ce livre vous guide pas à pas dans l\'art d\'enregistrer et de lire efficacement des données via des fichiers .ini avec PHP. Découvrez une approche robuste et orientée objet pour gérer vos données, allant bien au-delà de la fonction `parse_ini_file` pour une flexibilité maximale avec des structures à deux niveaux. Idéal pour les développeurs désireux d\'alternatives aux bases de données, vous apprendrez à créer des systèmes de notes, de commentaires et bien plus encore, avec des exemples concrets et un code PHP complet. Optimisez votre gestion des données et maîtrisez la puissance des fichiers d\'initialisation pour vos projets web.','Kyle Katarn',0,'covers/enregistrer-et-lire-des-donnees-de-fichiers-ini.png','books/Enregistrer et lire des donnees de fichiers ini.pdf',39,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(101,'Créez des instruments virtuels avec SynthMaker','creez-des-instruments-virtuels-avec-synthmaker','Envie de concevoir vos propres instruments virtuels sans écrire une ligne de code ? Ce livre vous guide pas à pas dans l\'univers de SynthMaker, l\'outil idéal pour transformer vos idées sonores en synthétiseurs uniques et personnalisés. Vous apprendrez à manipuler les composants modulaires essentiels – oscillateurs, enveloppes, filtres – et à maîtriser le traitement audio et le routage du signal à travers des projets pratiques stimulants. Idéal pour les débutants et les utilisateurs de FL Studio, cet ouvrage vous ouvre les portes de la création sonore intuitive et puissante, vous permettant de sculpter le son de vos rêves en toute simplicité.','Jérémi Dupin (Madex)',0,'covers/creez-des-instruments-virtuels-avec-synthmaker.png','books/Creez des instruments virtuels avec synthmaker.pdf',55,2011,1,6,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(102,'Apprenez le BASIC Casio !','apprenez-le-basic-casio','Envie d\'exploiter pleinement le potentiel de votre calculatrice Casio ? Que vous soyez un programmeur débutant ou un parfait novice, ce guide complet vous initie pas à pas au langage BASIC, de A à Z. De la programmation numérique de base aux affichages graphiques avancés, en passant par la gestion des listes et matrices, chaque concept est expliqué clairement et illustré par des Travaux Pratiques concrets. Idéal pour transformer votre Casio Graph+ en un véritable outil de création, ce livre vous permettra de concevoir vos propres programmes, jeux simples et utilitaires, sans aucun prérequis.','Deltod',0,'covers/apprenez-le-basic-casio.png','books/Apprenez le basic casio.pdf',55,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(103,'Personnaliser entièrement votre Windows XP !','personnaliser-entierement-votre-windows-xp','Donnez une seconde jeunesse à votre Windows XP grâce à ce guide ultime de personnalisation ! Découvrez comment débloquer l\'installation de milliers de thèmes non-officiels et transformez l\'esthétique de votre système d\'exploitation, des icônes aux écrans de démarrage. Que vous souhaitiez des fenêtres transparentes ou des curseurs originaux, ce livre vous accompagnera pas à pas pour créer un environnement Windows XP unique et entièrement à votre image. Faites de votre bureau une véritable œuvre d\'art numérique.','orion-project',0,'covers/personnaliser-entierement-votre-windows-xp.png','books/Personnaliser entierement votre windows xp.pdf',15,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(104,'Le pattern Decorator en Python','le-pattern-decorator-en-python','Découvrez comment transformer votre approche de la Programmation Orientée Objet avec \'Le pattern Decorator en Python\'. Ce livre essentiel vous guidera à travers ce design pattern fondamental pour concevoir des applications robustes, flexibles et aisément maintenables face aux changements constants. À travers un cas d\'étude pratique et des exemples concrets, apprenez à gérer l\'évolution de votre code et à intégrer le Decorator avec les spécificités de Python pour des solutions élégantes et performantes. Offrez à vos projets la qualité et l\'extensibilité qu\'ils méritent.','nohar',0,'covers/le-pattern-decorator-en-python.png','books/Le pattern decorator en python.pdf',27,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(105,'Lecture et écriture dans les fichiers en C++','lecture-et-ecriture-dans-les-fichiers-en-c','Plongez au cœur de la gestion des fichiers avec \"Lecture et écriture dans les fichiers en C++\", le guide indispensable pour maîtriser ces opérations fondamentales. Ce livre vous propose une approche claire et rigoureuse, en se concentrant exclusivement sur les méthodes modernes et spécifiques au C++, évitant ainsi toute confusion avec les techniques du C. Apprenez à ouvrir, lire et écrire dans des fichiers texte, à gérer le positionnement et à utiliser les fonctions clés des flux, pour des applications robustes et performantes. Idéal pour les développeurs souhaitant approfondir leurs connaissances et adopter les meilleures pratiques en C++.','Xavinou',0,'covers/lecture-et-ecriture-dans-les-fichiers-en-c.png','books/Lecture et ecriture dans les fichiers en c.pdf',16,2010,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(106,'Une musique professionnelle avec Reason','une-musique-professionnelle-avec-reason','Vous rêvez de produire une musique professionnelle avec Reason, mais l\'ampleur de ce logiciel MAO vous intimide ? Ce guide complet et accessible est votre passeport pour maîtriser l\'un des studios virtuels les plus puissants du marché. Des bases de l\'installation et de l\'interface aux arcanes des synthétiseurs, samplers, effets, mixage, et même des fonctionnalités avancées comme le câblage CV et le Combinator, chaque étape est expliquée avec clarté. Préparez-vous à libérer votre créativité et à transformer vos idées en compositions sonores d\'une qualité exceptionnelle.','Jérémi Dupin (Madex)',0,'covers/une-musique-professionnelle-avec-reason.png','books/Une musique professionnelle avec reason.pdf',52,2011,1,7,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(107,'Rendus optimisés : DL, VA, VBO','rendus-optimises-dl-va-vbo','Vos rendus 3D OpenGL manquent-ils de fluidité ? Ce livre est votre guide pour maîtriser les techniques d\'optimisation indispensables et donner un coup de fouet aux performances de vos applications. Plongez dans les Display Lists, Vertex Arrays et Vertex Buffer Objects, et découvrez comment réduire drastiquement les appels coûteux au pilote graphique. Une ressource essentielle pour les développeurs C soucieux de maximiser la rapidité et l\'efficacité de leurs affichages OpenGL.','Yno',0,'covers/rendus-optimises-dl-va-vbo.png','books/Rendus optimises dl va vbo.pdf',48,2011,1,7,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(108,'Utilisation avancée des listes en Python','utilisation-avancee-des-listes-en-python','Élevez votre maîtrise de Python avec ce guide essentiel dédié à l\'utilisation avancée des listes, la structure de données la plus fondamentale du langage. Au-delà des opérations de base, plongez dans des techniques puissantes telles que les fonctions fonctionnelles, les compréhensions de liste et l\'optimisation des performances. Ce livre vous fournira les outils nécessaires pour manipuler vos données avec une efficacité et une élégance accrues, transformant ainsi la qualité de vos programmes. Idéal pour les développeurs souhaitant écrire un code Python plus robuste et performant.','Les Validateurs',0,'covers/utilisation-avancee-des-listes-en-python.png','books/Utilisation avancee des listes en python.pdf',11,2010,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(109,'L\'idle port scan','lidle-port-scan','Imaginez pouvoir scanner une machine cible sans jamais révéler votre propre identité. Ce livre vous introduit à l\'Idle Port Scan, une technique ingénieuse permettant d\'analyser les systèmes en utilisant une machine tierce, inactive, comme un leurre. Explorez en détail la théorie et la mise en pratique de ce procédé avancé, de la manipulation des paquets TCP à l\'exploitation de l\'IPID, exigeant une solide expertise en réseau. Maîtrisez cette méthode de reconnaissance furtive pour enrichir votre arsenal de connaissances en cybersécurité.','elalitte',0,'covers/l-idle-port-scan.png','books/L idle port scan.pdf',8,2010,1,7,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(110,'Apprenez à créer avec GIMP 2.8 !','apprenez-a-creer-avec-gimp-28','Découvrez le monde fascinant de la création graphique avec GIMP 2.8, le logiciel libre et puissant pour toutes vos envies artistiques ! Pensé pour les débutants, ce guide structuré vous accompagne pas à pas, de l\'installation sur votre système (Windows, Mac, Linux) à la maîtrise des outils essentiels comme les calques, les masques et les sélections. Apprenez à réaliser de la retouche photo, des montages percutants ou de la peinture numérique grâce à des explications claires et des exercices pratiques. Laissez-vous guider et libérez votre créativité, même si vous n\'avez jamais touché un logiciel de graphisme auparavant !','Ishimaru Chiaki',0,'covers/apprenez-a-creer-avec-gimp-2-8.png','books/Apprenez a creer avec gimp 2 8.pdf',218,2012,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(111,'Un système de cache simple','un-systeme-de-cache-simple','Optimisez la performance de votre site web et soulagez votre serveur avec \"Un système de cache simple\". Ce guide pratique vous enseigne à mettre en place un mécanisme de cache basé sur des fichiers, étape par étape, pour réduire la charge de vos bases de données et vos requêtes SQL. Apprenez à offrir une expérience de navigation plus rapide et fluide à vos utilisateurs, tout en assurant une mise à jour intelligente et ponctuelle de votre contenu. Un incontournable pour tous ceux qui cherchent à améliorer significativement la réactivité et l\'efficacité de leur plateforme en ligne.','Benoît CRAUET (Kermi)',0,'covers/un-systeme-de-cache-simple.png','books/Un systeme de cache simple.pdf',9,2010,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(112,'Rédiger en japonais avec LaTeX','rediger-en-japonais-avec-latex','Maîtrisez l\'art de la rédaction en japonais avec LaTeX grâce à ce guide essentiel. Spécialement conçu pour surmonter les défis des caractères multi-octets, ce livre vous équipe pour créer des documents professionnels et impeccables en langue japonaise. De l\'installation pas à pas du compilateur pLaTeX sur Windows, Linux et macOS à la configuration de Texmaker, vous apprendrez à construire et compiler vos premiers documents avec aisance. Idéal pour les utilisateurs de LaTeX souhaitant étendre leurs compétences au japonais, ce tutoriel rend la composition complexe accessible à tous.','Shaddan',0,'covers/rediger-en-japonais-avec-latex.png','books/Rediger en japonais avec latex.pdf',7,2010,1,7,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(113,'HTML5, web-workers : le monde parallèle du javascript','html5-web-workers-le-monde-parallele-du-javascript','Fatigué des pages web qui figent ou des animations saccadées à cause du JavaScript mono-thread ? Ce livre vous ouvre les portes du monde parallèle des Web Workers HTML5, une solution révolutionnaire pour exécuter du code en arrière-plan sans bloquer l\'interface utilisateur. De l\'introduction fondamentale à la programmation parallèle aux techniques avancées de communication, de gestion des erreurs et d\'optimisation des performances, il vous offre les clés pour concevoir des applications web fluides et ultra-réactives. Maîtrisez les Dedicated et Shared Workers à travers des explications claires et des exercices pratiques, et propulsez vos compétences JavaScript à un niveau supérieur.','restimel',0,'covers/html5-web-workers-le-monde-parallele-du-javascript.png','books/Html5 web workers le monde parallele du javascript.pdf',85,2012,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(114,'La redirection HTTP','la-redirection-http','Vous avez récemment déplacé votre site web, modifié des URLs ou des dossiers et vous inquiétez des conséquences sur vos visiteurs et votre référencement ? Ce livre est la réponse ! Il vous plonge au cœur de la redirection HTTP, la méthode la plus robuste et la plus utilisée pour gérer ces transitions, en vous guidant pas à pas avec Apache et les fichiers .htaccess. Maîtrisez les techniques essentielles pour assurer la pérennité de votre trafic et maintenir la visibilité de votre site sur le web.','Spy-Seth',0,'covers/la-redirection-http.png','books/La redirection http (2).pdf',8,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:13'),(115,'World of Goo : La création de niveaux avec WooGLE','world-of-goo-la-creation-de-niveaux-avec-woogle','Amateur développeur ou simple fan du jeu World of Goo, prolongez l\'aventure en donnant vie à vos propres univers ! Ce guide complet vous accompagne pas à pas dans la prise en main de WooGLE, l\'éditeur de niveaux officiel, pour transformer vos idées en terrains de jeu captivants. De l\'installation et la configuration aux techniques avancées de création de surfaces solides, d\'ajout de Goos, de gestion des particules et d\'intégration d\'éléments interactifs, vous maîtriserez tous les outils. Lancez-vous et partagez vos créations originales avec la communauté de World of Goo !','Marin M.',0,'covers/world-of-goo-la-creation-de-niveaux-avec-woogle.png','books/World of goo la creation de niveaux avec woogle.pdf',8,2010,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(116,'Comment utiliser la balise <math>','comment-utiliser-la-balise-math','Découvrez comment transformer l\'écriture de formules mathématiques complexes en un jeu d\'enfant grâce à ce guide essentiel sur la balise `<math>`. Ce livre vous initie au puissant langage TeX, en décomposant ses commandes et astuces pour vous permettre d\'insérer avec aisance des équations, symboles avancés, fonctions ou matrices dans vos textes. Que vous soyez débutant ou que vous cherchiez à affiner vos compétences, maîtrisez l\'art de la notation mathématique pour des rendus impeccables et professionnels. Ne laissez plus la complexité des formules vous intimider !','Les Validateurs',0,'covers/comment-utiliser-la-balise-math.png','books/Comment utiliser la balise math.pdf',15,2011,1,6,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(117,'Créez des applications 2D avec SFML','creez-des-applications-2d-avec-sfml','Plongez dans l\'univers fascinant de la création d\'applications et de jeux 2D avec ce guide complet dédié à la bibliothèque SFML. De l\'installation à la manipulation avancée des graphiques, du son et des événements, vous serez guidé pas à pas pour développer des interfaces riches et interactives. Grâce à de nombreux travaux pratiques, vous maîtriserez rapidement les fondamentaux pour donner vie à vos propres projets créatifs. Idéal pour les développeurs C++ de niveau intermédiaire désireux d\'explorer les vastes possibilités de cette bibliothèque multimédia performante.','mr.xyz',0,'covers/creez-des-applications-2d-avec-sfml.png','books/Creez des applications 2d avec sfml.pdf',87,2012,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(118,'Développez votre propre plug-in jQuery !','developpez-votre-propre-plug-in-jquery','Optimisez vos projets web avec jQuery en développant des plug-ins personnalisés qui démultiplient ses fonctionnalités ! Ce guide complet vous emmène des concepts fondamentaux à la création de modules d\'extension réutilisables et professionnels, en passant par la gestion avancée des paramètres. Maîtrisez l\'art de concevoir des plug-ins interactifs, comme une galerie d\'images dynamique, et apprenez à les partager efficacement. Une ressource indispensable pour tout développeur jQuery souhaitant accroître son efficacité et contribuer à la communauté.','Adrien Guéret (KorHosik)',0,'covers/developpez-votre-propre-plug-in-jquery.png','books/Developpez votre propre plug in jquery.pdf',17,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(119,'Créer son serveur FTP','creer-son-serveur-ftp','Découvrez comment monter votre propre serveur FTP de A à Z grâce à ce guide pratique et accessible. Que vous soyez webmaster ou propriétaire d\'un serveur dédié, apprenez à installer et configurer pas à pas un service comme ProFTPd pour échanger des fichiers en toute autonomie. Ce tutoriel détaillé vous expliquera les bases du protocole FTP, vous guidera dans l\'activation de votre configuration et l\'accès à votre serveur, tout en abordant les considérations de sécurité essentielles. Maîtrisez l\'échange de fichiers pour vos projets en ligne, même avec des bases en ligne de commande.','Mathieu Nebra (Mateo21)',0,'covers/creer-son-serveur-ftp.png','books/Creer son serveur ftp.pdf',11,2010,1,6,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(120,'A la découverte de l\'aléatoire et des probabilités','a-la-decouverte-de-laleatoire-et-des-probabilites','Découvrez les mystères de l\'aléatoire et des probabilités dans cet ouvrage stimulant, conçu pour démystifier l\'un des concepts les plus fascinants de l\'informatique. Au-delà de la simple utilisation de la fonction `rand`, vous apprendrez à fabriquer vos propres générateurs de nombres pseudo-aléatoires, à comprendre leur fonctionnement interne et à simuler divers phénomènes, du dé pipé aux jeux de cartes complexes. Explorez ensuite la puissance de la méthode de Monte Carlo, en l\'appliquant de manière ludique au calcul de Pi ou à l\'intégration de fonctions complexes, rendant l\'étude des probabilités accessible et passionnante pour tous.','sebsheep',0,'covers/a-la-decouverte-de-l-aleatoire-et-des-probabilites.png','books/A la decouverte de l aleatoire et des probabilites.pdf',46,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(121,'Gestion de verrou MySQL','gestion-de-verrou-mysql','Confrontez-vous à l\'incohérence des données dans un environnement multi-utilisateur ? Ce guide aborde la gestion des verrous MySQL, une technique indispensable pour garantir l\'intégrité de vos informations. Il explore en détail les verrous natifs à courte durée et les solutions programmées pour un contrôle de longue durée, en expliquant leur articulation pratique. Idéal pour les développeurs intermédiaires, cet ouvrage vous offre les clés pour bâtir des applications robustes et sans conflit de données.','P\'titMat',0,'covers/gestion-de-verrou-mysql.png','books/Gestion de verrou mysql.pdf',15,2010,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(122,'Introduction au scan de ports','introduction-au-scan-de-ports','Plongez au cœur des interactions réseau et démystifiez les mécanismes sous-jacents aux applications connectées. Ce guide essentiel vous offre une introduction claire et pratique au scan de ports, un outil fondamental pour comprendre et sécuriser n\'importe quelle infrastructure. Vous y découvrirez comment fonctionnent les ports et les protocoles TCP/UDP, apprendrez à identifier les connexions actives et maîtriserez les bases d\'un scan efficace. Idéal pour les curieux et les futurs experts en cybersécurité souhaitant explorer le monde fascinant des réseaux.','elalitte',0,'covers/introduction-au-scan-de-ports.png','books/Introduction au scan de ports.pdf',12,2009,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(123,'Créer des bibliothèques avec Code::Blocks','creer-des-bibliotheques-avec-codeblocks','Optimisez vos projets C et accélérez votre développement en maîtrisant la création de bibliothèques réutilisables. Ce guide pratique, centré sur l\'IDE Code::Blocks, vous accompagne pas à pas dans la conception de bibliothèques statiques et dynamiques, en détaillant leurs spécificités techniques. Vous apprendrez à structurer votre code pour une modularité accrue, à réduire la taille de vos exécutables et à faciliter le partage de vos fonctions. Un outil indispensable pour tout développeur C souhaitant améliorer la performance et la portabilité de ses applications.','seb13',0,'covers/creer-des-bibliotheques-avec-code-blocks.png','books/Creer des bibliotheques avec code blocks.pdf',8,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(124,'Créer et modifier le menu de Counter- Strike: Source (et autres jeux Valve)','creer-et-modifier-le-menu-de-counter-strike-source-et-autres-jeux-valve','Vous rêvez de prendre le contrôle total du menu de vos jeux Valve comme Counter-Strike: Source ? Ce guide expert vous révèle comment personnaliser chaque ligne, ajouter des raccourcis essentiels pour la console, l\'affichage des FPS ou la connexion rapide à un serveur, et bien plus encore. Apprenez à manipuler le fichier GameMenu.res avec des instructions claires et des explications détaillées des commandes spéciales. Transformez facilement votre expérience de jeu grâce à un menu sur mesure, conçu pour répondre précisément à vos besoins.','MisterJ',0,'covers/creer-et-modifier-le-menu-de-counter-strike-source-et-autres-jeux-valve.png','books/Creer et modifier le menu de counter strike source et autres jeux valve.pdf',11,2011,1,7,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(125,'Créer une icône pour son programme','creer-une-icone-pour-son-programme','Marre de l\'icône générique attribuée par Windows à vos programmes ? Donnez une identité visuelle unique et professionnelle à vos créations logicielles grâce à ce guide essentiel. Vous apprendrez à extraire des icônes existantes de fichiers .exe ou .dll, à concevoir les vôtres avec des outils gratuits et intuitifs comme SnIco Edit, et à les associer facilement à votre programme lors de la compilation. Ce cours simple et rapide vous montrera l\'importance des fichiers .ico multi-versions et vous fournira toutes les astuces pour maîtriser la personnalisation d\'icônes, transformant ainsi l\'apparence de vos applications avec facilité.','Mathieu Nebra (Mateo21)',0,'covers/creer-une-icone-pour-son-programme.png','books/Creer une icone pour son programme.pdf',8,2012,1,6,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(126,'L\'accessibilité web','laccessibilite-web','À l\'ère du numérique, l\'accès à l\'information et aux services en ligne devrait être universel. Pourtant, de nombreuses personnes en situation de handicap se heurtent à des barrières invisibles. Cet ouvrage explore en profondeur les défis rencontrés par les utilisateurs malvoyants, aveugles, malentendants et sourds, détaillant leurs besoins spécifiques et les obstacles techniques fréquents. À travers des cas d\'usage concrets et des explications claires, il vous offre les clés pour comprendre et concevoir des expériences web véritablement accessibles et inclusives.','Sylvie_Duchateau',0,'covers/l-accessibilite-web.png','books/L accessibilite web.pdf',6,2013,1,7,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(127,'Qu\'est-ce que le Responsive Web Design ?','quest-ce-que-le-responsive-web-design','L\'explosion de l\'usage des appareils mobiles a rendu indispensable l\'adaptation des sites web à toutes les tailles d\'écran. Découvrez dans ce guide complet le Responsive Web Design, la solution élégante et efficace pour que votre site s\'affiche parfaitement, que ce soit sur un smartphone, une tablette ou un ordinateur de bureau. Fini les multiples versions à gérer : apprenez les principes clés pour concevoir un site unique, flexible et optimisé pour le référencement. Ce livre est l\'introduction idéale pour comprendre et mettre en œuvre le design web adaptatif, et ainsi préparer vos projets pour l\'avenir du web.','Mathieu Nebra (Mateo21)',0,'covers/qu-est-ce-que-le-responsive-web-design.png','books/Qu est ce que le responsive web design.pdf',10,2013,1,5,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(128,'Empêcher le téléchargement direct de fichiers','empecher-le-telechargement-direct-de-fichiers','Maîtrisez la distribution de vos contenus en ligne et protégez-les des téléchargements directs non autorisés grâce à ce guide essentiel. Apprenez à déjouer le \"vol\" de fichiers et à maintenir l\'intégrité de vos statistiques de téléchargement, évitant ainsi que vos ressources ne soient exploitées sans votre contrôle. Ce livre vous révèle des méthodes efficaces pour sécuriser l\'accès à vos fichiers et forcer les utilisateurs à passer par votre page dédiée. Gardez une maîtrise totale sur votre propriété intellectuelle et la fréquentation de votre site web.','Noxalus',0,'covers/empecher-le-telechargement-direct-de-fichiers.png','books/Empecher le telechargement direct de fichiers.pdf',12,2011,1,4,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(129,'Partitionner son disque dur sous Vista','partitionner-son-disque-dur-sous-vista','Vous utilisez Windows Vista et rêvez d\'un disque dur mieux organisé, plus sécurisé ou capable d\'accueillir plusieurs systèmes d\'exploitation ? Ce guide pratique, conçu pour les débutants, vous dévoile étape par étape tous les secrets du partitionnement, de la préparation essentielle à la création et gestion de vos partitions. Apprenez à optimiser votre espace de stockage en toute confiance, en comprenant les intérêts et les risques, et en suivant des instructions claires pour une sécurité optimale. Maîtrisez votre machine et donnez une nouvelle dimension à votre expérience informatique sous Vista.','cedricweb',0,'covers/partitionner-son-disque-dur-sous-vista.png','books/Partitionner son disque dur sous vista.pdf',21,2011,1,6,'2026-07-29 08:53:06','2026-07-29 08:53:06'),(130,'Les Conteneurs de la STL','les-conteneurs-de-la-stl','Vous maîtrisez déjà les bases de C++ et le `std::vector`, mais souhaitez aller plus loin dans l\'optimisation de vos structures de données ? Ce livre, de niveau intermédiaire, vous plonge au cœur des conteneurs de la Standard Template Library (STL), en explorant des outils essentiels comme `std::map` et les itérateurs à travers des exemples concrets et ludiques. Découvrez comment choisir le conteneur le plus adapté à chaque scénario, des conteneurs associatifs aux adaptateurs, pour écrire un code plus performant et élégant. Une ressource indispensable pour tout développeur C++ désireux de maîtriser pleinement les capacités offertes par la STL.','Megaz',0,'covers/les-conteneurs-de-la-stl.png','books/Les conteneurs de la stl.pdf',38,2011,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(131,'Apprenez à développer en C#','apprenez-a-developper-en-c','Plongez dans l\'univers du développement C# avec ce guide complet, conçu pour vous accompagner des fondamentaux jusqu\'aux concepts les plus avancés. Que vous soyez novice ou désireux d\'approfondir vos connaissances, cet ouvrage vous guidera depuis les rudiments du langage et la mise en place de votre environnement de développement, jusqu\'à la maîtrise de la Programmation Orientée Objet (POO) et des fonctionnalités clés du framework .NET. Grâce à de nombreux exemples concrets, l\'exploration des outils essentiels comme le débogueur et des Travaux Pratiques stimulants, vous développerez des compétences solides pour concevoir des applications robustes et professionnelles.','nico.pyright',0,'covers/apprenez-a-developper-en-c.png','books/Apprenez a developper en c.pdf',382,2013,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(132,'Internet et les navigateurs','internet-et-les-navigateurs','Explorez l\'univers fascinant d\'Internet, depuis ses origines complexes et son \"Histoire (avec un grand H)\" jusqu\'à son évolution constante qui nous relie aujourd\'hui. Ce guide complet ne se contente pas de retracer cette aventure numérique ; il vous équipe également pour maîtriser les navigateurs incontournables, tels que Mozilla Firefox, Google Chrome, Safari mobile et Opera Mini. Apprenez à optimiser votre navigation, à personnaliser votre expérience et à renforcer votre sécurité en ligne grâce à des tutoriels clairs et détaillés. Que vous soyez novice ou utilisateur expérimenté, ce livre est votre passeport pour une compréhension approfondie et une utilisation efficace du Web d\'aujourd\'hui.','Blaise Barré (~Electro)',0,'covers/internet-et-les-navigateurs.png','books/Internet et les navigateurs.pdf',65,2012,1,5,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(133,'Créer des jeux textuels avec Inform 7','creer-des-jeux-textuels-avec-inform-7','Envie de créer des mondes imaginaires et des histoires interactives où le joueur est le héros ? Plongez dans l\'univers fascinant d\'Inform 7, le système moderne et puissant pour concevoir des fictions interactives, avec ce guide unique qui offre la première initiation complète en français à ce langage déclaratif innovant. De l\'installation du logiciel à la maîtrise des objets, des lieux, des scènes et des interactions, vous serez guidé étape par étape pour développer votre propre jeu textuel complet. Libérez votre créativité et préparez-vous à donner vie à des aventures captivantes, prêtes à être partagées avec le monde entier.','farvardin',0,'covers/creer-des-jeux-textuels-avec-inform-7.png','books/Creer des jeux textuels avec inform 7.pdf',21,2010,1,7,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(134,'Introduction aux algorigrammes','introduction-aux-algorigrammes','Optimisez la conception de vos programmes et anticipez les défis dès la phase de planification grâce à \"Introduction aux algorigrammes\". Ce guide essentiel vous apprendra à modéliser la logique de n\'importe quelle application avant même d\'écrire une ligne de code, et ce, quel que soit le langage de programmation que vous utilisez. Que vous travailliez seul ou en équipe, découvrez comment simplifier les structures complexes, détecter les erreurs en amont et organiser efficacement vos projets, grâce à des exemples concrets et des annexes pratiques sur les outils et alternatives.','Programpriv',0,'covers/introduction-aux-algorigrammes.png','books/Introduction aux algorigrammes.pdf',37,2012,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(135,'Effectuez vos études statistiques avec R','effectuez-vos-etudes-statistiques-avec-r','Plongez dans l\'univers de l\'analyse statistique avec ce guide pratique dédié à R, le langage de référence plébiscité par la communauté scientifique et universitaire. De l\'installation à la maîtrise de ses structures de données fondamentales comme les vecteurs, matrices et dataframes, vous apprendrez à organiser, traiter et manipuler efficacement toutes vos données. Découvrez comment appliquer divers tests statistiques, explorer les corrélations et la régression linéaire, et représenter graphiquement vos résultats pour une compréhension approfondie. Ce livre vous offre les clés pour devenir autonome et performant dans la réalisation de vos études statistiques, du traitement initial à l\'interprétation finale.','ptitlu',0,'covers/effectuez-vos-etudes-statistiques-avec-r.png','books/Effectuez vos etudes statistiques avec r.pdf',87,2011,1,6,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(136,'Les tours de Hanoï','les-tours-de-hanoi','Plongez au cœur d\'un des casse-têtes les plus fascinants de l\'histoire de l\'informatique et des mathématiques : les Tours de Hanoï. Ce livre vous invite à explorer sa formalisation légendaire et sa résolution élégante, démontrant avec brio la puissance et la concision de la récursivité. Idéal pour les développeurs et passionnés d\'algorithmique de niveau intermédiaire, il vous guidera vers une compréhension approfondie de cette technique fondamentale. Découvrez comment aborder des problèmes complexes avec une logique claire et un code puissant.','Olivier Strebler (shareman)',0,'covers/les-tours-de-hanoi.png','books/Les tours de hanoi.pdf',5,2009,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(137,'Le Camera Mapping avec Blender','le-camera-mapping-avec-blender','Plongez dans l\'univers fascinant du Camera Mapping avec Blender et apprenez à créer des rendus 3D d\'un réalisme saisissant à partir de simples photographies. Ce guide pratique de niveau intermédiaire vous révèle l\'art du \"bluff\", une technique astucieuse qui vous permet de transformer des images 2D en scènes 3D étonnantes avec un minimum de modélisation traditionnelle. Maîtrisez chaque étape, de la préparation méticuleuse de la scène à l\'optimisation des lumières et des matériaux, pour obtenir des visuels fidèles à la réalité. Idéal pour ceux qui souhaitent obtenir des résultats professionnels rapidement et facilement avec Blender.','bobo75014',0,'covers/le-camera-mapping-avec-blender.png','books/Le camera mapping avec blender.pdf',34,2012,1,7,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(138,'Construire un mode - ap / -ar','construire-un-mode-ap-ar','Donnez une nouvelle dimension à vos cartes Warcraft III grâce à ce guide essentiel ! Apprenez à construire un système de sélection de mode de jeu intelligent, offrant aux joueurs le choix entre des modes \"All Pick\" et \"All Random\" dès le début de la partie. Ce tutoriel pas à pas, accessible même avec des connaissances basiques en déclencheurs, vous permettra d\'intégrer facilement cette fonctionnalité interactive. Enrichissez vos créations et offrez une expérience de jeu personnalisée qui captivera votre audience.','MaRSiGnoU7',0,'covers/construire-un-mode-ap-ar.png','books/Construire un mode ap ar.pdf',8,2009,1,7,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(139,'Créez des applications pour Windows Phone','creez-des-applications-pour-windows-phone','La révolution de la mobilité vous passionne et vous maîtrisez le C# ? Ce livre est votre passeport pour le monde du développement d\'applications Windows Phone, en se concentrant sur les applications de gestion innovantes avec Silverlight. Du paramétrage initial de votre environnement de développement aux interactions avancées avec les services web, la géolocalisation ou l\'API Facebook, vous apprendrez à concevoir des interfaces dynamiques et à gérer les données avec expertise. Ce guide complet vous accompagnera pas à pas, intégrant une étude de cas pratique et toutes les étapes clés pour publier avec succès vos créations sur le Windows Phone Store.','nico.pyright',0,'covers/creez-des-applications-pour-windows-phone.png','books/Creez des applications pour windows phone.pdf',178,2012,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(140,'Un peu de physique en ActionScript 3','un-peu-de-physique-en-actionscript-3','Envie d\'insuffler une touche de réalisme et d\'interactivité à vos applications Flash ? Ce tutoriel vous invite à explorer les lois fondamentales de la physique pour donner vie à vos créations grâce à ActionScript 3. Vous apprendrez pas à pas à simuler des mouvements réalistes, comme la chute et le rebond d\'une balle soumise à la gravité, sans avoir besoin de maîtriser la programmation orientée objet. Idéal pour les développeurs souhaitant dynamiser leurs projets, ce guide pratique et accessible est votre porte d\'entrée vers la physique appliquée en AS3.','Paul F. (Faw)',0,'covers/un-peu-de-physique-en-actionscript-3.png','books/Un peu de physique en actionscript 3.pdf',11,2011,1,7,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(141,'C++ : Bien choisir ses structures de données','c-bien-choisir-ses-structures-de-donnees','Maximiser la performance de vos applications C++ passe inévitablement par le choix judicieux de vos structures de données. Ce guide pratique lève le voile sur les structures linéaires et arborescentes, en vous offrant une analyse claire de la complexité des opérations et des implémentations via la STL ou Boost. Que vous soyez un développeur débutant cherchant à éviter les pièges ou un expert en quête d\'un rappel, ce livre vous dotera des connaissances essentielles pour optimiser chaque ligne de code. Faites le bon choix et transformez l\'efficacité de vos algorithmes.','Olivier Strebler (shareman)',0,'covers/c-bien-choisir-ses-structures-de-donnees.png','books/C bien choisir ses structures de donnees.pdf',9,2012,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(142,'Développez vos applications web avec Symfony2 !','developpez-vos-applications-web-avec-symfony2','Fatigué du développement web complexe et de code désorganisé ? Ce guide complet vous propose de maîtriser Symfony2, le framework PHP réputé pour sa capacité à simplifier et structurer la création d\'applications web performantes. De l\'installation et la configuration de votre environnement aux concepts avancés comme la gestion des formulaires, la validation des données et l\'utilisation des services, chaque étape est abordée de manière progressive et pratique. Destiné aux développeurs intermédiaires ayant des bases solides en PHP et POO, ce livre vous permettra d\'acquérir une expertise significative et de bâtir des applications robustes, propres et efficaces.','Vincent Paulin (Genokiller)',0,'covers/developpez-vos-applications-web-avec-symfony2.png','books/Developpez vos applications web avec symfony2.pdf',59,2012,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(143,'Débutez en informatique avec Windows 8','debutez-en-informatique-avec-windows-8','Plongez dans l\'univers de l\'informatique avec \"Débutez en informatique avec Windows 8\", le guide essentiel pour maîtriser votre ordinateur dès les premiers clics. De la découverte de l\'interface Windows 8 (Metro et Bureau) à la gestion avancée des fichiers et dossiers, en passant par les applications, la personnalisation et la sécurité, ce livre couvre toutes les bases nécessaires pour une utilisation autonome et efficace. Apprenez également à naviguer sur Internet en toute confiance, à utiliser votre navigateur et à sécuriser vos connexions, pour tirer pleinement parti de toutes les opportunités offertes par le monde numérique. Idéal pour les débutants, cet ouvrage structuré et didactique vous accompagnera pas à pas pour transformer les défis techniques en succès quotidiens.','ShigeruM',0,'covers/debutez-en-informatique-avec-windows-8.png','books/Debutez en informatique avec windows 8.pdf',445,2013,1,7,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(144,'Le framework Executor','le-framework-executor','Maîtrisez la programmation concurrente en Java grâce à \"Le framework Executor\", un guide essentiel pour les développeurs déjà familiers avec les threads. Ce livre explore en profondeur l\'API Executor, introduite avec Java 5, qui simplifie considérablement la gestion des tâches parallèles sans manipuler directement les threads. Découvrez comment utiliser efficacement les pools de threads, `Callable<V>` et `Future<V>` pour structurer vos applications et améliorer leur performance. Un incontournable pour ceux qui cherchent à écrire des programmes multi-threads robustes et optimisés en toute simplicité.','Ramius',0,'covers/le-framework-executor.png','books/Le framework executor.pdf',18,2012,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(145,'[Visual C#] Utiliser les paramètres d\'application','visual-c-utiliser-les-parametres-dapplication','Vous développez en C# et cherchez une méthode simple et efficace pour stocker les données de vos applications sans recourir à une base de données ? Ce guide pratique vous plonge au cœur des paramètres d\'application, vous enseignant comment configurer, lire et écrire ces informations précieuses directement via les fichiers de configuration XML et l\'outil intégré de Visual C#. Idéal pour les débutants, il vous permettra de maîtriser la gestion des réglages et préférences de vos logiciels, qu\'ils soient en portée application ou utilisateur, pour des applications plus flexibles et personnalisables. Apprenez à donner une mémoire à vos créations C# !','Saggah',0,'covers/visual-c-utiliser-les-parametres-d-application.png','books/Visual c utiliser les parametres d application.pdf',11,2011,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(146,'Un système d\'options','un-systeme-doptions','Optimisez l\'interaction de vos programmes C grâce à \"Un système d\'options\", le guide indispensable pour implémenter une gestion robuste et efficace des arguments en ligne de commande. Ce tutoriel détaillé vous montrera comment manipuler des options courtes, longues et avec paramètres, à l\'instar des utilitaires Unix que vous côtoyez chaque jour. Vous y explorerez des techniques d\'optimisation avancées et des subtilités du langage C, incluant les casts complexes et l\'application judicieuse des tables de hachage et des listes chaînées. Donnez à vos applications la flexibilité et le professionnalisme qu\'elles méritent.','pylaterreur',0,'covers/un-systeme-d-options.png','books/Un systeme d options.pdf',11,2009,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(147,'Allocation dynamique en C - complément','allocation-dynamique-en-c-complement','Maîtrisez les subtilités de l\'allocation dynamique en C avec ce guide complémentaire, indispensable pour tout développeur souhaitant aller au-delà de `malloc()`. Explorez `calloc()` pour une initialisation automatique des zones mémoire et `realloc()` pour redimensionner vos blocs existants en toute sécurité. Grâce à des exemples concrets et des applications pratiques, notamment pour le jeu du pendu, vous acquerrez les compétences clés pour une gestion mémoire optimale. Un tutoriel clair et concis pour affiner vos connaissances en programmation C.','Adrien31100',0,'covers/allocation-dynamique-en-c-complement.png','books/Allocation dynamique en c complement.pdf',12,2011,1,7,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(148,'Les bases d\'Excel','les-bases-dexcel','Débutez votre parcours sur Excel avec un guide clair et progressif, idéal pour les débutants n\'ayant aucune connaissance préalable du logiciel. De la découverte de l\'interface et de l\'adressage des cellules à la maîtrise des fonctions de base, en passant par la création et la manipulation de tableaux et de graphiques, chaque étape est expliquée simplement. Apprenez à organiser vos données, effectuer des calculs et visualiser vos informations de manière percutante. Ce livre pratique vous offre toutes les bases nécessaires pour utiliser Excel avec aisance et confiance.','Célestin Faraday ,',0,'covers/les-bases-d-excel.png','books/Les bases d excel.pdf',21,2010,1,6,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(149,'Créez des maps pour Teeworlds !','creez-des-maps-pour-teeworlds','Envie de personnaliser Teeworlds et de jouer sur des cartes uniques ? Ce guide essentiel vous ouvre les portes de l\'éditeur, souvent déroutant, pour transformer vos idées les plus folles en terrains de jeu captivants. Apprenez pas à pas à créer des maps solides et amusantes, à maîtriser les bases de la conception visuelle et même à configurer votre propre serveur pour des parties mémorables entre amis. N\'attendez plus pour libérer votre créativité et concevoir les mondes que vous avez toujours rêvé d\'explorer !','Tanguy Zotti (Tangeek)',0,'covers/creez-des-maps-pour-teeworlds.png','books/Creez des maps pour teeworlds.pdf',23,2011,1,6,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(150,'La chimie à partir de zéro','la-chimie-a-partir-de-zero','Démystifiez la chimie dès les premières pages avec \"La chimie à partir de zéro\", le compagnon indispensable pour tous les curieux désireux d\'explorer cette science sans aucun prérequis. Loin des clichés rébarbatifs, ce guide ludique et progressif vous accompagne pas à pas, des atomes aux liaisons chimiques, pour bâtir une compréhension solide et intuitive des fondamentaux. Grâce à des explications claires, des exemples concrets et des exercices pratiques, vous assimilerez les bases essentielles tout en développant un réel plaisir d\'apprendre. Préparez-vous à découvrir que la chimie est non seulement accessible, mais surtout passionnante !','moejul',0,'covers/la-chimie-a-partir-de-zero.png','books/La chimie a partir de zero.pdf',34,2012,1,6,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(151,'Lumière sur la lumière','lumiere-sur-la-lumiere','Plongez dans le monde fascinant de la lumière avec cet ouvrage complet, qui explore toutes ses facettes, des lois fondamentales de la réfraction et de la réflexion aux mystères de la dualité onde-corpuscule et des photons. Vous voyagerez de l\'optique géométrique, avec l\'étude des lentilles et des systèmes optiques comme l\'œil, jusqu\'aux découvertes modernes sur les ondes électromagnétiques, la diffraction et l\'effet photoélectrique. S\'adressant à un public de niveau intermédiaire, « Lumière sur la lumière » démystifie des concepts parfois complexes grâce à une approche pédagogique et historique, vous invitant à comprendre les phénomènes concrets même si les calculs avancés peuvent être survolés. Une lecture éclairante pour quiconque souhaite approfondir sa compréhension de ce phénomène essentiel qui façonne notre perception du monde.','Brice Errandonea',0,'covers/lumiere-sur-la-lumiere.png','books/Lumiere sur la lumiere.pdf',82,2011,1,6,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(152,'Pratiques avancées et méconnues en Python','pratiques-avancees-et-meconnues-en-python','Destiné aux développeurs Python intermédiaires, ce livre révèle les secrets des \"pratiques avancées et méconnues\" qui transforment un bon code en un code exceptionnel. Apprenez à exploiter pleinement la puissance des générateurs, des coroutines, des list comprehensions et du module `itertools` pour écrire des programmes plus lisibles, efficaces et élégants. Passez au niveau supérieur et forgez votre expertise en Python, vous permettant de vous démarquer par un code véritablement pythonnique et optimisé.','delroth',0,'covers/pratiques-avancees-et-meconnues-en-python.png','books/Pratiques avancees et meconnues en python.pdf',13,2010,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(153,'Irssi, le client IRC du futur','irssi-le-client-irc-du-futur','Plongez dans l\'univers de l\'IRC avec Irssi, le client en mode texte qui allie puissance, convivialité et une personnalisation sans limites. Ce guide complet et accessible vous prend par la main, de l\'installation sur Linux, Windows ou Mac OS, à la maîtrise de ses fonctionnalités avancées pour une communication parfaitement adaptée à vos besoins. Apprenez à dompter son interface intuitive, à exploiter ses raccourcis clavier efficaces et à transformer radicalement votre expérience grâce à l\'ajout de thèmes et de scripts, prouvant que la console peut être synonyme de confort et de performance.','Chiantos',0,'covers/irssi-le-client-irc-du-futur.png','books/Irssi le client irc du futur.pdf',12,2011,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(154,'Tout sur l’OpenSim','tout-sur-lopensim','Plongez dans l\'univers fascinant d\'OpenSim, l\'alternative libre à Second Life, avec ce guide complet. Que vous souhaitiez explorer des mondes virtuels, interagir avec d\'autres avatars ou apprendre les bases de la construction, ce livre vous accompagnera pas à pas. Allez plus loin en découvrant comment installer et configurer votre propre monde virtuel, gérer des serveurs dédiés et même créer un site d\'accueil pour votre communauté. Maîtrisez OpenSim de l\'exploration à la création, et donnez vie à vos propres univers numériques.','acryline',0,'covers/tout-sur-l-opensim.png','books/Tout sur l opensim.pdf',122,2012,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(155,'Nous descendons tous de Gengis Khan !','nous-descendons-tous-de-gengis-khan','\"Nous descendons tous de Gengis Khan !\" Ce titre surprenant est bien plus qu\'une provocation : il révèle une vérité scientifique fascinante. À travers des calculs généalogiques simples et accessibles, ce livre déconstruit l\'idée reçue de l\'arbre généalogique parfait pour montrer l\'incroyable densité de nos liens ancestraux. Découvrez comment la loi des grands nombres nous connecte inévitablement à des figures historiques lointaines et transformez votre perception de votre propre héritage familial. Une lecture captivante qui prouve que nous sommes tous bien plus liés que nous ne l\'imaginons.','Mickaël Launay (GéoMl17)',0,'covers/nous-descendons-tous-de-gengis-khan.png','books/Nous descendons tous de gengis khan.pdf',11,2013,1,6,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(156,'Apprenez à programmer en C !','apprenez-a-programmer-en-c','Prêt à plonger dans l\'univers de la programmation ? Ce guide complet, \"Apprenez à programmer en C !\", est le compagnon idéal pour tout débutant désireux de maîtriser les bases de ce langage fondamental. De la mise en place de votre environnement de développement à la création de votre premier jeu, en passant par les variables, les conditions, les boucles et les fonctions, vous bâtirez des fondations solides et pratiques. Vous explorerez également des techniques essentielles comme la manipulation de la mémoire avec les pointeurs, les tableaux et la programmation modulaire, vous préparant ainsi à créer des applications performantes et structurées.','Mathieu Nebra (Mateo21)',0,'covers/apprenez-a-programmer-en-c.png','books/Apprenez a programmer en c.pdf',409,2013,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(157,'[C++] Les manipulateurs de flux','c-les-manipulateurs-de-flux','Fatigué des affichages bruts et peu esthétiques dans vos programmes C++ ? Ce livre vous plonge au cœur des manipulateurs de flux, des outils indispensables pour transformer vos sorties console et fichier en présentations claires et structurées. Apprenez à contrôler avec précision l\'alignement, la précision des nombres et le formatage de tous vos types de données. Élevez la lisibilité et le professionnalisme de vos applications C++ grâce à ces techniques de mise en forme puissantes et élégantes.','Matthieu Schaller (Nanoc)',0,'covers/c-les-manipulateurs-de-flux.png','books/C les manipulateurs de flux.pdf',13,2011,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(158,'L\'algèbre de Boole','lalgebre-de-boole','Démystifiez l\'algèbre de Boole avec cet ouvrage accessible, un pilier fondamental pour tout programmeur, spécialiste SQL ou concepteur électronique. Explorez les variables et opérateurs logiques, les règles de simplification essentielles, et des outils pratiques comme les tableaux de Karnaugh, pour maîtriser la logique derrière vos conditions et optimiser vos systèmes. Ce guide clair et professionnel transforme un concept en apparence complexe en un outil puissant et limpide, indispensable pour affûter vos compétences en algorithmique et en conception de circuits.','alcinos',0,'covers/l-algebre-de-boole.png','books/L algebre de boole.pdf',20,2012,1,6,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(159,'Petit guide d\'utilisation de Twitter','petit-guide-dutilisation-de-twitter','Vous entendez parler de Twitter mais ne savez pas par où commencer ? Ce guide concis est votre porte d\'entrée idéale pour explorer et maîtriser les rouages de cette plateforme incontournable. De l\'inscription à la personnalisation de votre profil, en passant par la création de tweets percutants et les interactions efficaces, chaque étape est expliquée avec clarté. Apprenez les meilleures pratiques pour maximiser votre présence en ligne et comprendre pleinement la puissance de ce réseau social, transformant ainsi votre curiosité en une utilisation avertie et stratégique.','Christophe Tafani-Dereeper (christophetd)',0,'covers/petit-guide-d-utilisation-de-twitter.png','books/Petit guide d utilisation de twitter.pdf',10,2011,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(160,'Choisissez et/ou fabriquez votre câble RJ45','choisissez-etou-fabriquez-votre-cable-rj45','Marre des câbles Ethernet inadaptés à vos besoins ? Découvrez comment choisir et fabriquer vos propres câbles RJ45 sur mesure grâce à ce guide complet et accessible. Il démystifie les caractéristiques essentielles, des paires torsadées aux types de brins et revêtements, pour vous aider à faire les bons choix techniques. Passez ensuite à l\'action avec des instructions claires pour assembler des câbles robustes, esthétiques et parfaitement adaptés à votre réseau domestique ou professionnel.','4drien',0,'covers/choisissez-et-ou-fabriquez-votre-cable-rj45.png','books/Choisissez et ou fabriquez votre cable rj45.pdf',11,2009,1,7,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(161,'Comprendre la messagerie électronique','comprendre-la-messagerie-electronique','Découvrez les secrets de la messagerie électronique grâce à cet ouvrage incontournable, qui vous emmène bien au-delà de la simple utilisation quotidienne. Explorez en profondeur les serveurs et les protocoles fondamentaux tels que SMTP, POP et IMAP, et comprenez réellement comment un e-mail est acheminé et interprété. Enrichissez vos compétences en configurant vos clients de messagerie avec aisance et en adoptant les meilleures pratiques pour lutter efficacement contre le spam et les arnaques. Ce guide pratique et détaillé vous transformera en un utilisateur averti, maîtrisant les mécanismes cachés derrière chaque envoi et réception de courrier électronique.','yoch',0,'covers/comprendre-la-messagerie-electronique.png','books/Comprendre la messagerie electronique.pdf',44,2011,1,5,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(162,'Apprenez à programmer en TI- Basic !','apprenez-a-programmer-en-ti-basic','Envie de révéler le potentiel de votre calculatrice TI en apprenant à programmer ? Ce guide complet vous accompagne pas à pas, des fondamentaux du TI-Basic à la maîtrise des concepts avancés comme les listes, les matrices et les graphismes. Grâce à des explications claires, des exercices pratiques, des TP détaillés et des codes sources complets, vous développerez rapidement vos propres programmes. Transformez votre calculatrice en un puissant outil de création et donnez vie à toutes vos idées !','mdr1',0,'covers/apprenez-a-programmer-en-ti-basic.png','books/Apprenez a programmer en ti basic.pdf',132,2013,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(163,'Apprenez la programmation fonctionnelle avec Haskell','apprenez-la-programmation-fonctionnelle-avec-haskell','Envie de maîtriser un paradigme de programmation puissant et élégant ? Ce guide complet vous plonge dans le monde de Haskell, un langage fonctionnel pur reconnu pour sa robustesse, son typage statique intelligent et son évaluation paresseuse. Idéal pour les développeurs désireux d\'élargir leurs horizons, même avec des bases en programmation, il vous accompagnera pas à pas, de l\'installation à la manipulation des types, de la récursivité aux foncteurs applicatifs. Apprenez à concevoir des applications plus sûres, plus concises et plus performantes avec un code d\'une clarté inégalée.','gnomnain',0,'covers/apprenez-la-programmation-fonctionnelle-avec-haskell.png','books/Apprenez la programmation fonctionnelle avec haskell.pdf',98,2012,1,4,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(164,'Mise en place des serveurs Apache et DNS','mise-en-place-des-serveurs-apache-et-dns','Maîtrisez l\'art de l\'administration système avec ce guide pratique dédié à la mise en place des serveurs Apache et DNS sous Linux. Apprenez à configurer les adresses IP, à gérer la résolution de noms de domaine essentielle avec un serveur DNS, et à installer Apache pour héberger efficacement vos contenus web. Le livre vous accompagnera pas à pas, de la création d\'une page HTML de test aux techniques avancées d\'hébergement virtuel par nom, port ou adresse IP. Idéal pour développer des compétences clés et rendre vos services web accessibles sur votre réseau.','wawanopoulos',0,'covers/mise-en-place-des-serveurs-apache-et-dns.png','books/Mise en place des serveurs apache et dns.pdf',15,2010,1,5,'2026-07-29 08:53:07','2026-07-29 08:53:07'),(165,'Apprenez à programmer en Actionscript 3','apprenez-a-programmer-en-actionscript-3','Plongez au cœur de l\'ActionScript 3 et maîtrisez les fondamentaux de la programmation dynamique. Ce guide complet vous accompagne pas à pas, de l\'installation des outils (Flex SDK, FlashDevelop) et de la syntaxe de base (variables, conditions, boucles) aux puissants paradigmes de la programmation orientée objet. Vous y démystifierez les concepts-clés tels que les classes, l\'encapsulation, l\'héritage et le polymorphisme, indispensables pour structurer des applications robustes. Enfin, explorez l\'art de l\'affichage interactif en manipulant les objets graphiques et l\'arbre d\'affichage, vous permettant de donner vie à des expériences visuelles percutantes pour le web ou les applications de bureau avec Adobe AIR.','Akryum ,',0,'covers/apprenez-a-programmer-en-actionscript-3.png','books/Apprenez a programmer en actionscript 3.pdf',400,2013,1,4,'2026-07-29 08:53:08','2026-07-29 08:53:08'),(166,'POV-Ray','pov-ray','Envie de créer des images de synthèse époustouflantes, comme dans vos films préférés, sans dépenser un euro ? Ce livre est votre passeport pour maîtriser POV-Ray, un moteur de rendu 3D gratuit et puissant. Du maniement des objets et des bases du langage aux textures complexes, éclairages avancés et techniques de programmation, vous serez guidé étape par étape. Transformez votre imagination en scènes réalistes, animations captivantes et œuvres d\'art numériques, que vous soyez grand débutant ou désireux d\'approfondir vos compétences.','Archipastek',0,'covers/pov-ray.png','books/Pov ray.pdf',174,2012,1,6,'2026-07-29 08:53:08','2026-07-29 08:53:08'),(167,'Programmation Perl (Modules CPAN)','programmation-perl-modules-cpan','Plongez au cœur de la programmation Perl avancée avec ce guide exhaustif dédié aux modules CPAN, essentiels pour toute application professionnelle. Apprenez à interagir avec des bases de données via le module DBI, à gérer l\'envoi et la réception d\'e-mails en utilisant les protocoles SMTP, POP3 et IMAP, et à maîtriser les interactions avec les serveurs FTP. Grâce à des explications pas à pas, des exemples concrets et des travaux pratiques, vous développerez les compétences clés pour automatiser et enrichir vos projets. Ce livre est la ressource idéale pour tout développeur souhaitant exploiter pleinement les capacités réseau et de gestion de données de Perl.','Ludovic ROLAND (Wapiti89)',0,'covers/programmation-perl-modules-cpan.png','books/Programmation perl modules cpan.pdf',97,2012,1,7,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(168,'Installer / désinstaller un ou plusieurs gestionnaires de bureau proprement (Gnome, KDE, XFCE, etc.)','installer-desinstaller-un-ou-plusieurs-gestionnaires-de-bureau-proprement-gnome-kde-xfce-etc','Envie de personnaliser votre expérience Linux et d\'explorer de nouveaux horizons visuels ? Ce guide pratique vous dévoile comment installer et désinstaller plusieurs gestionnaires de bureau. Découvrez des méthodes efficaces pour installer des environnements tels que Gnome, KDE ou XFCE, tout en assurant leur coexistence harmonieuse et une désinstallation impeccable. Fini les installations encombrantes et les désinstallations problématiques : ce tutoriel vous offre les clés pour gérer votre interface graphique Linux avec expertise et sans mauvaises surprises.','Renesis-3',0,'covers/installer-desinstaller-un-ou-plusieurs-gestionnaires-de-bureau-proprement-gnome-kde-xfce-etc.png','books/Installer desinstaller un ou plusieurs gestionnaires de bureau proprement gnome kde xfce etc.pdf',15,2011,1,7,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(169,'Une map avec Hammer !','une-map-avec-hammer','Plongez dans l\'univers de la création de niveaux avec \"Une map avec Hammer !\", le guide indispensable pour transformer vos idées en mondes virtuels captivants grâce à l\'éditeur emblématique des jeux Valve. De l\'installation et la configuration de Hammer aux techniques avancées de modelage de blocs, de gestion des textures et de création de terrains réalistes, chaque étape est expliquée avec clarté pour vous assurer une maîtrise progressive. Maîtrisez les entités interactives, les effets spéciaux, l\'intégration de l\'intelligence artificielle, et même la conception de cartes spécifiques pour Counter-Strike, donnant vie à des expériences de jeu dynamiques et immersives. Que vous soyez un débutant désireux de créer sa première map ou un moddeur expérimenté cherchant à affiner ses compétences, cet ouvrage complet vous fournit les outils et les connaissances pour repousser les limites de votre créativité.','Loulimi',0,'covers/une-map-avec-hammer.png','books/Une map avec hammer.pdf',225,2011,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(170,'Menus en onglets','menus-en-onglets','Découvrez comment concevoir des menus en onglets modernes et fonctionnels pour vos sites web grâce à cet ouvrage pratique. Conçu pour être accessible aux développeurs ayant des bases en XHTML et CSS, il vous guidera étape par étape dans l\'implémentation de la structure XHTML, le stylisme CSS professionnel et le placement précis de vos menus. Vous apprendrez également à gérer l\'onglet actif, y compris via PHP, pour offrir une expérience utilisateur dynamique et intuitive. Enrichissez l\'ergonomie de vos interfaces avec des menus en onglets soignés et efficaces.','Xavinou',0,'covers/menus-en-onglets.png','books/Menus en onglets.pdf',11,2011,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(171,'Aidez la science avec Folding@Home','aidez-la-science-avec-folding-at-home','Découvrez comment mettre la puissance inutilisée de votre ordinateur au service de la science grâce à Folding@Home. Ce guide vous plonge dans les principes du calcul distribué et du repliement des protéines, un domaine crucial pour la recherche médicale. Apprenez à installer et configurer le logiciel sur Windows, Linux ou Mac, à optimiser votre contribution et à gérer vos clients en toute simplicité. Contribuez concrètement à des découvertes scientifiques majeures, tout en maîtrisant les considérations énergétiques et pratiques.','saroumane',0,'covers/aidez-la-science-avec-folding-home.png','books/Aidez la science avec folding home.pdf',36,2013,1,6,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(172,'Synthèse sonore avec Csound','synthese-sonore-avec-csound','Découvrez l\'art de la synthèse sonore et libérez votre potentiel créatif avec Csound, un langage de programmation audio réputé pour sa puissance illimitée. Ce guide complet vous accompagne, même sans aucune connaissance préalable en programmation ou en physique, des fondamentaux théoriques du son et du traitement du signal jusqu\'à la création concrète de vos propres univers sonores. Apprenez à maîtriser Csound pour générer, traiter et assembler des sons uniques, qu\'il s\'agisse de reproduire des sonorités naturelles ou d\'inventer des paysages sonores futuristes. Plongez dans ce tutoriel exhaustif pour transformer vos idées musicales en réalité vibrante.','Kevin Leonhart',0,'covers/synthese-sonore-avec-csound.png','books/Synthese sonore avec csound.pdf',43,2011,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(173,'Apprenez la programmation avec Scala','apprenez-la-programmation-avec-scala','Découvrez la programmation avec Scala, un langage moderne, élégant et puissant, que vous soyez un débutant absolu ou un programmeur en quête de renouveau. Ce livre vous guide pas à pas, des bases de la programmation orientée objet aux concepts avancés comme le filtrage de motifs et la programmation fonctionnelle. Grâce à des exercices pratiques et des projets stimulants (incluant la création de jeux !), vous apprendrez à concevoir des programmes robustes et évolutifs. Dites adieu aux frustrations des langages plus complexes et embrassez l\'efficacité et la clarté de Scala.','Einstein++',0,'covers/apprenez-la-programmation-avec-scala.png','books/Apprenez la programmation avec scala.pdf',118,2012,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(174,'Explorez l\'espace avec Celestia !','explorez-lespace-avec-celestia','Passionné d\'astronomie ou simplement curieux de l\'Univers, embarquez pour un voyage extraordinaire sans quitter votre fauteuil grâce à Celestia ! Ce guide vous accompagne pas à pas pour maîtriser ce simulateur spatial 3D gratuit, offrant un réalisme photographique bluffant et une exploration intuitive du cosmos. Apprenez à naviguer avec aisance du système solaire aux confins de la galaxie, à manipuler le temps et à personnaliser votre expérience avec des add-ons, pour une immersion totale dans les étoiles.','Nicolas Auvray (itms)',0,'covers/explorez-l-espace-avec-celestia.png','books/Explorez l espace avec celestia.pdf',24,2011,1,7,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(175,'Le système de micro- paiement Flattr','le-systeme-de-micro-paiement-flattr','Vous êtes créateur de contenu en ligne, webmaster, photographe ou musicien, et souhaitez monnayer vos œuvres de manière simple et innovante ? Plongez dans ce guide complet dédié à Flattr, le système de micro-paiement qui permet aux internautes de soutenir facilement le contenu qu\'ils apprécient. Découvrez comment ce mécanisme novateur fonctionne, de l\'historique à son principe de partage d\'argent entre créateurs. Apprenez à intégrer Flattr à votre site via plugins ou méthodes manuelles, à gérer vos dépôts et vos gains, et offrez à votre travail la valorisation qu\'il mérite.','Frank9321',0,'covers/le-systeme-de-micro-paiement-flattr.png','books/Le systeme de micro paiement flattr.pdf',7,2011,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(176,'Utiliser le protocole IRC avec PHP','utiliser-le-protocole-irc-avec-php','Envie d\'explorer les multiples facettes de PHP au-delà du simple développement web ? Ce livre vous guide pas à pas pour maîtriser l\'interaction de vos programmes PHP avec le vénérable protocole IRC. À travers la création concrète d\'un bot de quiz, vous apprendrez à gérer les échanges réseau, structurer votre application et concevoir des scripts autonomes. Idéal pour les développeurs intermédiaires, cet ouvrage vous offre les clés pour étendre vos compétences et donner vie à des applications PHP innovantes pour les serveurs IRC.','linkboss',0,'covers/utiliser-le-protocole-irc-avec-php.png','books/Utiliser le protocole irc avec php.pdf',20,2010,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(177,'Programmez en Objective-C !','programmez-en-objective-c','Découvrez \"Programmez en Objective-C !\", le guide indispensable pour maîtriser ce langage puissant, pierre angulaire du développement sur les plateformes Apple. S\'adressant aux développeurs déjà familiarisés avec le C, cet ouvrage vous accompagnera des principes fondamentaux de l\'orienté objet, comme les classes, l\'héritage et la gestion mémoire, à l\'exploration approfondie des frameworks Foundation et Cocoa. Grâce à des explications claires, des exercices pratiques et un TP complet, vous apprendrez à concevoir des applications robustes et élégantes, de la logique interne à l\'interface graphique. Lancez-vous dans l\'aventure Objective-C et donnez une nouvelle dimension à vos compétences de programmeur.','prs513rosewood',0,'covers/programmez-en-objective-c.png','books/Programmez en objective c.pdf',91,2011,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(178,'Installer un serveur DNS avec djbdns sous debian','installer-un-serveur-dns-avec-djbdns-sous-debian','Découvrez comment bâtir une infrastructure DNS sécurisée et fiable avec djbdns sous Debian, une alternative moderne aux solutions historiques souvent sujettes aux failles. Ce guide pratique vous accompagne pas à pas, de l\'installation des paquets à la configuration de tinydns et l\'interrogation du service, expliquant chaque commande pour une compréhension approfondie. Idéal pour les administrateurs système et les professionnels du réseau souhaitant maîtriser un outil robuste et simple d\'utilisation, cet ouvrage est votre ressource pour une mise en œuvre réussie et pérenne de votre serveur DNS de domaine.','elalitte',0,'covers/installer-un-serveur-dns-avec-djbdns-sous-debian.png','books/Installer un serveur dns avec djbdns sous debian.pdf',11,2011,1,6,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(179,'Sérialisation avec Boost','serialisation-avec-boost','Maîtrisez la sérialisation en C++ avec Boost, la solution incontournable pour transformer efficacement vos objets complexes en données échangeables. Ce guide pratique vous accompagne pas à pas, de l\'installation de la bibliothèque Boost sur Windows et GNU/Linux, à l\'implémentation des techniques de sérialisation basique et non intrusive. Apprenez à gérer les cas spécifiques tels que les classes dérivées ou les pointeurs, simplifiant considérablement la persistance de données, les transferts réseau et la création de formats de fichiers. Optimisez votre code et gagnez un temps précieux grâce à la puissance et la simplicité de Boost::serialization.','Grota',0,'covers/serialisation-avec-boost.png','books/Serialisation avec boost.pdf',15,2010,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(180,'Développez vos applications web avec Django','developpez-vos-applications-web-avec-django','Vous maîtrisez Python et aspirez à créer des applications web interactives et robustes ? Ce livre est votre guide essentiel pour plonger dans l\'univers de Django, le framework Python réputé pour sa rapidité de développement et son efficacité. Apprenez pas à pas à structurer un projet complet, de la conception des modèles de données à la gestion des vues et des gabarits, pour donner vie à vos sites dynamiques. Lancez-vous et transformez vos idées en plateformes web fonctionnelles grâce à une approche claire et concrète.','Cam',0,'covers/developpez-vos-applications-web-avec-django.png','books/Developpez vos applications web avec django.pdf',28,2012,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(181,'Les Bookmarklets ou comment modifier la page d\'un site depuis la barre d\'adresse','les-bookmarklets-ou-comment-modifier-la-page-dun-site-depuis-la-barre-dadresse','Vous rêvez de personnaliser n\'importe quelle page web, d\'automatiser des tâches répétitives ou d\'accéder à des informations cachées d\'un simple clic ? Ce livre vous initie aux bookmarklets, de puissants scripts JavaScript qui s\'exécutent directement depuis votre barre d\'adresse ou vos favoris, transformant votre navigateur en un véritable outil sur mesure. Apprenez facilement à désactiver les protections anti-clic droit, afficher le code HTML généré par JavaScript, ou pré-remplir des formulaires en un instant, et reprenez le contrôle total de votre navigation en ligne. Découvrez comment rendre le web plus interactif et plus utile, que vous soyez développeur ou simple utilisateur curieux.','Xavier MONTILLET (xavierm02)',0,'covers/les-bookmarklets-ou-comment-modifier-la-page-d-un-site-depuis-la-barre-d-adresse.png','books/Les bookmarklets ou comment modifier la page d un site depuis la barre d adresse.pdf',16,2011,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(182,'Développez vos applications 3D avec OpenGL 3.3','developpez-vos-applications-3d-avec-opengl-33','Plongez au cœur du développement 3D avec OpenGL 3.3 grâce à ce guide exhaustif et pratique, conçu pour transformer vos idées en applications visuellement époustouflantes. De l\'installation des outils essentiels à la création de scènes complexes, vous explorerez les fondamentaux de la programmation graphique, incluant la gestion des matrices, des textures et des caméras. L\'ouvrage vous mènera ensuite vers des notions avancées telles que l\'utilisation des shaders (GLSL), des VBO et des VAO, pour une maîtrise complète des techniques modernes. Idéal pour concrétiser vos projets de jeux ou de simulations, ce livre vous accompagnera pas à pas vers l\'autonomie en développement 3D.','Boouh',0,'covers/developpez-vos-applications-3d-avec-opengl-3-3.png','books/Developpez vos applications 3d avec opengl 3 3.pdf',593,2013,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(183,'Les requêtes HTTP','les-requetes-http','Découvrez les secrets derrière le \"http://\" de vos navigateurs grâce à ce guide essentiel sur les requêtes HTTP. Ce livre démystifie le protocole de communication client-serveur, vous plongeant au cœur des échanges de données avec des explications claires sur la syntaxe des requêtes, les méthodes clés comme GET, POST et HEAD, ainsi que les en-têtes et le corps des messages. Idéal pour les débutants, il vous offre une compréhension solide et pratique du fonctionnement interne du web, des bases aux mécanismes essentiels de communication.','anonymousguest',0,'covers/les-requetes-http.png','books/Les requetes http.pdf',9,2012,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(184,'Présentation de bibliothèque SDL en Java','presentation-de-bibliotheque-sdl-en-java','Découvrez comment donner vie à vos idées de jeux 2D et d\'applications graphiques avec la bibliothèque SDL, le tout en Java ! Ce guide pratique vous accompagne pas à pas, de l\'installation et la configuration de votre projet à la gestion des graphiques, du son et des interactions utilisateur. Idéal pour les développeurs Java souhaitant explorer la création de jeux ou enrichir leurs applications avec des fonctionnalités multimédias. Transformez vos compétences Java en créations interactives et visuellement attrayantes grâce à la puissance de SDL.','demonixis',0,'covers/presentation-de-bibliotheque-sdl-en-java.png','books/Presentation de bibliotheque sdl en java.pdf',67,2012,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(185,'Le typage : présentation thématique et historique','le-typage-presentation-thematique-et-historique','Plongez au cœur du typage, ce concept fondamental qui façonne l\'architecture de tous les langages de programmation. Cet ouvrage propose une exploration thématique et historique approfondie, décryptant les raisons de son apparition, ses différentes formes – des langages statiques aux dynamiques – et ses fonctionnalités avancées comme l\'inférence ou le polymorphisme. Découvrez comment le typage garantit la sûreté de vos codes et ajoute du sens à vos programmes, enrichissant ainsi votre compréhension globale des pratiques de développement.','bluestorm',0,'covers/le-typage-presentation-thematique-et-historique.png','books/Le typage presentation thematique et historique.pdf',14,2009,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(186,'Mécanique de zéro','mecanique-de-zero','Plongez dans le monde fascinant de la mécanique avec \"Mécanique de zéro\", un ouvrage conçu pour vous faire maîtriser les lois du mouvement et prévoir la trajectoire des objets, même sans connaissances préalables. De l\'historique des interactions aux lois de Newton, en passant par les vecteurs et les forces, ce guide complet combine théorie, exercices pratiques et même des expérimentations pour solidifier vos acquis. Vous y développerez une compréhension intuitive des concepts physiques complexes, abordant les aspects mathématiques avec une approche didactique, pour finalement décrypter des phénomènes allant du lancement de fusées aux trajectoires sportives. Idéal pour les débutants désireux de transformer leur curiosité en savoir-faire concret.','Romain Porte (MicroJoe) ,',0,'covers/mecanique-de-zero.png','books/Mecanique de zero.pdf',78,2012,1,6,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(187,'Hébergez vos projets web dans le cloud avec Windows Azure','hebergez-vos-projets-web-dans-le-cloud-avec-windows-azure','Le cloud computing vous intrigue et vous souhaitez héberger vos projets web sans les tracas de la gestion serveur ? Ce livre est votre guide essentiel pour comprendre et maîtriser Windows Azure, la puissante plateforme d\'hébergement de Microsoft. Vous apprendrez à déployer vos applications avec agilité, depuis la configuration initiale jusqu\'à l\'hébergement de CMS populaires comme WordPress et Orchard, en tirant pleinement parti de la flexibilité et de la disponibilité offertes. Concentrez-vous sur le développement de vos applications web, tandis qu\'Azure assure leur performance et leur scalabilité.','Matthieu Denis (MastaKillah)',0,'covers/hebergez-vos-projets-web-dans-le-cloud-avec-windows-azure.png','books/Hebergez vos projets web dans le cloud avec windows azure.pdf',59,2013,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(188,'Les images en 3D','les-images-en-3d','Envie de transformer votre écran 2D en une fenêtre sur la troisième dimension, comme un véritable \"home futuroscope\" ? Ce guide captivant vous plonge dans l\'art de créer des images 3D, en explorant les mécanismes de la vision stéréoscopique et son histoire fascinante. Découvrez pas à pas des techniques accessibles comme les anaglyphes, avec des explications claires, des exercices pratiques et des applications concrètes. Que vous soyez débutant ou simple curieux, ce livre vous offre toutes les clés pour maîtriser la 3D fixe et animée, et donner vie à vos créations en relief.','Clément Maliet (Clemsip)',0,'covers/les-images-en-3d.png','books/Les images en 3d.pdf',21,2012,1,6,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(189,'Créez vos diaporamas en LaTeX avec Beamer !','creez-vos-diaporamas-en-latex-avec-beamer','Découvrez comment créer des diaporamas professionnels et visuellement impeccables grâce à LaTeX Beamer, l\'alternative puissante et flexible aux outils de présentation traditionnels. Ce guide complet vous mène des fondamentaux, comme l\'installation et la création de slides basiques, jusqu\'aux techniques de personnalisation avancées incluant les thèmes, les couleurs et l\'intégration multimédia. Idéal pour les utilisateurs ayant une connaissance minimale de LaTeX, il vous permettra de transformer vos exposés en présentations percutantes et sophistiquées.','Rudy de Visscher (Spader)',0,'covers/creez-vos-diaporamas-en-latex-avec-beamer.png','books/Creez vos diaporamas en latex avec beamer.pdf',127,2012,1,6,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(190,'La vérité sur les tableaux et pointeurs en C','la-verite-sur-les-tableaux-et-pointeurs-en-c','Oubliez ce que vous pensiez savoir sur les tableaux et les pointeurs en C ! Ce livre plonge au cœur des malentendus courants pour vous révéler la \"vérité nue\" qui échappe souvent aux tutoriels classiques. Fini les approximations et les erreurs déroutantes du compilateur : de la représentation en mémoire aux conversions implicites complexes, en passant par les subtilités des paramètres de fonction, chaque concept est décortiqué avec précision. Que vous soyez confronté à des avertissements incompréhensibles ou que vous cherchiez simplement à maîtriser parfaitement ces mécanismes fondamentaux, cette lecture est indispensable pour écrire du code C robuste et sans ambiguïté.','Marc Mongenet',0,'covers/la-verite-sur-les-tableaux-et-pointeurs-en-c.png','books/La verite sur les tableaux et pointeurs en c.pdf',15,2011,1,5,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(191,'Utilisez MacPorts !','utilisez-macports','Vous souhaitez étendre les capacités de votre Mac en installant des logiciels plus avancés ou spécifiques, mais vous êtes confronté aux complexités de la compilation et des dépendances ? Découvrez MacPorts, l\'outil incontournable qui transforme l\'installation, la mise à jour et la gestion de ces programmes en un jeu d\'enfant. Ce guide pratique vous accompagne pas à pas pour maîtriser ce puissant gestionnaire de paquets, vous permettant d\'accéder sans effort à un vaste catalogue de logiciels open source et de simplifier radicalement votre expérience macOS. Prenez le contrôle total de vos applications et libérez le plein potentiel de votre machine.','prs513rosewood',0,'covers/utilisez-macports.png','books/Utilisez macports.pdf',13,2010,1,5,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(192,'Débutez dans la 3D avec Blender','debutez-dans-la-3d-avec-blender','Envie de créer vos propres univers 3D sans aucune connaissance préalable ? Ce guide est votre porte d\'entrée idéale pour maîtriser Blender, le logiciel libre de référence qui équipe les professionnels. Du maniement de l\'interface aux techniques de modélisation avancées, en passant par l\'éclairage réaliste, les textures, l\'animation de personnages et la simulation de fluides, chaque étape est abordée de manière progressive. Grâce à des explications claires et de nombreux travaux pratiques, vous apprendrez à donner vie à vos créations, des scènes les plus simples aux rendus les plus impressionnants, jusqu\'à l\'initiation à la création de mini-jeux vidéo.','aerodark',0,'covers/debutez-dans-la-3d-avec-blender.png','books/Debutez dans la 3d avec blender.pdf',331,2012,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(193,'La saisie sécurisée avec scanf ?','la-saisie-securisee-avec-scanf','Oubliez les préjugés sur l\'insécurité de `scanf()` ! Ce livre provocateur, \"La saisie sécurisée avec scanf ?\", vous invite à redécouvrir en profondeur cette fonction essentielle de la programmation C. Loin des approximations habituelles, explorez comment maîtriser ses formats, son tampon et prévenir les dépassements, transformant `scanf()` en un outil rapide, puissant et sécurisé pour vos applications. Un guide indispensable pour les développeurs C désireux d\'écrire du code fiable et performant.','Link/DD',0,'covers/la-saisie-securisee-avec-scanf.png','books/La saisie securisee avec scanf.pdf',10,2012,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(194,'Le backtracking par l\'exemple : résoudre un sudoku','le-backtracking-par-lexemple-resoudre-un-sudoku','Découvrez le backtracking, une technique de programmation essentielle pour résoudre des problèmes complexes de satisfaction de contraintes. Ce livre vous guide pas à pas à travers l\'exemple stimulant de la résolution de Sudoku par ordinateur, transformant un brute-force naïf en un algorithme efficace et élégant. Idéal pour les développeurs souhaitant approfondir leurs compétences en récursivité, il propose une approche pratique pour maîtriser cette méthode puissante et optimiser l\'exploration de solutions logicielles.','l\'exemple : résoudre',0,'covers/le-backtracking-par-l-exemple-resoudre-un-sudoku.png','books/Le backtracking par l exemple resoudre un sudoku.pdf',13,2011,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(195,'Sensibilisation sur le choix d\'un mot de passe','sensibilisation-sur-le-choix-dun-mot-de-passe','Fatigué des conseils génériques sur les mots de passe qui ne vous expliquent jamais le *pourquoi* ? Cet ouvrage vous offre une plongée concrète dans les méthodes d\'attaque par force brute, de la génération exhaustive au dictionnaire, pour révéler la surprenante facilité avec laquelle un mot de passe faible peut être compromis. Grâce à des exemples percutants, vous comprendrez enfin pourquoi la longueur et la complexité sont cruciales, et saurez comment choisir un mot de passe véritablement imprenable. Une lecture essentielle pour quiconque souhaite renforcer efficacement sa sécurité numérique.','Aerhus',0,'covers/sensibilisation-sur-le-choix-d-un-mot-de-passe.png','books/Sensibilisation sur le choix d un mot de passe.pdf',6,2009,1,7,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(196,'Parcourir les dossiers avec dirent.h','parcourir-les-dossiers-avec-direnth','Maîtrisez l\'exploration et la manipulation des répertoires en langage C grâce à ce guide complet, qui vous plonge au cœur de la bibliothèque `dirent.h`. De l\'ouverture et la fermeture à la lecture des fichiers et la gestion des erreurs, vous apprendrez à naviguer avec aisance, en comprenant les spécificités de portabilité entre systèmes POSIX et Windows. Illustré par du code commenté, des exemples concrets et des exercices pratiques, cet ouvrage est indispensable pour tout programmeur C souhaitant interagir efficacement avec la structure de ses dossiers.','Monsieur_JaKy',0,'covers/parcourir-les-dossiers-avec-dirent-h.png','books/Parcourir les dossiers avec dirent h.pdf',16,2009,1,7,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(197,'Les dimensions en géométrie','les-dimensions-en-geometrie','Vous avez sûrement déjà entendu parler de cinéma en 2D ou en 3D, mais savez-vous ce que signifie réellement une dimension ? Cet ouvrage est une introduction limpide et sans prérequis à la géométrie, partant du point zéro pour explorer les bases fondamentales de notre espace. Au-delà des concepts classiques (0D, 1D, 2D, 3D), préparez-vous à être émerveillé par les figures fractales aux dimensions non entières et à vous aventurer dans les mystères de la quatrième dimension. Apprenez à mesurer les figures, jonglez avec les unités, et mettez vos connaissances à l\'épreuve grâce à un chapitre d\'énigmes stimulant.','Mickaël Launay (GéoMl17)',0,'covers/les-dimensions-en-geometrie.png','books/Les dimensions en geometrie.pdf',61,2012,1,6,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(198,'Présentez des diaporamas avec PowerPoint','presentez-des-diaporamas-avec-powerpoint','Plongez au cœur de PowerPoint avec ce guide exhaustif et transformez vos idées en présentations captivantes. Des fondamentaux du logiciel à la création de diaporamas percutants intégrant textes, illustrations, médias dynamiques et animations, chaque étape est clairement expliquée. Maîtrisez la collaboration, personnalisez votre interface et exploitez les fonctions avancées comme les macros pour livrer des messages professionnels avec impact et créativité.','Blaise Barré (~Electro)',0,'covers/presentez-des-diaporamas-avec-powerpoint.png','books/Presentez des diaporamas avec powerpoint.pdf',156,2012,1,6,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(199,'Apprenez à utiliser SolidWorks','apprenez-a-utiliser-solidworks','Maîtrisez SolidWorks de A à Z avec ce guide complet, conçu pour les débutants désireux de se lancer dans la modélisation 3D sans aucune connaissance préalable. De la création d\'esquisses aux assemblages complexes, en passant par la modélisation volumique, surfacique, la tôlerie et même l\'animation, chaque fonctionnalité essentielle du logiciel est abordée de manière progressive. Enrichi de nombreux exercices pratiques et de Travaux Pratiques, ce livre vous permettra de développer rapidement vos compétences pour des projets personnels ou professionnels, et de créer des designs réalistes grâce au rendu PhotoView.','Romain Ginestou (Romaingin)',0,'covers/apprenez-a-utiliser-solidworks.png','books/Apprenez a utiliser solidworks.pdf',257,2013,1,6,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(200,'Mettez des accents dans vos programmes avec le type wchar_t','mettez-des-accents-dans-vos-programmes-avec-le-type-wchar-t','Frustré par l\'incapacité de vos programmes C à afficher correctement les accents et les caractères spéciaux ? Découvrez comment le type `wchar_t`, introduit avec la norme C99, révolutionne la gestion des textes dans vos applications. Ce guide pratique vous mènera de l\'histoire des encodages à la configuration de votre compilateur, vous permettant de créer des logiciels véritablement internationaux et agréables à utiliser. Ne laissez plus les limitations du type `char` entraver vos projets : adoptez `wchar_t` et libérez tout le potentiel multilingue de votre code.','zarthur',0,'covers/mettez-des-accents-dans-vos-programmes-avec-le-type-wchar-t.png','books/Mettez des accents dans vos programmes avec le type wchar t.pdf',15,2011,1,6,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(201,'Dynamisez vos sites web avec Javascript !','dynamisez-vos-sites-web-avec-javascript','Découvrez comment transformer vos sites web statiques en expériences interactives et captivantes grâce à \"Dynamisez vos sites web avec Javascript !\". Ce guide essentiel vous accompagne pas à pas, des fondamentaux du langage comme les variables et les fonctions, jusqu\'à la manipulation avancée du DOM et la gestion des événements. Enrichi de nombreux exercices pratiques et travaux dirigés, il vous permettra d\'acquérir les compétences indispensables pour créer des interfaces utilisateur dynamiques. Maîtrisez JavaScript et donnez vie à toutes vos idées de développement web.','Johann Pardanaud (Nesk)',0,'covers/dynamisez-vos-sites-web-avec-javascript.png','books/Dynamisez vos sites web avec javascript.pdf',377,2012,1,4,'2026-07-29 08:53:12','2026-07-29 08:53:12'),(202,'La cryptographie asymétrique : RSA','la-cryptographie-asymetrique-rsa','Découvrez les secrets derrière la sécurisation de vos transactions et communications en ligne grâce à la cryptographie asymétrique. Ce guide essentiel vous plonge au cœur du système RSA, l\'algorithme asymétrique omniprésent, en démystifiant son fonctionnement théorique, de la création des clés aux mécanismes de chiffrement et de déchiffrement. Au-delà de la théorie, il vous guide pas à pas dans l\'implémentation concrète d\'un programme de chiffrement en C++ grâce à la puissante bibliothèque GMP, essentielle pour manipuler les grands nombres. Que vous soyez un développeur curieux ou un étudiant en informatique, ce livre est votre passeport pour maîtriser l\'un des piliers de la cybersécurité moderne.','Simon Chabot (chabotsi)',0,'covers/la-cryptographie-asymetrique-rsa.png','books/La cryptographie asymetrique rsa.pdf',23,2010,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(203,'Qt : Quelques fonctionnalités non- GUI','qt-quelques-fonctionnalites-non-gui','Découvrez les facettes méconnues et pourtant essentielles de Qt, bien au-delà de la création d\'interfaces graphiques ! Ce livre vous guidera dans l\'intégration sécurisée de vos ressources directement dans vos exécutables, l\'implémentation de fonctions de hachage pour renforcer la sécurité de vos données, et l\'optimisation de la gestion d\'informations via les tables de hachage. À travers des explications claires et un projet pratique, maîtrisez des fonctionnalités clés pour développer des applications Qt robustes, portables et professionnelles sur toutes les plateformes. Essentiel pour tout développeur souhaitant exploiter pleinement la puissance de Qt.','tobast',0,'covers/qt-quelques-fonctionnalites-non-gui.png','books/Qt quelques fonctionnalites non gui.pdf',67,2011,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(204,'Créer une UserBar avec GIMP','creer-une-userbar-avec-gimp','Envie d\'exprimer votre personnalité sur les forums avec des images uniques et percutantes ? Ce guide pratique vous initie pas à pas à la création de UserBars personnalisées à l\'aide de GIMP, le logiciel de retouche graphique gratuit et puissant. Conçu pour les débutants, ce livre vous accompagnera de l\'installation de GIMP jusqu\'à la maîtrise des calques, dégradés et effets d\'éclairage pour réaliser des créations variées. Apprenez également des astuces essentielles pour optimiser votre travail et découvrez des raccourcis qui rendront votre expérience graphique fluide et intuitive.','@lex 3001',0,'covers/creer-une-userbar-avec-gimp.png','books/Creer une userbar avec gimp.pdf',34,2011,1,7,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(205,'Rédigez en Markdown !','redigez-en-markdown','Simplifiez radicalement votre manière de rédiger pour le web avec \"Rédigez en Markdown !\" de Mathieu Nebra. Ce guide accessible vous ouvre les portes d\'un langage de balisage léger et puissant, idéal pour structurer sans effort vos messages de forum, documentations techniques ou contenus de site web, sans jamais manipuler une seule balise HTML complexe. Apprenez en un clin d\'œil à créer des textes clairs, professionnels et impactants grâce à une syntaxe intuitive qui transformera votre productivité. Maîtrisez Markdown et écrivez plus vite, plus proprement, sur toutes les plateformes qui comptent !','Mathieu Nebra (Mateo21)',0,'covers/redigez-en-markdown.png','books/Redigez en markdown.pdf',14,2013,1,5,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(206,'La gestion des erreurs en C','la-gestion-des-erreurs-en-c','En tant que développeur C intermédiaire, vous savez que la simple gestion des retours de fonction ne suffit plus face à la complexité des erreurs. Ce livre vous guide pas à pas, de la maîtrise des outils standards comme `stderr` et `errno`, aux débats cruciaux sur la remontée des erreurs et l\'usage judicieux des sauts non-locaux. Allez au-delà des conventions en apprenant à bâtir votre propre bibliothèque de gestion des erreurs, intégrant des diagnostics avancés comme la génération de stacktraces et un système `errno` étendu pour une robustesse inédite de vos applications. Transformez votre approche de la programmation C en dotant vos projets d\'un système de gestion d\'erreurs infaillible et élégant.','Lucas Pesenti (Lucas-84)',0,'covers/la-gestion-des-erreurs-en-c.png','books/La gestion des erreurs en c.pdf',31,2012,1,7,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(207,'Google Maps JavaScript API V3','google-maps-javascript-api-v3','Plongez dans le monde de la cartographie interactive avec ce tutoriel dédié à l\'API Google Maps JavaScript V3. Vous y apprendrez à afficher et personnaliser des cartes, en maîtrisant les options essentielles d\'affichage, de zoom et de type de carte. Le guide vous accompagnera ensuite dans la création d\'overlays variés comme les marqueurs, polylignes et polygones, et vous montrera comment gérer les interactions utilisateur via les événements souris pour une expérience dynamique. Idéal pour les développeurs souhaitant intégrer des fonctionnalités de géolocalisation avancées à leurs applications web.','aymensan',0,'covers/google-maps-javascript-api-v3.png','books/Google maps javascript api v3.pdf',11,2012,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(208,'Site épinglé avec Internet Explorer','site-epingle-avec-internet-explorer','Transformez vos sites web en applications Windows immersives et interactives avec ce guide complet dédié aux sites épinglés d\'Internet Explorer. Explorez toutes les facettes de la personnalisation, des métadonnées d\'installation aux listes de raccourcis dynamiques et aux notifications en temps réel, sans oublier les barres d\'outils enrichies directement sur la barre des tâches. Idéal pour les développeurs souhaitant créer une expérience utilisateur unique et profondément intégrée, ce livre vous fournit les outils pour aller bien au-delà d\'une simple page web.','warpShadow',0,'covers/site-epingle-avec-internet-explorer.png','books/Site epingle avec internet explorer.pdf',19,2012,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(209,'Introduction à la vision par ordinateur','introduction-a-la-vision-par-ordinateur','Plongez dans l\'univers captivant de la vision par ordinateur et conférez aux machines la capacité d\'interpréter le monde visuel ! Cet ouvrage propose une introduction complète aux notions fondamentales du traitement d\'images et de flux vidéo, vous guidant pas à pas de la représentation des pixels aux techniques d\'analyse avancées. Grâce au langage C et à la bibliothèque OpenCV, vous acquerrez les compétences pratiques pour développer des applications de reconnaissance de formes, de détection de mouvement et bien d\'autres défis passionnants.','ordinateur',0,'covers/introduction-a-la-vision-par-ordinateur.png','books/Introduction a la vision par ordinateur.pdf',55,2012,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(210,'Introduction à la logique floue','introduction-a-la-logique-floue','La logique floue, une extension fascinante de la logique classique, permet de modéliser l\'imprécision et l\'incertitude du monde réel, se rapprochant ainsi de la flexibilité du raisonnement humain. Des jeux vidéo aux pilotes automatiques en passant par votre micro-onde, ses applications concrètes sont omniprésentes, souvent sans même que vous le sachiez ! Ce livre vous guidera à travers les notions fondamentales, des ensembles classiques aux systèmes d\'inférence floue, illustrées par un exemple pratique et cohérent sur la décision d\'un pourboire. Idéal pour les développeurs et les curieux de niveau intermédiaire, il offre une introduction claire et structurée pour maîtriser cette approche essentielle de l\'IA.','Franck Dernoncourt',0,'covers/introduction-a-la-logique-floue.png','books/Introduction a la logique floue.pdf',17,2012,1,6,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(211,'Créer des GIF animés','creer-des-gif-animes','Découvrez comment transcender les limites de la librairie GD pour créer vos propres GIF animés dynamiques en PHP. Grâce à l\'intégration de la puissante classe GIFEncoder, ce guide pratique vous dévoile une méthode pas à pas pour construire vos animations image par image, du squelette de script aux exemples concrets. Destiné aux développeurs PHP de niveau intermédiaire, cet ouvrage vous offre les clés pour donner vie à vos projets web avec des bannières personnalisées ou des flux RSS visuels et engageants. Préparez-vous à maîtriser l\'art de l\'animation web avec élégance et efficacité.','Phoenix76',0,'covers/creer-des-gif-animes.png','books/Creer des gif animes.pdf',12,2010,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(212,'Ajouter une ville et une région à Médiéval II : Total War','ajouter-une-ville-et-une-region-a-medieval-ii-total-war','Passionné par Médiéval II : Total War et désireux d\'ajouter votre propre ville ou région à la carte du jeu ? Découvrez comment réaliser ce rêve de manière légale et sans modifier l\'installation de base grâce à ce guide complet. De la préparation des outils (unpack, logiciels) à la création graphique, en passant par le codage et le lancement de votre mod, chaque étape est expliquée avec précision. Conçu pour un public de niveau intermédiaire mais partant de zéro, il aborde toutes les particularités techniques, y compris les spécificités des systèmes d\'exploitation (XP, Vista/Seven) et des versions du jeu (vanilla ou Kingdoms). Préparez-vous à personnaliser votre expérience et à forger un nouveau destin pour vos territoires préférés !','Amàndil',0,'covers/ajouter-une-ville-et-une-region-a-medieval-ii-total-war.png','books/Ajouter une ville et une region a medieval ii total war.pdf',21,2012,1,7,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(213,'Un menu horizontal','un-menu-horizontal','Optimisez l\'ergonomie et l\'esthétique de votre site web avec ce guide concis sur la création de menus horizontaux. Vous y apprendrez à structurer vos menus en XHTML de manière sémantique et à les mettre en forme avec les propriétés CSS `display: inline` ou `float` pour une navigation fluide et un design professionnel. Idéal pour les développeurs souhaitant enrichir leurs compétences en XHTML/CSS, ce tutoriel \"facile\" vous donnera les clés pour des menus intuitifs et élégants.','neoxx78',0,'covers/un-menu-horizontal.png','books/Un menu horizontal.pdf',8,2011,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(214,'Lecture et écriture de fichiers en mode binaire','lecture-et-ecriture-de-fichiers-en-mode-binaire','Vous maîtrisez la lecture et l\'écriture de fichiers texte en C ? Ce livre est votre prochaine étape pour une gestion des données avancée. Découvrez le pouvoir du mode binaire avec `fwrite` et `fread`, des fonctions essentielles pour stocker et récupérer directement des variables, tableaux et structures, offrant une simplicité et une performance inégalées. Apprenez à manipuler efficacement vos données en mémoire pour optimiser vos applications.','uknow',0,'covers/lecture-et-ecriture-de-fichiers-en-mode-binaire.png','books/Lecture et ecriture de fichiers en mode binaire.pdf',15,2010,1,10,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(215,'Programmation objet avancée : la conception avant tout (design patterns à l\'emploi)','programmation-objet-avancee-la-conception-avant-tout-design-patterns-a-lemploi','Pour les développeurs désireux de dépasser les bases de la programmation orientée objet, cet ouvrage vous guide vers une maîtrise avancée de la conception logicielle. Il met l\'accent sur les principes essentiels du paradigme objet, souvent sous-estimés, pour créer des applications robustes et facilement maintenables. Vous y découvrirez l\'application concrète de design patterns incontournables, illustrés avec des exemples génériques en C++ et Java, afin de structurer votre code avec élégance et efficacité. Adoptez une philosophie de la conception qui transformera durablement votre approche du développement.','Michaël Haberzettel (devil may cry)',0,'covers/programmation-objet-avancee-la-conception-avant-tout-design-patterns-a-l-emploi.png','books/Programmation objet avancee la conception avant tout design patterns a l emploi.pdf',68,2012,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(216,'[C++] Déboguer avec Code::Blocks','c-deboguer-avec-codeblocks','Vous en avez assez des programmes C++ (ou C) qui compilent mais plantent de manière inexplicable à l\'exécution, vous laissant démuni face à des bogues invisibles ? Ce guide pratique vous plonge au cœur du débogage avec Code::Blocks, en vous apprenant à exploiter toute la puissance du dévermineur GDB intégré. Découvrez comment identifier avec précision la ligne de l\'erreur, connaître la valeur de vos variables au moment du plantage et résoudre efficacement les problèmes les plus complexes, sans recourir à des méthodes fastidieuses. Transformez la frustration en expertise et rendez votre code robuste et fiable grâce à des techniques de débogage professionnelles.','Matthieu Schaller (Nanoc)',0,'covers/c-deboguer-avec-code-blocks.png','books/C deboguer avec code blocks.pdf',11,2011,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(217,'Créer un dépôt Launchpad','creer-un-depot-launchpad','Vous avez développé un programme innovant et souhaitez le partager avec le plus grand nombre ? Ce guide essentiel vous accompagne pas à pas dans la création de votre dépôt Launchpad, la plateforme idéale pour une diffusion efficace de vos logiciels. Apprenez à configurer votre compte, gérer vos clés PGP et empaqueter vos applications, offrant ainsi à vos utilisateurs la possibilité d\'installations et mises à jour aisées via `apt-get`. Un tutoriel indispensable pour tout développeur souhaitant maîtriser la distribution de ses créations sur l\'écosystème Ubuntu et Debian.','Skit',0,'covers/creer-un-depot-launchpad.png','books/Creer un depot launchpad.pdf',14,2011,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(218,'Initiation à la création d\'un design extensible','initiation-a-la-creation-dun-design-extensible','Plongez dans l\'univers du développement web et apprenez à concevoir des sites qui s\'adaptent harmonieusement à toutes les tailles d\'écran de vos visiteurs. Cet ouvrage vous guide pas à pas, des fondamentaux théoriques sur les définitions d\'écran et la distinction entre design fixe et extensible, jusqu\'aux techniques concrètes de centrage et d\'alignement. Maîtrisez la création d\'un design fluide et professionnel, garantissant une expérience utilisateur optimale sur n\'importe quel support. Prérequis : une connaissance des bases du XHTML/CSS.','Bob-le-zéro',0,'covers/initiation-a-la-creation-d-un-design-extensible.png','books/Initiation a la creation d un design extensible.pdf',18,2011,1,5,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(219,'Les acides aminés','les-acides-amines','Plongez au cœur des molécules fondamentales du vivant avec \"Les acides aminés\", un guide essentiel pour explorer ces bâtisseurs cruciaux des protéines. Cet ouvrage vous mènera des rappels de stéréoisomérie aux applications médicales et aux classifications détaillées, en passant par leur rôle indispensable dans la synthèse protéique. Conçu pour les étudiants et passionnés de biochimie (niveau Bac minimum), il offre une approche claire et structurée pour maîtriser ces composés organiques aux multiples facettes. Démystifiez la chimie du vivant et saisissez l\'importance capitale des acides aminés dans le fonctionnement cellulaire et la santé.','MMACORP',0,'covers/les-acides-amines.png','books/Les acides amines.pdf',38,2011,1,6,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(220,'Mise en Page avec InDesign','mise-en-page-avec-indesign','Vous rêvez de réaliser des mises en page professionnelles sans être un expert ? Ce guide pratique est conçu pour vous accompagner, pas à pas, dans la maîtrise d\'InDesign, le logiciel incontournable de la Publication Assistée par Ordinateur (PAO). De la théorie fondamentale aux projets concrets, comme la création d\'une carte de visite ou d\'une maquette de magazine, vous explorerez les bases de la typographie et de l\'organisation visuelle. Mettez votre créativité au service de documents impactants et apprenez à concevoir des mises en page professionnelles, même en partant de zéro.','Dakadak',0,'covers/mise-en-page-avec-indesign.png','books/Mise en page avec indesign.pdf',51,2011,1,5,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(221,'La reconnaissance vocale dans son application','la-reconnaissance-vocale-dans-son-application','Maîtrisez l\'art d\'intégrer la reconnaissance vocale dans vos applications grâce à ce guide pratique et détaillé. Conçu pour les développeurs C# de niveau intermédiaire, ce livre comble un vide en vous enseignant la mise en œuvre pas à pas de l\'ASR (Automatic Speech Recognition) via Windows Speech Recognition. Vous apprendrez à structurer votre projet, configurer le moteur vocal et créer des commandes personnalisées pour des interfaces utilisateur innovantes. Ouvrez la voie à des applications plus intuitives et accessibles en dotant vos créations de la puissance de la parole.','janulrich00001',0,'covers/la-reconnaissance-vocale-dans-son-application.png','books/La reconnaissance vocale dans son application.pdf',14,2009,1,5,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(222,'Faites parler vos applications en .NET','faites-parler-vos-applications-en-net','Envie de transcender la communication textuelle de vos applications .NET ? Ce livre vous guide pas à pas pour intégrer le Text-to-Speech et permettre à vos logiciels de s\'exprimer en C# et VB.NET. Vous apprendrez à concevoir des interfaces intuitives, à implémenter la synthèse vocale avec des méthodes synchrones ou asynchrones, et à gérer les voix disponibles. Offrez une dimension sonore unique à vos créations et enrichissez significativement l\'expérience de vos utilisateurs.','maxituc',0,'covers/faites-parler-vos-applications-en-net.png','books/Faites parler vos applications en net.pdf',14,2012,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(223,'Créez vos applications web avec Flask','creez-vos-applications-web-avec-flask','Envie de transformer vos compétences Python en applications web fonctionnelles et dynamiques ? Ce livre vous initie à Flask, un micro-framework élégant et facile à prendre en main, idéal pour concrétiser vos projets web. Des bases du protocole HTTP à l\'intégration de templates Jinja, en passant par la gestion des formulaires et des sessions, vous maîtriserez toutes les étapes pour créer des expériences utilisateur interactives. Préparez-vous à développer concrètement un service web d\'upload d\'images, et à acquérir une expertise solide pour bâtir vos propres applications modernes.','FireZéro',0,'covers/creez-vos-applications-web-avec-flask.png','books/Creez vos applications web avec flask.pdf',51,2013,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(224,'Les calculs en binaire','les-calculs-en-binaire','Plongez au cœur des fondements de l\'informatique avec \"Les calculs en binaire\", le guide essentiel pour maîtriser les opérations mathématiques de base dans ce langage fondamental. De la représentation des nombres négatifs aux additions, soustractions, multiplications et divisions, ce tutoriel vous équipe pour manipuler manuellement les chiffres binaires avec aisance et précision. Idéal pour les futurs développeurs d\'applications en assembleur ou les passionnés de micro-contrôleurs, ce cours accessible vous offrira une compréhension pratique et approfondie de la logique binaire, éclairant des concepts souvent perçus comme complexes.','distopia',0,'covers/les-calculs-en-binaire.png','books/Les calculs en binaire.pdf',18,2012,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(225,'Débuguer facilement avec Valgrind','debuguer-facilement-avec-valgrind','Marre des erreurs de segmentation et des fuites de mémoire, souvent cauchemars des développeurs C/C++ ? Ce livre est votre compagnon indispensable pour maîtriser Valgrind, l\'outil par excellence pour traquer les bugs les plus insidieux. Découvrez comment il vous révèle les accès invalides, les variables non initialisées et les allocations non libérées, avec des explications claires et des exemples pratiques. Transformez votre processus de débogage pour concevoir des applications plus robustes et performantes, en débusquant efficacement ce qui échappe aux méthodes traditionnelles.','Tados',0,'covers/debuguer-facilement-avec-valgrind.png','books/Debuguer facilement avec valgrind.pdf',18,2011,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(226,'Mozilla Thunderbird','mozilla-thunderbird','Optimisez votre gestion de courriels avec ce guide complet dédié à Mozilla Thunderbird. Que vous soyez un utilisateur débutant ou désireux d\'approfondir vos connaissances, ce livre vous accompagnera pas à pas, de l\'installation et la configuration des comptes à la rédaction de mails et la gestion des contacts. Découvrez comment personnaliser et étendre les capacités de Thunderbird grâce aux extensions et aux thèmes, et maîtrisez les réglages avancés pour une efficacité inégalée. Prenez le contrôle total de votre messagerie et transformez votre quotidien numérique.','Merj',0,'covers/mozilla-thunderbird.png','books/Mozilla thunderbird.pdf',55,2011,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(227,'Le guide du contributeur','le-guide-du-contributeur','Vous êtes un utilisateur assidu de logiciels libres et souhaitez comprendre les mécanismes de leur développement, voire y prendre part ? Ce guide complet vous ouvre les portes de la contribution, que vous soyez développeur, rédacteur, traducteur ou créateur d\'éléments multimédias. Il vous accompagnera pas à pas, de la théorie des différents types de projets à la pratique concrète de l\'envoi de patchs, de la gestion des bugs et de la revue de code. Apprenez à naviguer dans l\'écosystème open source, à communiquer efficacement et à tirer le meilleur parti des outils collaboratifs pour améliorer vos logiciels préférés et développer vos propres compétences.','Cygal',0,'covers/le-guide-du-contributeur.png','books/Le guide du contributeur.pdf',7,2009,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(228,'Traitez des textes avec Word','traitez-des-textes-avec-word','Maîtrisez Word de A à Z avec ce guide complet et pratique. Que vous soyez débutant ou que vous souhaitiez perfectionner vos compétences, ce livre vous accompagnera depuis la prise en main du logiciel jusqu\'à la création de documents sophistiqués. Apprenez à structurer, formater et présenter vos textes avec aisance, en exploitant les styles, les illustrations, les tableaux et les fonctionnalités avancées. Devenez un expert de Word et optimisez votre productivité pour créer des documents professionnels et percutants.','Blaise Barré (~Electro)',0,'covers/traitez-des-textes-avec-word.png','books/Traitez des textes avec word.pdf',294,2013,1,5,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(229,'Compilation à la volée avec libtcc','compilation-a-la-volee-avec-libtcc','Plongez dans l\'univers fascinant de la compilation à la volée avec libtcc et apprenez à intégrer un compilateur C directement au cœur de vos applications. Ce livre vous ouvre les portes d\'une flexibilité inédite, permettant à vos utilisateurs d\'écrire et d\'exécuter du code C en temps réel, sans la moindre interruption. À travers des explications claires et des exemples pratiques, de l\'installation à la manipulation de symboles, vous transformerez facilement votre logiciel en un environnement dynamique et programmable. Idéal pour les développeurs désireux d\'ajouter une dimension interactive puissante à leurs projets.','Grota',0,'covers/compilation-a-la-volee-avec-libtcc.png','books/Compilation a la volee avec libtcc.pdf',13,2011,1,6,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(230,'La gestion du joystick avec la SDL','la-gestion-du-joystick-avec-la-sdl','Vous rêvez de créer des jeux vidéo interactifs avec une manette ou un joystick ? Ce livre est votre guide essentiel pour maîtriser la gestion des contrôleurs de jeu grâce à la puissante bibliothèque SDL. Découvrez en détail les composants d\'un joystick, apprenez à recueillir des informations précieuses et gérez avec précision tous les types d\'événements, des simples pressions de boutons aux mouvements complexes des axes et des chapeaux. Idéal pour les développeurs de jeux souhaitant intégrer une expérience utilisateur fluide et immersive, cet ouvrage vous ouvre les portes de la création de jeux interactifs et réactifs.','François Sellier (François.S)',0,'covers/la-gestion-du-joystick-avec-la-sdl.png','books/La gestion du joystick avec la sdl.pdf',32,2012,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(231,'Le tri rapide : QSort','le-tri-rapide-qsort','Maîtrisez le QuickSort (QSort), l\'un des algorithmes de tri les plus performants et les plus ingénieux, idéal pour organiser efficacement vos données désordonnées. Ce livre vous guidera à travers son principe récursif unique, illustré par des exemples clairs et des implémentations pratiques en OCaml et C. Vous apprendrez à optimiser le choix du pivot et à analyser ses performances dans les meilleurs et pires scénarios, y compris les implémentations \"in-place\". Préparez-vous à démystifier la vitesse et l\'élégance du tri rapide.','GuilOooo',0,'covers/le-tri-rapide-qsort.png','books/Le tri rapide qsort.pdf',9,2009,1,6,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(232,'Le GUI avec Qt, la suite','le-gui-avec-qt-la-suite','Poursuivez votre parcours en développement GUI avec Qt et élevez vos compétences à un niveau supérieur grâce à cet ouvrage, la suite essentielle au célèbre tutoriel de M@teo21. Explorez la personnalisation avancée des widgets comme les QPushButton et les boutons-menus, maîtrisez la manipulation de fichiers, les interactions système et l\'art des styles personnalisés pour des applications robustes. Découvrez également la richesse de la 2D avec Qt, en apprenant à dessiner des formes, gérer du texte, intégrer des images et manipuler des éléments graphiques complexes via les QGraphicsItem. Idéal pour les développeurs intermédiaires désireux de créer des programmes complets et professionnels, ce livre est votre guide pour exploiter toutes les facettes de Qt.','Amnell',0,'covers/le-gui-avec-qt-la-suite.png','books/Le gui avec qt la suite.pdf',68,2012,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(233,'Les displacements : techniques avancées','les-displacements-techniques-avancees','Maîtrisez l\'art délicat de la création d\'environnements naturels réalistes et fluides dans les moteurs de jeu grâce à ce guide avancé sur les displacements. Conçu pour les mappeurs intermédiaires et avancés, cet ouvrage comble les lacunes des tutoriels classiques en vous révélant des techniques professionnelles pour des paysages visuellement impeccables et naturels. Découvrez comment découper vos blocs stratégiquement pour un \"sew\" parfait, maîtrisez l\'association du Vertex Tool et optimisez la précision de vos reliefs, qu\'il s\'agisse de grottes adoucies ou de déserts bruts.','Tydax',0,'covers/les-displacements-techniques-avancees.png','books/Les displacements techniques avancees.pdf',9,2012,1,7,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(234,'Manipulez les paquets réseau avec Scapy','manipulez-les-paquets-reseau-avec-scapy','Transformez votre compréhension du réseau en maîtrise opérationnelle avec \"Manipulez les paquets réseau avec Scapy\" ! Ce guide immersif vous initie au module Python Scapy, l\'outil incontournable pour forger, envoyer et analyser en profondeur le trafic réseau. Que vous souhaitiez déconstruire le fonctionnement de Wireshark ou Nmap, ou programmer vos propres utilitaires sophistiqués, ce livre vous équipe des compétences nécessaires pour manipuler les paquets à leur plus bas niveau. Embarquez pour une exploration pratique et devenez un véritable architecte de vos interactions réseau.','FireZéro',0,'covers/manipulez-les-paquets-reseau-avec-scapy.png','books/Manipulez les paquets reseau avec scapy.pdf',23,2011,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(235,'Gérer vos projets avec Mercurial','gerer-vos-projets-avec-mercurial','Vous en avez assez de perdre vos modifications, de voir votre travail écrasé lors de projets collaboratifs, ou de ne plus savoir où se trouve la dernière version de votre code ? Ce guide vous invite à découvrir Mercurial, le système de gestion de version libre et gratuit qui révolutionnera votre approche du développement, que vous travailliez seul ou en équipe. De l\'installation pas à pas sur toutes les plateformes à la maîtrise des commandes essentielles et de l\'intégration dans vos IDE favoris comme Netbeans et Eclipse, vous apprendrez à naviguer entre les versions et à configurer votre environnement. Retrouvez la sérénité et l\'efficacité, et protégez durablement l\'intégralité de vos projets informatiques.','Meianki',0,'covers/gerer-vos-projets-avec-mercurial.png','books/Gerer vos projets avec mercurial.pdf',12,2011,1,7,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(236,'Foncteurs et itérateurs','foncteurs-et-iterateurs','Découvrez les foncteurs et itérateurs, deux concepts essentiels pour tout développeur C++ souhaitant écrire un code plus puissant et plus générique. Ce guide pratique vous montrera comment les itérateurs standardisent la traversée des séquences, des tableaux aux `std::string`, et simplifient la manipulation des données avec des fonctions comme `std::for_each`. Apprenez également à transformer vos objets en fonctions pour des architectures logicielles plus flexibles et performantes. Idéal pour les programmeurs C++ ayant une bonne compréhension des pointeurs, cet ouvrage vous propulsera vers une maîtrise accrue du langage et de sa librairie standard.','Ice_Keese',0,'covers/foncteurs-et-iterateurs.png','books/Foncteurs et iterateurs.pdf',8,2011,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(237,'La cryptographie facile avec PGP','la-cryptographie-facile-avec-pgp','À l\'ère du numérique, la protection de vos communications n\'a jamais été aussi cruciale. Ce guide pratique, \"La cryptographie facile avec PGP\", vous démystifie l\'art de sécuriser vos messages grâce à GnuPG, l\'implémentation libre et fiable du standard OpenPGP. De l\'installation du logiciel à la génération de vos paires de clés, en passant par le chiffrement et la signature, vous maîtriserez toutes les étapes pour garantir la confidentialité et l\'authenticité de vos échanges. Conçu pour être accessible aux débutants, ce livre est votre passeport pour des communications personnelles et professionnelles véritablement sécurisées.','Perlejade',0,'covers/la-cryptographie-facile-avec-pgp.png','books/La cryptographie facile avec pgp.pdf',9,2009,1,7,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(238,'Les ChMod','les-chmod','Démystifiez les permissions Linux avec \"Les ChMod\" et mettez fin aux problèmes de droits qui entravent souvent vos projets. Ce guide complet vous introduira aux subtilités de cette commande essentielle, de sa logique binaire et octale à son application concrète. Apprenez à manipuler les droits sur fichiers et répertoires de manière octale ou symbolique, et comprenez les distinctions fondamentales pour une gestion sécurisée et efficace. Idéal pour les développeurs et administrateurs souhaitant maîtriser les fondements des systèmes multi-utilisateurs, ce livre est votre allié pour une gestion parfaite de vos permissions.','Natim',0,'covers/les-chmod.png','books/Les chmod.pdf',7,2012,1,4,'2026-07-29 08:53:13','2026-07-29 08:53:13'),(239,'Découverte de la programmation par contraintes','decouverte-de-la-programmation-par-contraintes','Plongez dans le monde fascinant de la programmation par contraintes, une approche où vous décrivez simplement votre problème et laissez l\'ordinateur trouver les solutions. À travers un projet concret de résolution de carrés magiques, ce guide pratique vous initie à la puissance de la bibliothèque Gecode, sans exiger une expertise approfondie en C++. De l\'installation à la modélisation des contraintes, vous serez guidé pas à pas pour aborder des défis logiques complexes avec une efficacité surprenante. Une ressource indispensable pour quiconque souhaite découvrir comment optimiser la résolution de problèmes.','contraintes',0,'covers/decouverte-de-la-programmation-par-contraintes.png','books/Decouverte de la programmation par contraintes.pdf',9,2009,1,4,'2026-07-29 08:53:16','2026-07-29 08:53:16'),(240,'Le tri par tas','le-tri-par-tas','Découvrez le Tri par Tas, un algorithme de tri puissant et asympotiquement optimal, offrant une complexité en O(n log n) qui le rend idéal pour les grandes entrées. Ce guide complet vous mènera des concepts fondamentaux des tas binaires et de l\'opération d\'entassement à l\'implémentation concrète de l\'algorithme. Que vous soyez étudiant ou développeur, apprenez à maîtriser ce tri efficace, avec des explications claires facilitant la transposition des exemples OCaml vers votre langage de prédilection.','tas',0,'covers/le-tri-par-tas.png','books/Le tri par tas.pdf',7,2011,1,6,'2026-07-29 08:53:16','2026-07-29 08:53:16'),(241,'Inscrivez et connectez vos membres en un clic !','inscrivez-et-connectez-vos-membres-en-un-clic','Optimisez l\'expérience utilisateur de votre site avec ce guide pratique dédié à l\'inscription et la connexion en un clic. Découvrez comment Janrain révolutionne l\'intégration des identifiants sociaux, en vous guidant pas à pas pour configurer des fournisseurs comme Facebook ou Windows Live ID. Cet ouvrage vous fournit le code et les méthodologies pour simplifier radicalement la gestion de vos membres, rendant leur accès à votre plateforme fluide et instantané.','emersion',0,'covers/inscrivez-et-connectez-vos-membres-en-un-clic.png','books/Inscrivez et connectez vos membres en un clic.pdf',23,2012,1,4,'2026-07-29 08:53:16','2026-07-29 08:53:16'),(242,'Créer un serveur Subversion','creer-un-serveur-subversion','Vous maîtrisez Subversion mais l\'absence de serveur vous empêche d\'en exploiter tout le potentiel ? Ce guide pratique et accessible est conçu pour vous ! Il vous accompagne pas à pas dans l\'installation et la configuration d\'un serveur Subversion sous Debian et ses dérivés, même avec des ressources matérielles limitées. Transformez rapidement toute machine modeste en un centre de versionnement efficace pour vos projets, et commencez à collaborer sans effort.','lp0',0,'covers/creer-un-serveur-subversion.png','books/Creer un serveur subversion.pdf',7,2011,1,7,'2026-07-29 08:53:16','2026-07-29 08:53:16'),(243,'Dissimuler un texte dans une image','dissimuler-un-texte-dans-une-image','Plongez dans l\'univers captivant de la stéganographie et maîtrisez l\'art de la dissimulation numérique. Ce livre vous guide pas à pas pour cacher un texte discret au sein d\'une image bitmap, en exploitant astucieusement les bits de poids faible des pixels pour une invisibilité parfaite. Des concepts binaires fondamentaux à l\'implémentation pratique en PHP (facilement transposable en C++ ou Java), vous acquerrez toutes les compétences pour créer vos propres messages secrets visuels. Prêt à transformer n\'importe quelle image en un support de communication insoupçonnable ?','Cid',0,'covers/dissimuler-un-texte-dans-une-image.png','books/Dissimuler un texte dans une image.pdf',14,2011,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(244,'Mise en place d\'un Serveur DHCP sous Linux','mise-en-place-dun-serveur-dhcp-sous-linux','Optimisez la gestion de votre réseau Linux grâce à ce guide pratique et didactique sur la mise en place d\'un serveur DHCP. Apprenez à distribuer automatiquement les adresses IP et les paramètres réseau essentiels à vos clients, transformant une tâche manuelle en un processus fluide et efficace. Que vous soyez débutant ou administrateur système, ce livre vous accompagnera pas à pas, des rappels fondamentaux à la configuration avancée du serveur et du client. Maîtrisez le DHCP sous Linux et simplifiez radicalement l\'administration de vos infrastructures.','wawanopoulos',0,'covers/mise-en-place-d-un-serveur-dhcp-sous-linux.png','books/Mise en place d un serveur dhcp sous linux.pdf',10,2010,1,7,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(245,'Indefero, un bug tracker très complet','indefero-un-bug-tracker-tres-complet','Plongez dans le monde de la gestion de projets open-source avec ce guide dédié à Indefero, une forge logicielle complète et robuste. Idéal pour les équipes de développement, cette plateforme web intègre harmonieusement un puissant bug tracker, la gestion avancée des dépôts Git, SVN et Mercurial, ainsi qu\'un wiki collaboratif et des outils d\'administration projet/utilisateur. Ce tutoriel détaillé vous guidera pas à pas à travers l\'installation et la configuration d\'Indefero, transformant la documentation complexe en un parcours simple et efficace sur votre serveur. Optimisez votre travail collaboratif et centralisez toutes les facettes de vos projets logiciels grâce à cette solution tout-en-un.','slash-dev',0,'covers/indefero-un-bug-tracker-tres-complet.png','books/Indefero un bug tracker tres complet.pdf',18,2010,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(246,'Apprenez à colorier avec \"The GIMP\" !','apprenez-a-colorier-avec-the-gimp','Plongez dans l\'univers de la coloration numérique avec \"Apprenez à colorier avec The GIMP\" et donnez vie à vos illustrations ! Ce guide pratique et accessible vous accompagne pas à pas pour maîtriser les bases du logiciel libre GIMP, de la configuration de votre espace de travail au choix des couleurs, en passant par les techniques d\'ombrage. Que vous soyez débutant ou souhaitiez affiner votre approche, découvrez une méthode inspirante pour développer votre propre style et transformer vos line arts en œuvres d\'art vibrantes. Préparez-vous à exprimer votre créativité et à réaliser des colorations numériques captivantes.','Valt',0,'covers/apprenez-a-colorier-avec-the-gimp.png','books/Apprenez a colorier avec the gimp.pdf',13,2010,1,6,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(247,'Bruit de Perlin','bruit-de-perlin','Plongez dans l\'univers captivant du Bruit de Perlin, une technique fondamentale de l\'art numérique et de la génération procédurale. Ce livre explore les fonctions de bruit et révèle comment l\'algorithme innovant de Ken Perlin permet d\'insuffler un réalisme saisissant aux images de synthèse, aux jeux vidéo et aux effets spéciaux. Découvrez comment créer automatiquement des textures variées, des terrains complexes ou même des mondes virtuels entiers, et maîtrisez les bases pour repousser les limites de votre imagination créative.','OveRdrivR',0,'covers/bruit-de-perlin.png','books/Bruit de perlin.pdf',13,2012,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(248,'La programmation avec Autoit','la-programmation-avec-autoit','Plongez dans l\'univers de la programmation avec AutoIt grâce à ce guide complet et très accessible, élaboré par la communauté française. Idéal pour les débutants, ce livre vous accompagnera pas à pas, des fondamentaux du langage à la création d\'interfaces graphiques (GUI) complexes et à l\'automatisation de tâches Windows. Démystifiez les idées reçues et apprenez à manipuler fenêtres, processus et applications pour développer des scripts puissants et accroître votre productivité.','Timothée Malossane (timmalos)',0,'covers/la-programmation-avec-autoit.png','books/La programmation avec autoit.pdf',98,2012,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(249,'Modifier l\'apparence d\'une infobulle','modifier-lapparence-dune-infobulle','Envie de donner une touche professionnelle et personnalisée à vos interfaces web ? Ce guide pratique vous révèle comment dépasser les limitations des infobulles par défaut pour créer des éléments interactifs uniques. Apprenez pas à pas à concevoir et styliser vos propres infobulles avec xHTML et CSS, transformant une simple information en un détail élégant et intuitif pour vos utilisateurs. Idéal pour les développeurs intermédiaires, ce tutoriel complet vous ouvre les portes d\'une personnalisation avancée et d\'une expérience utilisateur enrichie.','ShadowBlade',0,'covers/modifier-l-apparence-d-une-infobulle.png','books/Modifier l apparence d une infobulle.pdf',8,2011,1,5,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(250,'Tableaux, pointeurs et allocation dynamique','tableaux-pointeurs-et-allocation-dynamique','Souvent sources de confusion pour les programmeurs, les tableaux et les pointeurs sont pourtant des piliers essentiels de la gestion mémoire. Ce livre vous guide pour non seulement comprendre leurs différences fondamentales, mais aussi pour maîtriser leur utilisation correcte et les techniques d\'allocation dynamique. De l\'initialisation à la gestion des tableaux multidimensionnels et aux passages en argument de fonctions, chaque aspect est abordé avec clarté et illustré par des exemples concrets. Plongez dans ce tutoriel complet pour transformer vos défis en compétences solides et éviter les pièges courants de la programmation.','uknow',0,'covers/tableaux-pointeurs-et-allocation-dynamique.png','books/Tableaux pointeurs et allocation dynamique.pdf',46,2012,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(251,'Découvrir et configurer le protocole SFTP avec MySecureShell','decouvrir-et-configurer-le-protocole-sftp-avec-mysecureshell','Besoin de transférer des fichiers en toute sécurité sur votre serveur Linux, tout en garantissant un accès strictement contrôlé ? Ce guide essentiel vous plonge dans le protocole SFTP et l\'outil puissant MySecureShell. Apprenez pas à pas à configurer un environnement de transfert sécurisé, permettant à vos utilisateurs d\'accéder uniquement aux dossiers que vous autorisez, grâce à une technique de chrootage efficace. Maîtrisez une solution robuste et fiable pour une gestion optimale de vos accès SFTP.','jtraulle',0,'covers/decouvrir-et-configurer-le-protocole-sftp-avec-mysecureshell.png','books/Decouvrir et configurer le protocole sftp avec mysecureshell.pdf',8,2012,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(252,'Rédigez des documents de qualité avec LaTeX','redigez-des-documents-de-qualite-avec-latex','Transformez la rédaction de vos documents en une expérience fluide et professionnelle avec \"Rédigez des documents de qualité avec LaTeX\", le guide essentiel pour maîtriser ce puissant système de composition. De l\'installation à la création de documents complexes, cet ouvrage complet vous accompagne pas à pas, abordant la mise en page, les polices, l\'insertion d\'images et de tableaux, ainsi que la gestion avancée des formules mathématiques et des bibliographies. Idéal pour les étudiants, les chercheurs et les professionnels, il propose des exemples concrets et des travaux pratiques pour vous assurer une maîtrise rapide et efficace, garantissant des publications d\'une qualité typographique irréprochable.','Laleloulilo',0,'covers/redigez-des-documents-de-qualite-avec-latex.png','books/Redigez des documents de qualite avec latex.pdf',220,2012,1,6,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(253,'Qt - Création de plugins','qt-creation-de-plugins','Donnez une nouvelle dimension à vos applications Qt en les rendant modulaires et évolutives grâce aux plugins. Ce guide pratique et théorique vous équipe pour comprendre, définir et implémenter vos propres greffons, du concept d\'interface au chargement dynamique. Conçu pour les développeurs C++ familiers avec la POO avancée, il vous permettra d\'ajouter facilement de nouvelles fonctionnalités et d\'optimiser la maintenance de vos logiciels. Maîtrisez l\'art des plugins Qt et développez des applications robustes et flexibles.','EPonix',0,'covers/qt-creation-de-plugins.png','books/Qt creation de plugins.pdf',19,2011,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(254,'Développez des jeux en 2D avec Construct','developpez-des-jeux-en-2d-avec-construct','Envie de donner vie à vos propres jeux en 2D sans la complexité des langages de programmation ? Ce livre est votre guide pour maîtriser Construct, un outil puissant et intuitif qui rend la création de jeux rapide et accessible à tous. Des bases essentielles comme la gestion des sprites, des comportements et des événements, jusqu\'à l\'organisation de votre projet avec les calques et les variables, vous découvrirez comment concrétiser vos idées. Lancez-vous dans l\'aventure avec un projet complet pas à pas et transformez votre imagination en jeux captivants.','Martin (The_Lord_King)',0,'covers/developpez-des-jeux-en-2d-avec-construct.png','books/Developpez des jeux en 2d avec construct.pdf',50,2012,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(255,'Les ACL (Access Control Lists) sous Linux','les-acl-access-control-lists-sous-linux','Vous gérez une machine Linux partagée et les permissions classiques de fichiers et dossiers sont devenues un véritable casse-tête ? Découvrez comment les ACL (Access Control Lists) révolutionnent la gestion des droits en vous offrant une granularité et une flexibilité sans précédent. Ce livre vous guide pas à pas, de la vérification du noyau à l\'installation des outils, pour maîtriser les commandes setfacl et getfacl. Apprenez à créer des permissions sur mesure pour chaque utilisateur et groupe, assurant une sécurité et une organisation optimales de vos données.','op414',0,'covers/les-acl-access-control-lists-sous-linux.png','books/Les acl access control lists sous linux.pdf',12,2011,1,6,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(256,'Gérez vos projets à l\'aide du gestionnaire de versions Subversion','gerez-vos-projets-a-laide-du-gestionnaire-de-versions-subversion','Prenez le contrôle total de vos projets et de votre collaboration avec \"Gérez vos projets à l\'aide du gestionnaire de versions Subversion\". Ce guide essentiel vous plonge au cœur de Subversion (SVN), l\'outil indispensable pour les développeurs et les équipes souhaitant une gestion de versions robuste et intelligente. Vous y découvrirez comment maîtriser les clients SVN sous Windows, Mac et Linux, gérer efficacement les arborescences de fichiers, communiquer avec le système et résoudre les conflits, tout en comprenant les mécanismes fondamentaux qui sous-tendent chaque opération. Adoptez une approche professionnelle de la gestion de projet et sécurisez l\'historique de toutes vos modifications.','Dalshim',0,'covers/gerez-vos-projets-a-l-aide-du-gestionnaire-de-versions-subversion.png','books/Gerez vos projets a l aide du gestionnaire de versions subversion.pdf',54,2010,1,7,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(257,'Débutez en informatique avec Windows 7','debutez-en-informatique-avec-windows-7','Vous faites vos premiers pas dans le monde de l\'informatique et souhaitez maîtriser Windows 7 en toute confiance ? Ce livre vous accompagne pas à pas, de la prise en main de votre ordinateur et de la gestion de vos fichiers à l\'exploration du web et à l\'envoi de courriers électroniques. Acquérez rapidement les réflexes fondamentaux pour naviguer avec aisance, sécuriser vos données et communiquer efficacement en ligne.','ShigeruM',0,'covers/debutez-en-informatique-avec-windows-7.png','books/Debutez en informatique avec windows 7.pdf',348,2013,1,6,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(258,'Introduction au dialogue entre OCaml et le C','introduction-au-dialogue-entre-ocaml-et-le-c','Vous aspirez à libérer le plein potentiel de vos applications OCaml en les connectant à la puissance du C ? Ce guide professionnel est l\'outil indispensable pour les développeurs OCaml expérimentés désireux d\'explorer l\'interopérabilité. Il vous mènera, de la maîtrise des macros fondamentales aux subtilités de la gestion mémoire avec le ramasse-miettes, en passant par les types complexes et l\'optimisation des performances. Découvrez comment construire des ponts robustes entre ces deux langages et éviter les erreurs courantes pour des projets stables et performants.','Cacophrene',0,'covers/introduction-au-dialogue-entre-ocaml-et-le-c.png','books/Introduction au dialogue entre ocaml et le c.pdf',15,2009,1,6,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(259,'3ds Max pour les Zéros !','3ds-max-pour-les-zeros','Plongez dans l\'univers de la 3D avec \"3ds Max pour les Zéros !\", le guide parfait pour débuter avec le logiciel de référence en animation, jeux vidéo et architecture. De la prise en main de l\'interface à la modélisation d\'objets complexes comme une table ou un verre, en passant par le texturing et l\'éclairage, chaque étape est expliquée avec clarté. Apprenez à créer, manipuler et rendre vos premières scènes 3D grâce à des explications simples et des exemples concrets, vous permettant de rapidement maîtriser les bases essentielles. Ce livre est votre point de départ idéal pour donner vie à toutes vos idées numériques en 3D.','Spoke44',0,'covers/3ds-max-pour-les-zeros.png','books/3ds max pour les zeros.pdf',62,2011,1,6,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(260,'Découvrez Ogre 3D','decouvrez-ogre-3d','Vous rêvez de créer vos propres jeux vidéo ou applications 3D interactives, mais ne savez pas par où commencer ? Ce livre est votre porte d\'entrée vers le monde fascinant du développement 3D, vous guidant pas à pas à travers Ogre 3D, un moteur libre et gratuit plébiscité par les développeurs pour sa puissance et sa flexibilité. Des fondamentaux de la création de scènes et de l\'intégration d\'objets à la maîtrise des matériaux, des shaders et des animations complexes, en passant par la gestion des entrées et des terrains, chaque étape est détaillée. Préparez-vous à transformer vos idées en réalité et à donner vie à vos projets 3D avec ce guide complet et accessible.','Midnight Falcon',0,'covers/decouvrez-ogre-3d.png','books/Decouvrez ogre 3d.pdf',158,2012,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(261,'Le multiboot sous GNU/Linux','le-multiboot-sous-gnulinux','Envie de faire cohabiter plusieurs systèmes d\'exploitation sur votre machine, qu\'il s\'agisse de Windows et GNU/Linux ou de différentes distributions ? Ce livre est votre compagnon idéal pour maîtriser l\'art du multiboot. Il vous guide pas à pas, des bases théoriques du partitionnement et du processus de démarrage aux manipulations pratiques avancées, avec un accent prononcé sur l\'utilisation des puissants outils en ligne de commande. Que vous soyez un débutant ou un utilisateur expérimenté, vous apprendrez à configurer et gérer vos systèmes en toute autonomie, garantissant un environnement stable et performant.','Alexis211',0,'covers/le-multiboot-sous-gnu-linux.png','books/Le multiboot sous gnu linux.pdf',96,2012,1,6,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(262,'Développer son propre contrôle utilisateur WinForms','developper-son-propre-controle-utilisateur-winforms','Vous êtes développeur WinForms et rêvez d\'aller au-delà des contrôles utilisateur standards ? Ce livre vous guide pas à pas pour concevoir et implémenter vos propres composants sur mesure en C#, de la partie design à la logique métier. Apprenez à gérer les événements, intégrer des fonctionnalités avancées comme les SmartTags et les Designer Verbs, et même personnaliser l\'affichage de vos créations dans la boîte à outils. Donnez vie à des interfaces uniques et prenez le contrôle total de l\'expérience utilisateur de vos applications.','Chiheb2012',0,'covers/developper-son-propre-controle-utilisateur-winforms.png','books/Developper son propre controle utilisateur winforms.pdf',21,2012,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(263,'Réalisez votre jeu vidéo avec UDK','realisez-votre-jeu-video-avec-udk','Plongez dans l\'univers fascinant de la création de jeux vidéo et maîtrisez l\'Unreal Development Kit (UDK) avec ce guide pratique et exhaustif. De la prise en main de l\'éditeur à la conception de niveaux immersifs, en passant par l\'intégration d\'effets spéciaux spectaculaires et la gestion d\'éclairages sophistiqués, chaque étape est détaillée pour donner vie à vos idées. Apprenez également à créer et importer votre propre contenu unique, du model 3D aux matériaux dynamiques et animations, pour personnaliser chaque aspect de votre projet. Que vous soyez débutant ou souhaitiez approfondir vos connaissances, ce livre vous accompagnera jusqu\'à la publication de votre jeu.','Gwennaël Arbona (Gwenn)',0,'covers/realisez-votre-jeu-video-avec-udk.png','books/Realisez votre jeu video avec udk.pdf',234,2012,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(264,'Apprenez la sculpture digitale avec Pixologic ZBrush','apprenez-la-sculpture-digitale-avec-pixologic-zbrush','Plongez dans l\'univers captivant de la sculpture digitale et maîtrisez Pixologic ZBrush, le logiciel incontournable pour les professionnels de la 3D dans le jeu vidéo et le cinéma. Ce guide complet vous emmène pas à pas, des bases de l\'interface et de la navigation aux techniques avancées de modelage organique et de hard surface, incluant les ZSpheres, DynaMesh, et l\'application de détails fins. Apprenez à sculpter avec précision, à gérer vos maillages et à personnaliser votre environnement de travail, pour donner vie à toutes vos idées créatives avec une efficacité redoutable. Ce livre est la ressource idéale pour transformer votre imagination en œuvres d\'art numériques saisissantes.','Danyl Bekhoucha (Linko)',0,'covers/apprenez-la-sculpture-digitale-avec-pixologic-zbrush.png','books/Apprenez la sculpture digitale avec pixologic zbrush.pdf',91,2012,1,5,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(265,'Affichez le nombre de visiteurs connectés','affichez-le-nombre-de-visiteurs-connectes','Ce livre essentiel vous guide pas à pas pour implémenter un compteur de visiteurs connectés en temps réel sur votre site web. Découvrez une méthode simple et efficace pour concevoir cette fonctionnalité dynamique à l\'aide de PHP et MySQL, en apprenant à gérer les adresses IP et les timestamps pour un suivi précis de l\'activité. Idéal pour les webmasters, cet ouvrage vous fournit les outils pour comprendre le fonctionnement des connexions et afficher des statistiques pertinentes sur vos pages. Offrez à votre site une dimension interactive et informative, en toute simplicité.','Mathieu Nebra (Mateo21)',0,'covers/affichez-le-nombre-de-visiteurs-connectes.png','books/Affichez le nombre de visiteurs connectes.pdf',6,2011,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(266,'Algorithmique pour l\'apprenti programmeur','algorithmique-pour-lapprenti-programmeur','Vous maîtrisez les bases de la programmation et aspirez à créer des applications non seulement fonctionnelles, mais aussi incroyablement performantes ? Ce livre est votre guide essentiel pour démystifier l\'algorithmique, en vous introduisant aux concepts fondamentaux de la complexité et des structures de données. Apprenez à évaluer et à optimiser l\'efficacité de vos programmes, du tri à la recherche d\'éléments, en choisissant les bonnes approches techniques. Devenez un développeur aguerri, capable de concevoir des solutions élégantes et hautement performantes.','bluestorm ,',0,'covers/algorithmique-pour-l-apprenti-programmeur.png','books/Algorithmique pour l apprenti programmeur.pdf',70,2011,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(267,'Programmer un bot IRC simplement avec ircbot','programmer-un-bot-irc-simplement-avec-ircbot','Plongez dans le monde fascinant des bots IRC et apprenez à programmer le vôtre avec une simplicité déconcertante grâce au module `ircbot` pour Python. Ce guide complet vous initie à la programmation événementielle, essentielle pour interagir efficacement avec les serveurs IRC, et vous accompagne de la conception d\'un bot basique à l\'intégration de fonctionnalités avancées telles que la gestion des canaux et les masques de bannissement. Idéal pour les développeurs Python (avec des bases en POO et Python 2) désireux d\'automatiser et d\'animer leurs communautés, ce livre est votre passeport pour maîtriser la création de bots IRC performants. Ne manquez pas l\'opportunité de donner vie à vos propres assistants virtuels !','Dentuk',0,'covers/programmer-un-bot-irc-simplement-avec-ircbot.png','books/Programmer un bot irc simplement avec ircbot.pdf',13,2010,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(268,'Utiliser Qt avec Visual Studio 2010','utiliser-qt-avec-visual-studio-2010','Développeurs C++ sous Visual Studio 2010, vous rêvez d\'exploiter la puissance de Qt sans devoir changer d\'IDE ? Ce guide est conçu précisément pour vous, car la compatibilité officielle et les plugins dédiés ne couvrent pas directement cette version spécifique de l\'IDE, rendant la tâche d\'intégration complexe. Grâce à ce livre, découvrez comment compiler manuellement Qt et configurer minutieusement votre environnement Visual Studio 2010, depuis les variables système jusqu\'à la gestion avancée de vos projets. Maîtrisez pas à pas chaque étape pour intégrer ces deux technologies robustes et donner vie à vos applications sans compromis.','Xavinou',0,'covers/utiliser-qt-avec-visual-studio-2010.png','books/Utiliser qt avec visual studio 2010.pdf',14,2010,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(269,'Maîtriser l\'outil plume et les tracés','maitriser-loutil-plume-et-les-traces','Révélez le potentiel créatif de vos logiciels de design graphique en maîtrisant l\'outil plume, un incontournable pour des tracés vectoriels d\'une précision chirurgicale et des sélections impeccables. Ce guide pratique vous accompagnera pas à pas, des bases des tracés simples et de la familiarisation avec l\'interface, jusqu\'aux techniques avancées pour les courbes complexes et la création de masques. Apprenez à convertir vos tracés en sélections, à les utiliser comme guides de texte ou à les redimensionner sans aucune perte de qualité, pour des designs professionnels et polyvalents. Idéal pour les débutants, ce livre vous offre toutes les clés pour transformer vos idées en réalisations graphiques fluides et percutantes.','tdimeco',0,'covers/maitriser-l-outil-plume-et-les-traces.png','books/Maitriser l outil plume et les traces.pdf',12,2010,1,7,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(270,'Montez votre site dans le cloud avec Google App Engine','montez-votre-site-dans-le-cloud-avec-google-app-engine','Propulsez votre site web dans le cloud avec Google App Engine ! Ce guide pratique vous accompagne pas à pas, des fondamentaux du cloud computing au déploiement de votre première application sur les serveurs de Google. Vous apprendrez à maîtriser toutes les options de stockage (Google Cloud SQL, Datastore NoSQL, Blobstore, Cloud Storage) et à intégrer les puissants services d\'App Engine : authentification, envoi d\'e-mails, traitement d\'images, tâches planifiées et création d\'APIs robustes. Maîtrisez cette plateforme d\'exception pour bâtir des applications web et mobiles performantes, scalables et résolument modernes.','Mathieu Nebra (Mateo21)',0,'covers/montez-votre-site-dans-le-cloud-avec-google-app-engine.png','books/Montez votre site dans le cloud avec google app engine.pdf',142,2013,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(271,'L\'électronique de zéro','lelectronique-de-zero','Découvrez l\'électronique de A à Z avec ce guide exhaustif, idéal pour les débutants désireux de comprendre les principes fondamentaux. Depuis les notions élémentaires de l\'électricité et les règles de sécurité indispensables, vous progresserez vers la compréhension des lois fondamentales et des composants passifs essentiels. Le livre aborde ensuite les composants semi-conducteurs modernes comme les diodes et les transistors, ainsi que les amplificateurs opérationnels, le tout agrémenté d\'exemples et d\'exercices pour une compréhension solide. Préparez-vous à acquérir une base solide pour maîtriser le monde fascinant de l\'électronique.','Basil1402 ,',0,'covers/l-electronique-de-zero.png','books/L electronique de zero.pdf',170,2012,1,6,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(272,'Le tri à paniers','le-tri-a-paniers','Découvrez le « tri à paniers », un algorithme de tri d\'entiers particulièrement astucieux, idéal pour optimiser l\'organisation de listes de nombres aux valeurs proches. Ce livre vous guide à travers son principe innovant de comptage des occurrences, illustré par des exemples concrets et une implémentation C++ claire et commentée. Enrichissez votre arsenal algorithmique avec cette méthode originale et acquérez une compréhension approfondie des techniques de tri efficaces et distinctives. Parfait pour les développeurs et étudiants, il offre une perspective précieuse sur l\'optimisation des structures de données.','GuilOooo',0,'covers/le-tri-a-paniers.png','books/Le tri a paniers.pdf',8,2010,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(273,'Faire une image anti- robots (ou captcha) facilement','faire-une-image-anti-robots-ou-captcha-facilement','Vous cherchez une solution efficace et simple pour protéger votre site web des robots spammeurs et des inscriptions indésirables ? Ce tutoriel détaillé vous guide pas à pas dans la création d\'un générateur de Captchas en PHP, exploitant la puissance du module GD pour des images dynamiques et aléatoires. D\'une difficulté \"Facile\", il vous montre comment, avec seulement quelques lignes de code, concevoir un système de vérification robuste, du script principal au formulaire et à la page de confirmation. Sécurisez vos interactions en ligne et vos données en toute simplicité !','Francois GAY (fecgay)',0,'covers/faire-une-image-anti-robots-ou-captcha-facilement.png','books/Faire une image anti robots ou captcha facilement.pdf',8,2010,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(274,'Créer des documents avec txt2tags','creer-des-documents-avec-txt2tags','Élevez votre création de documents au niveau supérieur avec txt2tags, un générateur multiplateforme qui dépasse les simples syntaxes wiki grâce à son puissant système de macros. Ce livre vous guide pas à pas, de l\'installation à l\'exploitation avancée, pour transformer aisément vos textes en une multitude de formats comme le HTML, le LaTeX ou les pages web. Maîtrisez cet outil polyvalent et rationalisez la production de vos articles, documentations ou livres, en profitant d\'une flexibilité et d\'une extensibilité inégalées.','farvardin',0,'covers/creer-des-documents-avec-txt2tags.png','books/Creer des documents avec txt2tags.pdf',19,2010,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(275,'Créez des applications en C# pour Windows Phone 8','creez-des-applications-en-c-pour-windows-phone-8','Plongez au cœur du développement mobile avec ce guide complet dédié à la création d\'applications Windows Phone 8 en C# et XAML. Des bases de Modern UI et des contrôles fondamentaux à la gestion avancée des données, des capteurs du téléphone et des interfaces utilisateur interactives, chaque étape est couverte avec clarté. Apprenez à concevoir des applications élégantes et performantes grâce à des explications détaillées, des exemples concrets et des travaux pratiques corrigés qui vous permettront de mettre immédiatement vos connaissances en œuvre. Ce livre est l\'outil indispensable pour transformer vos idées en applications fonctionnelles et innovantes, prêtes pour le Windows Phone Store.','nico.pyright',0,'covers/creez-des-applications-en-c-pour-windows-phone-8.png','books/Creez des applications en c pour windows phone 8.pdf',528,2013,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(276,'Développez votre site web avec le framework Django','developpez-votre-site-web-avec-le-framework-django','Maîtrisez le développement web avec le puissant framework Django grâce à ce guide complet et pratique. Du concept de framework aux techniques avancées de gestion des utilisateurs, de la base de données et de la mise en cache, ce livre vous accompagnera pas à pas dans la création de sites web performants. Apprenez à construire vos propres applications web, à personnaliser l\'administration et à intégrer des fonctionnalités complexes, que vous soyez un développeur débutant ou expérimenté. Lancez-vous et transformez vos idées en projets web concrets et professionnels.','Mathieu Xhonneux (MathX)',0,'covers/developpez-votre-site-web-avec-le-framework-django.png','books/Developpez votre site web avec le framework django.pdf',204,2013,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(277,'Des news sur votre site !','des-news-sur-votre-site','Boostez l\'interactivité de votre site web en apprenant à intégrer un système de news dynamique, le script PHP le plus populaire et utile ! Ce guide pratique, accessible même aux développeurs débutants, vous accompagnera pas à pas dans la création d\'un système complet, de l\'affichage des articles à la gestion d\'une administration sécurisée pour ajouter, modifier ou supprimer vos publications. Dites adieu aux mises à jour manuelles de vos pages HTML et offrez à vos visiteurs un contenu frais et régulièrement mis à jour, le tout avec une approche claire et des explications concrètes.','Mathieu Nebra (Mateo21)',0,'covers/des-news-sur-votre-site.png','books/Des news sur votre site (1).pdf',11,2011,1,4,'2026-07-29 08:53:17','2026-07-29 08:53:24'),(278,'Connaître et monter son PC','connaitre-et-monter-son-pc','Le rêve de monter son propre PC sur mesure, performant et économique, est à votre portée avec ce guide complet. Il vous accompagnera pas à pas, de la découverte détaillée de chaque composant (processeur, carte graphique, SSD...) à leur sélection éclairée pour définir une configuration optimale selon vos besoins. Apprenez ensuite à assembler votre machine étape par étape, puis à installer son système d\'exploitation, le tout illustré pour une parfaite compréhension. Que vous soyez novice ou passionné, ce livre démystifie la complexité pour vous offrir la satisfaction de maîtriser entièrement votre outil informatique.','AlBiNoSS ,',0,'covers/connaitre-et-monter-son-pc.png','books/Connaitre et monter son pc.pdf',72,2011,1,5,'2026-07-29 08:53:17','2026-07-29 08:53:17'),(279,'Une zForm avec Mootools','une-zform-avec-mootools','Plongez dans la création de formulaires interactifs et enrichis avec \"Une zForm avec Mootools\", un guide essentiel pour les développeurs souhaitant maîtriser l\'intégration d\'outils d\'édition avancés. Cet ouvrage vous mènera pas à pas dans l\'élaboration d\'un ZForm complet, exploitant la puissance du framework Mootools pour implémenter des fonctionnalités clés telles que l\'insertion de balises, les boutons à choix multiples et les listes déroulantes personnalisées. Apprenez à concevoir une prévisualisation dynamique en temps réel grâce à Ajax et PHP, offrant une expérience utilisateur fluide et moderne, idéale pour dynamiser vos applications web.','franckysolo',0,'covers/une-zform-avec-mootools.png','books/Une zform avec mootools.pdf',37,2012,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(280,'La programmation réseau en .NET','la-programmation-reseau-en-net','Plongez au cœur de la programmation réseau avec cet ouvrage complet dédié au .NET, conçu pour transformer vos ambitions en applications fonctionnelles. Ce guide exhaustif démystifie des concepts fondamentaux tels que les délégués et le multithreading, essentiels pour bâtir des solutions performantes et réactives. Vous explorerez ensuite la mise en œuvre pratique de la communication UDP et les techniques de sérialisation d\'objets, acquérant ainsi toutes les compétences pour développer des applications réseau robustes. Idéal pour les développeurs C# souhaitant maîtriser cet art, ce livre est la clé pour concrétiser vos projets les plus ambitieux.','gretro',0,'covers/la-programmation-reseau-en-net.png','books/La programmation reseau en net.pdf',99,2012,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(281,'Introduction à Vyatta','introduction-a-vyatta','Explorez Vyatta, la solution open-source qui transforme votre approche du routage et de la virtualisation réseau. Ce guide complet vous mène de l\'installation pas à pas de machines virtuelles à la configuration avancée des fonctions essentielles comme le NAT ou le VRRP, démystifiant au passage le rôle crucial d\'un routeur. Découvrez comment Vyatta, basé sur Debian et doté d\'une interface en ligne de commande intuitive comparable à IOS ou JUNOS, offre une alternative puissante et économique aux équipements propriétaires. Idéal pour les professionnels et les passionnés cherchant à bâtir des infrastructures réseau agiles et performantes, ce livre est votre tremplin vers une expertise moderne et maîtrisée.','Romain Guichard (Caelifer)',0,'covers/introduction-a-vyatta.png','books/Introduction a vyatta.pdf',14,2012,1,7,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(282,'Maîtrisez la 2D avec Photoshop','maitrisez-la-2d-avec-photoshop','Envie de transformer vos idées créatives en visuels époustouflants et de maîtriser le logiciel de référence en retouche et création 2D ? Ce guide complet, conçu pour les débutants, vous ouvre les portes de Photoshop en partant de zéro. Apprenez les fondamentaux de l\'imagerie numérique, installez et configurez le logiciel, puis explorez les opérations de base, le dessin numérique et le puissant concept des calques. Grâce à des explications claires et des applications pratiques, vous développerez rapidement les compétences nécessaires pour donner vie à toutes vos créations en 2D.','The maaaaan',0,'covers/maitrisez-la-2d-avec-photoshop.png','books/Maitrisez la 2d avec photoshop.pdf',85,2010,1,5,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(283,'Choisir une licence pour son tutoriel','choisir-une-licence-pour-son-tutoriel','En tant qu\'auteur de tutoriels, vous vous interrogez sur la protection de votre travail et les conditions de sa diffusion en ligne ? Ce guide essentiel vous éclaire sur le droit d\'auteur, ses mécanismes fondamentaux et la puissance des licences pour gérer l\'utilisation de vos créations.\n\nDécouvrez les différentes options disponibles, du droit d\'auteur simple aux licences de libre diffusion et Creative Commons, et apprenez à choisir et appliquer concrètement la licence la plus adaptée à vos contenus. Maîtrisez les outils nécessaires pour protéger efficacement votre propriété intellectuelle tout en favorisant un partage maîtrisé de votre savoir.','bluestorm',0,'covers/choisir-une-licence-pour-son-tutoriel.png','books/Choisir une licence pour son tutoriel.pdf',6,2012,1,7,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(284,'Apprendre à dessiner en 3D avec AutoCAD','apprendre-a-dessiner-en-3d-avec-autocad','Plongez dans le monde de la conception assistée par ordinateur avec \"Apprendre à dessiner en 3D avec AutoCAD\", un guide indispensable pour maîtriser ce logiciel professionnel. Que vous soyez novice ou en quête de perfectionnement, cet ouvrage vous accompagnera pas à pas, de la découverte de l\'interface et des fondamentaux du dessin 2D à la modélisation 3D avancée. Apprenez à créer des objets complexes, appliquer des textures réalistes et réaliser des présentations percutantes pour tous vos projets. Développez une expertise concrète pour transformer vos idées en plans de fabrication précis et en rendus saisissants, et ainsi exceller dans de nombreuses industries.','Sébastien NASLES (sebmag)',0,'covers/apprendre-a-dessiner-en-3d-avec-autocad.png','books/Apprendre a dessiner en 3d avec autocad.pdf',240,2012,1,7,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(285,'La géométrie plane','la-geometrie-plane','Intimidé par la géométrie, ses théorèmes et la trigonométrie ? Plongez dans \"La géométrie plane\", le guide idéal pour maîtriser cette discipline depuis ses fondements. De l\'histoire fascinante d\'Euclide et Descartes aux applications concrètes des théorèmes de Thalès et de Pythagore, en passant par les mystères de la trigonométrie et le calcul des aires, ce cours vous offre une exploration complète et ludique. Conçu pour les débutants comme pour ceux qui souhaitent réviser, cet ouvrage démystifie les concepts complexes et rend la géométrie plane accessible et passionnante, même pour les plus réticents.','Mickaël Launay (GéoMl17)',0,'covers/la-geometrie-plane.png','books/La geometrie plane.pdf',108,2013,1,6,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(286,'Un système de news sans base de données grâce à serialize et unserialize','un-systeme-de-news-sans-base-de-donnees-grace-a-serialize-et-unserialize','Fatigué de la complexité des bases de données pour vos projets web simples ? Découvrez une approche innovante pour développer un système de news léger et ultra-rapide en exploitant astucieusement les fonctions `serialize` et `unserialize` de PHP. Ce guide pratique vous montrera comment gérer l\'affichage, l\'ajout et la suppression d\'articles sans jamais avoir à configurer ni interroger une base de données relationnelle. Idéal pour les sites personnels ou les modules nécessitant une gestion de données simple et directe, ce tutoriel rend le développement accessible et étonnamment efficace.','Christophe Tafani-Dereeper (christophetd)',0,'covers/un-systeme-de-news-sans-base-de-donnees-grace-a-serialize-et-unserialize.png','books/Un systeme de news sans base de donnees grace a serialize et unserialize.pdf',10,2012,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(287,'Sécurisez vos mots de passe avec Lastpass','securisez-vos-mots-de-passe-avec-lastpass','Frustré par la complexité des mots de passe et les risques liés à leur réutilisation sur de multiples sites ? Dites adieu au casse-tête des identifiants et bonjour à une sécurité numérique sans effort grâce à LastPass. Ce guide pratique vous accompagnera pas à pas, de l\'installation à la maîtrise de ce gestionnaire révolutionnaire, vous permettant de générer, stocker et utiliser des mots de passe uniques et robustes pour tous vos comptes. Sécurisez votre vie en ligne de manière simple et efficace, et profitez pleinement de la tranquillité d\'esprit.','Mathieu Nebra (Mateo21)',0,'covers/securisez-vos-mots-de-passe-avec-lastpass.png','books/Securisez vos mots de passe avec lastpass.pdf',22,2013,1,6,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(288,'Déployez vos projets web facilement avec WebMatrix !','deployez-vos-projets-web-facilement-avec-webmatrix','Simplifiez radicalement le déploiement de vos projets web grâce à ce guide complet sur WebMatrix. Découvrez cet outil tout-en-un de Microsoft qui regroupe l\'édition de code, l\'administration de bases de données, les tests SEO et la publication de vos sites, vous évitant de jongler entre de multiples logiciels. Que vous travailliez avec WordPress, Joomla ou d\'autres technologies open source, ce livre vous montrera comment gagner un temps précieux en automatisant les installations et configurations. Apprenez à maîtriser WebMatrix et transformez la gestion de vos projets web en un processus fluide et efficace.','Mathieu Nebra (Mateo21)',0,'covers/deployez-vos-projets-web-facilement-avec-webmatrix.png','books/Deployez vos projets web facilement avec webmatrix.pdf',42,2012,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(289,'Développez votre site web avec le framework Symfony2','developpez-votre-site-web-avec-le-framework-symfony2','Prêt à construire des applications web robustes et efficaces ? Ce livre vous guide pas à pas pour maîtriser Symfony2, l\'un des frameworks PHP les plus puissants et populaires du marché. Vous explorerez ses fondamentaux, de l\'architecture MVC aux routes, contrôleurs, templates Twig et services, tout en intégrant la gestion de bases de données avec Doctrine2 et l\'automatisation avec Composer. À travers un projet de blog concret, vous développerez des compétences pratiques pour créer des sites web professionnels et évolutifs.','Alexandre Bacco (winzou)',0,'covers/developpez-votre-site-web-avec-le-framework-symfony2.png','books/Developpez votre site web avec le framework symfony2.pdf',384,2013,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(290,'Exécuter des fonctions mathématiques avec Grapher','executer-des-fonctions-mathematiques-avec-grapher','Plongez dans l\'univers de Grapher, l\'utilitaire graphique intégré à Mac OS X, et transformez l\'apprentissage des fonctions mathématiques en une expérience visuelle captivante. Que vous soyez lycéen ou étudiant, ce guide pas à pas vous accompagnera de la création de graphes 2D et 3D simples aux courbes paramétrées complexes, tout en consolidant vos connaissances en mathématiques. Apprenez à explorer les zones d\'équations, les animations et les options de personnalisation pour maîtriser Grapher et donner vie à vos équations avec une facilité déconcertante. C\'est l\'outil idéal pour visualiser et comprendre les mathématiques au-delà des formules.','Bean-Flayers',0,'covers/executer-des-fonctions-mathematiques-avec-grapher.png','books/Executer des fonctions mathematiques avec grapher.pdf',13,2010,1,6,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(291,'La programmation scientifique avec Python','la-programmation-scientifique-avec-python','Explorez l\'univers de la programmation scientifique et transformez Python en un puissant allié pour vos calculs numériques. Ce livre vous guide pas à pas dans l\'exploitation des bibliothèques fondamentales comme NumPy, Matplotlib et SciPy, vous permettant de manipuler des données complexes, de créer des visualisations éloquentes et de résoudre des problèmes mathématiques ardus. Que vous cherchiez une alternative gratuite et performante à des outils comme Matlab ou un complément pratique à vos codes C/Fortran, vous y trouverez toutes les clés pour optimiser vos algorithmes. Maîtrisez les techniques essentielles, de la résolution de systèmes linéaires aux transformées de Fourier, et propulsez vos projets scientifiques avec Python.','dramac.nicolas',0,'covers/la-programmation-scientifique-avec-python.png','books/La programmation scientifique avec python.pdf',35,2012,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(292,'Des widgets en 3D avec Qt','des-widgets-en-3d-avec-qt','Envie d\'apporter une dimension supplémentaire à vos interfaces Qt ? Ce livre vous révèle comment créer et manipuler des widgets et objets en 3D directement au sein de vos applications, sans recourir à des bibliothèques externes complexes. Plongez dans l\'univers des `QGraphicsItem` pour maîtriser les transformations, les rotations, les mouvements et même la gestion avancée de la caméra, simulant parfaitement la profondeur dans une scène 2D. Idéal pour les développeurs Qt intermédiaires, ce guide vous offre les clés pour dynamiser vos créations et offrir une expérience utilisateur immersive.','Midnight Falcon',0,'covers/des-widgets-en-3d-avec-qt.png','books/Des widgets en 3d avec qt.pdf',17,2010,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(293,'[OCaml] Les flots de données','ocaml-les-flots-de-donnees','Plongez au cœur des flots de données (streams) en OCaml, un outil puissant et unique, idéal pour la construction d\'analyseurs syntaxiques descendants et la gestion de séquences potentiellement infinies. Ce livre explore en détail leurs caractéristiques clés – du calcul paresseux à leur nature destructive – vous guidant de la théorie à la manipulation pratique. À travers des explications claires et des exemples concrets, notamment leur intégration avec `camlp4`, vous développerez une expertise précieuse pour des applications OCaml plus élégantes et performantes.','Olivier Strebler (shareman)',0,'covers/ocaml-les-flots-de-donnees.png','books/Ocaml les flots de donnees.pdf',11,2012,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(294,'Passer du latin1 à l\'unicode','passer-du-latin1-a-lunicode','Fatigué des limitations de Latin1 et des caractères inattendus sur votre site web ? Ce guide pratique vous offre la solution pour une compatibilité linguistique et universelle, en vous aidant à migrer vers l\'Unicode (UTF-). De la préparation de votre environnement PHP à l\'encodage de vos fichiers et bases de données, en passant par la gestion des entêtes HTTP, chaque étape est expliquée de manière claire et structurée. Conçu avec une difficulté \"Facile\", ce livre vous permettra de résoudre les défis complexes de l\'encodage et de garantir que votre contenu est parfaitement lisible, quelle que soit la langue.','Victor Thuillier (vyk12)',0,'covers/passer-du-latin1-a-l-unicode.png','books/Passer du latin1 a l unicode.pdf',11,2011,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(295,'Aligner ses formulaires sans tableaux','aligner-ses-formulaires-sans-tableaux','Vous en avez assez des formulaires web désordonnés et difficiles à aligner ? Découvrez ce guide essentiel qui vous apprendra à structurer vos formulaires avec une élégance irréprochable, sans avoir recours aux tableaux ni à une surcharge de `<div>`. Grâce à des techniques CSS modernes et l\'utilisation intelligente des balises `<label>`, ce tutoriel vous offre une solution simple et accessible pour créer des interfaces claires et professionnelles. Améliorez l\'expérience utilisateur de vos sites web en transformant des formulaires chaotiques en des éléments parfaitement alignés et stylisés.','Romain128',0,'covers/aligner-ses-formulaires-sans-tableaux.png','books/Aligner ses formulaires sans tableaux.pdf',6,2011,1,5,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(296,'Débugger avec Qt','debugger-avec-qt','Face aux erreurs tenaces qui ralentissent vos développements C++ avec Qt, ce guide essentiel vous équipe pour un débuggage efficace et méthodique. Découvrez les outils et techniques spécifiques à Qt pour traquer les bugs, qu\'il s\'agisse d\'applications complètes ou de librairies complexes, là où les debuggers traditionnels atteignent leurs limites. Apprenez à optimiser l\'affichage des messages, à gérer les modes de compilation et à intégrer des fonctions de diagnostic avancées directement dans votre code pour un suivi précis. Transformez la frustration du débuggage en une compétence maîtrisée et indispensable pour tout développeur Qt souhaitant produire un code robuste.','Julien Rosset (Darkelfe)',0,'covers/debugger-avec-qt.png','books/Debugger avec qt.pdf',12,2011,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(297,'Faire un Demon sous Linux','faire-un-demon-sous-linux','Vous rêvez d\'automatiser le lancement de vos scripts et services essentiels dès le démarrage de votre machine Linux, sans aucune intervention de votre part ? Ce guide pratique vous plonge au cœur de la création et de la gestion des démons Linux, ces programmes qui opèrent discrètement en arrière-plan pour assurer la robustesse de votre système. Apprenez pas à pas à configurer un démon, à utiliser `update-rc.d`, à le supprimer, et découvrez les spécificités d\'installation pour Debian, Ubuntu, Fedora ou ArchLinux, le tout avec des pré-requis abordables et des exemples concrets.','Gabriel JUCHAULT (Extaze)',0,'covers/faire-un-demon-sous-linux.png','books/Faire un demon sous linux.pdf',9,2011,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(298,'Du décimal au binaire','du-decimal-au-binaire','Découvrez comment votre ordinateur pense et manipule les nombres avec \"Du décimal au binaire\", le guide indispensable pour maîtriser les systèmes de numération ! Ce livre explore en profondeur le passage du décimal, notre système quotidien, au binaire, fondamental pour les machines, sans oublier les bases octale et hexadécimale. Vous y apprendrez des méthodes pratiques et des applications algorithmiques concrètes, tout en comprenant les justifications mathématiques sous-jacentes. Que vous soyez développeur en herbe ou simplement curieux de la logique informatique, ce tutoriel complet et accessible vous donnera les clés pour jongler avec aisance entre les différentes bases numériques.','Dentuk',0,'covers/du-decimal-au-binaire.png','books/Du decimal au binaire.pdf',13,2011,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(299,'Installer un réseau Wi-Fi sur Ubuntu et dérivés','installer-un-reseau-wi-fi-sur-ubuntu-et-derives','Fatigué des problèmes de reconnaissance de votre carte ou clé Wi-Fi sous Ubuntu et ses dérivés ? Ce livre est la solution indispensable pour enfin connecter votre machine à Internet sans fil. Il vous guide pas à pas, de la vérification de la compatibilité native à l\'installation des pilotes via l\'astucieux Ndiswrapper, y compris la configuration de votre connexion. Retrouvez une connexion Wi-Fi stable et fonctionnelle, même si votre matériel n\'est pas nativement supporté, grâce à des explications claires et détaillées.','Firemann',0,'covers/installer-un-reseau-wi-fi-sur-ubuntu-et-derives.png','books/Installer un reseau wi fi sur ubuntu et derives.pdf',13,2010,1,7,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(300,'Accès sécurisé à des documents','acces-securise-a-des-documents','Besoin de protéger l\'accès à des documents sensibles sur votre site web, au-delà des méthodes conventionnelles ? Ce livre détaille une approche complète pour sécuriser la diffusion de vos fichiers, en limitant l\'accès aux seuls membres authentifiés et autorisés. Apprenez à concevoir une architecture robuste combinant un contrôle strict des répertoires, une base de données flexible pour les droits et un code PHP intelligent pour l\'authentification et la livraison des documents. Maîtrisez la sécurité de vos contenus et offrez un accès fiable et personnalisé à vos utilisateurs.','P\'titMat',0,'covers/acces-securise-a-des-documents.png','books/Acces securise a des documents.pdf',13,2010,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(301,'Les arbres de Galton- Watson','les-arbres-de-galton-watson','Vous êtes-vous déjà demandé comment prédire la survie d\'une lignée familiale ou l\'extinction d\'un nom à travers les générations ? Ce livre vous invite à explorer les arbres de Galton-Watson, un modèle mathématique probabiliste conçu pour décrypter la dynamique des descendances aléatoires. Découvrez les fondements de ce concept historique et apprenez à calculer les probabilités d\'extinction ou de survie, des noms de famille aux populations. Une ressource précieuse pour les étudiants et passionnés de probabilités souhaitant appliquer la théorie à des questions concrètes et intrigantes.','Mickaël Launay (GéoMl17)',0,'covers/les-arbres-de-galton-watson.png','books/Les arbres de galton watson.pdf',23,2011,1,6,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(302,'Développement C# (.NET)','developpement-c-net','Plongez dans l\'univers du développement C# (.NET) avec ce guide complet, conçu pour les néophytes comme pour les développeurs souhaitant enrichir leurs compétences. De l\'architecture fondamentale du .NET à la maîtrise des types de données, boucles et conditions, vous acquerrez une solide base algorithmique. Explorez en profondeur la Programmation Orientée Objet (POO) à travers ses concepts clés – classes, objets, encapsulation, héritage – et mettez vos connaissances en pratique grâce à un projet de jeu de rôle captivant. Chaque chapitre est ponctué d\'exercices et de corrections, assurant une progression pédagogique et une compréhension durable pour maîtriser le développement d\'applications robustes.','JCVasselon ,',0,'covers/developpement-c-net.png','books/Developpement c net.pdf',89,2013,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(303,'Géolocalisez vos visiteurs grâce à leur IP','geolocalisez-vos-visiteurs-grace-a-leur-ip','Que ce soit pour des statistiques affinées, la personnalisation de l\'expérience utilisateur ou la détection de comportements spécifiques, la géolocalisation de vos visiteurs est un atout indéniable. Ce guide pratique vous propose une approche simple et autonome pour y parvenir, en exploitant la puissance de la base de données GeoLite de MaxMind et de l\'API PHP. Apprenez à récupérer des informations clés telles que le pays, la ville, et les coordonnées géographiques de chaque adresse IP, directement depuis votre serveur. Maîtrisez cette compétence essentielle pour une meilleure connaissance de votre audience et une personnalisation accrue de vos services.','matheod',0,'covers/geolocalisez-vos-visiteurs-grace-a-leur-ip.png','books/Geolocalisez vos visiteurs grace a leur ip.pdf',8,2012,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(304,'Le tri à bulles','le-tri-a-bulles','Découvrez \"Le tri à bulles\", l\'algorithme de tri le plus intuitif et souvent le premier que l\'on rencontre en débutant en informatique. Ce livre didactique vous guide pas à pas, du principe simple et illustré de ce tri élémentaire jusqu\'à son implémentation concrète, en passant par l\'analyse de sa complexité. Que vous soyez novice ou cherchiez à solidifier vos bases, maîtrisez cet algorithme fondamental et explorez même ses variantes pour une compréhension approfondie. Un incontournable pour quiconque souhaite comprendre les mécanismes essentiels du tri de données.','Olivier Strebler (shareman)',0,'covers/le-tri-a-bulles.png','books/Le tri a bulles.pdf',7,2011,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(305,'Débusquer et apprivoiser les bugsen C','debusquer-et-apprivoiser-les-bugsen-c','Vos programmes C compilent, mais refusent de se comporter comme prévu ou plantent sans explication ? Ce livre est votre guide indispensable pour débusquer et maîtriser les bugs les plus courants en C, notamment les fameux comportements indéterminés qui déroutent tant de développeurs. Vous apprendrez à décrypter les messages du compilateur, à exploiter pleinement le debugger et à identifier les pièges liés à la mémoire, aux fichiers ou aux modifications de valeurs. Armé de conseils pratiques pour une écriture de code plus claire et préventive, transformez vos frustrations en maîtrise et apprivoisez définitivement les caprices de vos programmes C.','GuilOooo',0,'covers/debusquer-et-apprivoiser-les-bugsen-c.png','books/Debusquer et apprivoiser les bugs en c.pdf',18,2012,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(306,'Space Art sur Photoshop','space-art-sur-photoshop','Explorez l\'univers infini de la création numérique avec \"Space Art sur Photoshop\", le guide ultime pour concevoir des scènes cosmiques époustouflantes. Ce livre vous emmène étape par étape dans l\'art de donner vie à des planètes détaillées, des soleils éclatants et des nébuleuses mystérieuses, en explorant des techniques de texturisation, de colorisation et d\'intégration d\'éléments avancés comme les fractales. Idéal pour les utilisateurs intermédiaires de Photoshop, il vous offre des instructions claires et complètes pour transformer vos visions de l\'espace et de la science-fiction en de magnifiques œuvres d\'art digital. Préparez-vous à repousser les limites de votre créativité et à maîtriser l\'art de l\'espace.','Licoti',0,'covers/space-art-sur-photoshop.png','books/Space art sur photoshop.pdf',131,2012,1,6,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(307,'Développer sur Microsoft Surface','developper-sur-microsoft-surface','Plongez dans le monde fascinant du développement multi-touch avec ce guide dédié à la première génération de Microsoft Surface, l\'innovante table interactive. Face à la rareté des ressources, cet ouvrage vous équipe pour maîtriser le SDK Surface, de l\'installation du simulateur à la création d\'applications complexes. Découvrez l\'intégration avec WPF et XNA, apprenez à gérer les contacts tactiles, les tags, les manipulations gestuelles et l\'inertie pour des interfaces intuitives et immersives. Idéal pour les développeurs C# et WPF souhaitant explorer les fondements du multi-touch sur Windows, ce livre vous ouvrira les portes des interactions sans souris ni clavier.','Strimy',0,'covers/developper-sur-microsoft-surface.png','books/Developper sur microsoft surface.pdf',87,2011,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(308,'[C++] Maîtriser le compilateur g++','c-maitriser-le-compilateur-g','Vous utilisez g++ pour vos projets C++, mais souhaitez en maîtriser toutes les subtilités et transformer cet outil en un véritable allié ? Ce livre vous guide pas à pas à travers les rouages essentiels du compilateur, du préprocesseur à l\'étape d\'assemblage, pour démystifier son fonctionnement. Découvrez comment exploiter ses nombreuses options pour affiner la compilation, gérer efficacement les warnings et optimiser la taille ou la vitesse de vos programmes. Que vous travailliez sous Code::Blocks ou en ligne de commande Linux, produisez un code C++ plus performant et sans surprise.','Matthieu Schaller (Nanoc)',0,'covers/c-maitriser-le-compilateur-g.png','books/C maitriser le compilateur g.pdf',13,2011,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(309,'Les shaders en GLSL','les-shaders-en-glsl','Vous rêvez de créer les effets 3D spectaculaires des jeux vidéo modernes, tels que l\'eau réaliste, le HDR ou le cel-shading ? Ce guide complet vous ouvre les portes de la programmation de shaders en GLSL, en vous guidant des fondamentaux de la création et compilation jusqu\'à l\'implémentation de fonctionnalités avancées comme la gestion des lumières et la manipulation de textures. Apprenez à faire communiquer efficacement votre application avec la carte graphique grâce aux attributs et uniforms, et maîtrisez les bases mathématiques essentielles des vecteurs pour des rendus époustouflants. Plongez dans le monde fascinant de la programmation GPU et transformez vos visions graphiques en réalité.','Yno',0,'covers/les-shaders-en-glsl.png','books/Les shaders en glsl.pdf',84,2012,1,4,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(310,'Débuter dans l\'infographie avec GIMP !','debuter-dans-linfographie-avec-gimp','Plongez dans le monde de l\'infographie avec ce guide complet dédié à GIMP, le logiciel libre et gratuit incontournable pour la retouche photo, le montage et la création graphique. Que vous soyez novice ou désireux d\'améliorer vos compétences, ce livre vous accompagnera pas à pas, de l\'installation du logiciel à la maîtrise des calques, des sélections et du détourage. Grâce à des explications claires et de nombreux travaux pratiques, vous développerez rapidement les techniques essentielles pour transformer vos idées en images saisissantes.','GreenSun',0,'covers/debuter-dans-l-infographie-avec-gimp.png','books/Debuter dans l infographie avec gimp.pdf',151,2012,1,5,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(311,'Débuter sur Adobe Photoshop !','debuter-sur-adobe-photoshop','Plongez dans l\'univers d\'Adobe Photoshop avec ce guide complet et progressif, conçu spécifiquement pour les débutants. Il vous accompagnera de la découverte de l\'interface et des fondamentaux essentiels jusqu\'aux techniques de retouche photographique avancées et à la création graphique sous toutes ses formes, y compris pour le web. Grâce à des explications claires et de nombreux ateliers pratiques, vous développerez rapidement les compétences indispensables pour concrétiser toutes vos idées visuelles et maîtriser ce logiciel incontournable du design. Ce livre est la clé pour transformer vos images et libérer votre créativité numérique.','Yannick Piault (sp0z)',0,'covers/debuter-sur-adobe-photoshop.png','books/Debuter sur adobe photoshop.pdf',635,2013,1,5,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(312,'De la musique avec Caml','de-la-musique-avec-caml','Découvrez comment allier la puissance de la programmation avec le plaisir de la musique grâce à \"De la musique avec Caml\". Ce tutoriel accessible vous guide pas à pas dans l\'installation de Caml-Light et l\'utilisation de sa librairie Graphics pour transformer vos partitions en mélodies audibles. Idéal pour les débutants, apprenez à coder vos airs favoris, du Requiem au thème de Tetris, et manipulez le tempo pour donner vie à vos créations sonores en un temps record. Une introduction ludique et pratique au développement musical.','iansus',0,'covers/de-la-musique-avec-caml.png','books/De la musique avec caml.pdf',7,2012,1,7,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(313,'L\'orthotypographie : bien écrire pour bien être lu','lorthotypographie-bien-ecrire-pour-bien-etre-lu','Fatigué des documents numériques qui manquent de clarté et de professionnalisme ? \"L\'orthotypographie : bien écrire pour bien être lu\" est votre guide indispensable pour transformer vos écrits et garantir leur impact. Découvrez les règles essentielles de la typographie française, de l\'accentuation des capitales à l\'usage correct des ponctuactions, des abréviations et des caractères spéciaux. Ce livre pratique vous apprendra à maîtriser les outils et à appliquer les normes pour rendre vos textes impeccables, lisibles et véritablement professionnels, quel que soit votre logiciel de traitement de texte. Ne laissez plus jamais une mauvaise présentation nuire à la compréhension de votre message.','TD',0,'covers/l-orthotypographie-bien-ecrire-pour-bien-etre-lu.png','books/L orthotypographie bien ecrire pour bien etre lu.pdf',13,2012,1,6,'2026-07-29 08:53:18','2026-07-29 08:53:18'),(314,'Introduction à l\'édition de texte avancée : l\'exemple de GNU Nano','introduction-a-ledition-de-texte-avancee-lexemple-de-gnu-nano','Plongez dans l\'univers de l\'édition de texte avancée grâce à ce guide pratique, qui utilise GNU Nano comme tremplin idéal pour maîtriser des techniques d\'une redoutable efficacité. Loin de se limiter à un simple répertoire de commandes, cet ouvrage vous enseigne les stratégies d\'édition pour manipuler vos fichiers avec une rapidité et une fluidité accrues, optimisant significativement votre flux de travail. Que vous soyez familier avec Nano ou désireux d\'explorer les avantages des éditeurs console, ce livre vous dotera des compétences essentielles pour une productivité décuplée et un gain de temps considérable.','mist',0,'covers/introduction-a-l-edition-de-texte-avancee-l-exemple-de-gnu-nano.png','books/Introduction a l edition de texte avancee l exemple de gnu nano.pdf',8,2009,1,7,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(315,'Programmez sur votre DS avec MicroLua','programmez-sur-votre-ds-avec-microlua','Rêvez-vous de créer vos propres jeux et applications sur votre Nintendo DS ? Ce guide complet, \"Programmez sur votre DS avec MicroLua\", est conçu pour vous initier au développement sur cette console emblématique, même si vous n\'avez que des bases en programmation. Explorez l\'environnement MicroLua et apprenez à manipuler les graphiques, animer des sprites, intégrer du son, gérer les interactions avec les joueurs, et bien plus encore. Des premiers pas à la conception de jeux complexes avec des cartes défilantes et la gestion de fichiers, transformez vos idées en réalité et donnez une nouvelle vie à votre DS.','Reylak',0,'covers/programmez-sur-votre-ds-avec-microlua.png','books/Programmez sur votre ds avec microlua.pdf',59,2011,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(316,'Unity3D : Création d\'un menu avec curseur personnalisé','unity3d-creation-dun-menu-avec-curseur-personnalise','Vous avez créé un jeu passionnant avec Unity3D et souhaitez lui offrir une interface utilisateur professionnelle ? Ce tutoriel \"Facile\" vous guide pas à pas dans la création d\'un menu de jeu interactif, incluant le chargement de scènes, l\'ajout d\'un curseur personnalisé et l\'intégration d\'effets sonores. De la mise en place du fond visuel à la programmation des scripts pour les interactions (agrandissement au survol, changement de couleur), chaque étape est clairement expliquée pour un résultat impeccable. Maîtrisez les techniques pour élever l\'expérience utilisateur de votre jeu et lui donner la touche finale qu\'il mérite.','Devmath',0,'covers/unity3d-creation-d-un-menu-avec-curseur-personnalise.png','books/Unity3d creation d un menu avec curseur personnalise.pdf',13,2012,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(317,'Les captchas anti-bot','les-captchas-anti-bot','Faites-vous face à une invasion de bots et de spam sur votre site web ? \"Les captchas anti-bot\" est le guide essentiel pour tout développeur PHP souhaitant maîtriser la création de systèmes de vérification robustes et personnalisés. Plongez dans l\'art de concevoir des captchas textuels intelligents, des défis graphiques sophistiqués utilisant la bibliothèque GD et des matrices de convolution, jusqu\'à l\'intégration de captchas audio via la manipulation avancée de fichiers binaires. Ce cours pratique ne se contente pas de vous protéger des robots ; il vous enseigne également des notions informatiques complexes et des outils PHP méconnus, transformant ainsi votre expertise en développement web sécurisé.','nax',0,'covers/les-captchas-anti-bot.png','books/Les captchas anti bot.pdf',31,2010,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(318,'Les animations optimisées avec SDL','les-animations-optimisees-avec-sdl','Marre des animations SDL qui rament ? Ce guide essentiel est conçu pour les développeurs expérimentés souhaitant maîtriser l\'optimisation du rafraîchissement des images. Découvrez comment dépasser la méthode naïve grâce à des techniques avancées comme le clipping, réduisant ainsi drastiquement la charge de traitement. Maîtrisez ces approches pour créer des animations fluides et performantes, et donnez une nouvelle dimension à l\'efficacité de vos applications SDL.','Arthurus',0,'covers/les-animations-optimisees-avec-sdl.png','books/Les animations optimisees avec sdl.pdf',22,2010,1,7,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(319,'Sécuriser son serveur Linux','securiser-son-serveur-linux','Protégez votre infrastructure avec \"Sécuriser son serveur Linux\", le guide essentiel pour tout administrateur désireux de maîtriser les fondations de la cybersécurité. De la configuration avancée de votre pare-feu à la détection proactive d\'intrusions avec des outils comme Fail2ban et Snort, ce livre vous initie aux meilleures pratiques. Renforcez efficacement la défense de votre serveur contre les menaces courantes et validez sa résilience grâce à des méthodes de test éprouvées.','Binabik',0,'covers/securiser-son-serveur-linux.png','books/Securiser son serveur linux.pdf',14,2009,1,5,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(320,'Réalisation d\'un overview','realisation-dun-overview','Transformez vos créations de cartes de jeu et offrez une expérience utilisateur irréprochable grâce à des overviews professionnels. Ce guide pas-à-pas lève le voile sur la réalisation de ces mini-cartes essentielles, vous permettant de différencier vos maps et de guider efficacement vos joueurs. Apprenez à prendre le screenshot parfait, à l\'éditer avec les logiciels les plus populaires et à l\'intégrer sans accroc, tout en contournant les pièges classiques. Un tutoriel clair et complet pour élever la qualité de vos cartes et faciliter la navigation de tous.','Piltokc',0,'covers/realisation-d-un-overview.png','books/Realisation d un overview.pdf',9,2011,1,7,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(321,'La représentation intervallaire','la-representation-intervallaire','Face aux défis de la gestion de données hiérarchiques, souvent ralentie par l\'héritage récursif, découvrez la puissance de la Représentation Intervallaire (RI). Ce guide essentiel vous propose une méthode élégante et performante pour structurer et manipuler des arborescences complexes, des forums aux catégories produits, en évitant les lourdeurs des approches traditionnelles. Maîtrisez la théorie des bornes gauches et droites et explorez des exemples SQL concrets pour optimiser la lecture, la mise à jour et la navigation au sein de vos données. Adoptez cette approche innovante pour une gestion de hiérarchie fluide et d\'une efficacité redoutable.','Baptiste Clavié (Talus)',0,'covers/la-representation-intervallaire.png','books/La representation intervallaire.pdf',20,2010,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(322,'RPG Maker XP','rpg-maker-xp','Lancez-vous dans la création de votre propre jeu de rôle 2D avec RPG Maker XP, un logiciel accessible qui ne requiert aucune connaissance en programmation. Ce guide pas à pas vous mènera de la conception de cartes captivantes à la gestion des événements complexes, en passant par l\'utilisation des variables et la personnalisation approfondie de votre univers grâce à la base de données. Apprenez concrètement grâce à des exercices pratiques et des travaux dirigés stimulants, comme la création d\'un système bancaire fonctionnel, pour maîtriser toutes les facettes de la conception de jeux. Donnez vie à vos histoires et émerveillez les joueurs, sans aucun prérequis technique.','Dark Patate ,',0,'covers/rpg-maker-xp.png','books/Rpg maker xp.pdf',75,2011,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(323,'Réaliser un triple boot sur un MacBook Pro 8','realiser-un-triple-boot-sur-un-macbook-pro-8','Débloquez tout le potentiel de votre MacBook Pro 8 grâce à ce guide expert pour réaliser un triple boot performant. Apprenez à intégrer harmonieusement macOS, Windows et Ubuntu sur votre machine, vous permettant d\'exécuter toutes vos applications natives avec les pleines performances de votre matériel, sans recours à la virtualisation. Idéal pour les étudiants ou les professionnels exigeants, ce livre vous montrera comment configurer rEFIt et gérer vos trois systèmes d\'exploitation pour transformer votre MacBook Pro en une station de travail véritablement polyvalente.','Flohw',0,'covers/realiser-un-triple-boot-sur-un-macbook-pro-8.png','books/Realiser un triple boot sur un macbook pro 8.pdf',14,2012,1,7,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(324,'Apprendre à utiliser Doctrine','apprendre-a-utiliser-doctrine','Simplifiez radicalement vos interactions avec les bases de données dans vos projets PHP grâce à cet ouvrage dédié à Doctrine, l\'ORM incontournable pour des applications robustes et bien structurées. Ce guide complet vous accompagnera pas à pas, de la prise en main des concepts fondamentaux et de l\'installation, jusqu\'à la manipulation avancée des données et la création d\'un CRUD complet. Vous y explorerez les puissants Events Listeners, les templates (behaviors) tels que Timestampable ou SoftDelete, et apprendrez même à créer le vôtre. Idéal pour les développeurs PHP intermédiaires désireux d\'optimiser leur gestion des données, ce livre transformera votre approche de la persistance objet-relationnel avec des exemples concrets et des TPs formateurs.','Cybermanu',0,'covers/apprendre-a-utiliser-doctrine.png','books/Apprendre a utiliser doctrine.pdf',66,2011,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(325,'A la découverte d\'UNIX (FreeBSD)','a-la-decouverte-dunix-freebsd','Plongez au cœur d\'UNIX, le système d\'exploitation fondateur qui continue d\'inspirer les architectures modernes, à travers ce guide complet dédié à FreeBSD. Que vous soyez novice ou expérimenté, vous débuterez avec l\'environnement prêt à l\'emploi de PC-BSD avant de maîtriser l\'installation et la personnalisation de FreeBSD, de la construction d\'une interface graphique à la gestion des périphériques. Ce livre vous permettra d\'explorer les profondeurs de l\'administration système, de la configuration réseau avancée à la création de scripts puissants, pour une compréhension approfondie du \"roi des OS\".','Brice Errandonea',0,'covers/a-la-decouverte-d-unix-freebsd.png','books/A la decouverte d unix freebsd.pdf',247,2012,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(326,'Rédigez facilement des documents avec Word','redigez-facilement-des-documents-avec-word','Découvrez comment maîtriser Word pour créer des documents professionnels sans effort. Ce guide complet vous emmène des bases de la mise en page à l\'intégration d\'illustrations percutantes et l\'utilisation experte des styles pour une cohérence parfaite. Optimisez votre productivité et donnez une touche d\'excellence à tous vos écrits, du simple courrier au rapport complexe.','MichelMartin',0,'covers/redigez-facilement-des-documents-avec-word.png','books/Redigez facilement des documents avec word.pdf',391,2012,1,6,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(327,'Utiliser la zone de notifications','utiliser-la-zone-de-notifications','Envie d\'offrir une présence discrète mais efficace à vos applications Windows ? Ce tutoriel pratique vous guide pas à pas pour maîtriser la zone de notifications, permettant à vos logiciels d\'afficher des icônes, des bulles de messages et des menus contextuels directement depuis la barre des tâches. Idéal pour les développeurs Visual Basic et C#, ce guide est conçu pour rendre vos applications plus professionnelles et conviviales, même si vous débutez. Découvrez comment intégrer facilement cette fonctionnalité essentielle et offrir une meilleure expérience utilisateur.','Maxime Jumelle (L1ne)',0,'covers/utiliser-la-zone-de-notifications.png','books/Utiliser la zone de notifications.pdf',16,2011,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(328,'Bruits et nombres aléatoires cohérents','bruits-et-nombres-aleatoires-coherents','Vous rêvez de générer des terrains réalistes, des nuages dynamiques ou des textures organiques pour vos projets informatiques ? Loin de l\'aléatoire \"naïf\" et son rendu chaotique, ce livre vous plonge dans l\'univers des bruits et nombres aléatoires cohérents. Vous y explorerez les techniques d\'interpolation et la puissance de la sommation de fonctions de bruit pour créer des heightmaps, des textures de bois ou de marbre. Maîtrisez l\'art de donner vie à vos mondes virtuels avec une touche d\'aléatoire, mais toujours avec sens et harmonie.','quarante-sept',0,'covers/bruits-et-nombres-aleatoires-coherents.png','books/Bruits et nombres aleatoires coherents.pdf',24,2011,1,6,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(329,'Introduction à la programmation dynamique','introduction-a-la-programmation-dynamique','Plongez dans le monde de la programmation dynamique, une approche algorithmique révolutionnaire pour résoudre des problèmes complexes avec une efficacité inégalée. Ce guide démystifie ce concept parfois intimidant grâce à des exemples concrets et pas à pas, tels que la pyramide de nombres, la partition et le problème du sac à dos. Développez une expertise précieuse en optimisation combinatoire et apprenez à transformer des défis algorithmiques récalcitrants en solutions élégantes et performantes. Idéal pour tout développeur ou étudiant souhaitant enrichir sa boîte à outils et maîtriser des techniques de pointe.','yoch',0,'covers/introduction-a-la-programmation-dynamique.png','books/Introduction a la programmation dynamique.pdf',10,2012,1,6,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(330,'Créez facilement des montages vidéo sous Linux avec OpenShot !','creez-facilement-des-montages-video-sous-linux-avec-openshot','Vous utilisez Linux et rêvez de créer des montages vidéo de qualité sans complication ? Ce guide complet est votre allié pour maîtriser OpenShot, le logiciel libre, intuitif et puissant qui transformera vos idées en vidéos captivantes avec une facilité déconcertante. De l\'installation aux réglages avancés, en passant par l\'ajout d\'effets spectaculaires, de transitions fluides et de titres 3D, vous apprendrez à exporter et partager vos créations sur le Web en un clin d\'œil. Préparez-vous à donner vie à vos projets vidéo, que vous soyez débutant ou confirmé !','Eolinwen',0,'covers/creez-facilement-des-montages-video-sous-linux-avec-openshot.png','books/Creez facilement des montages video sous linux avec openshot.pdf',30,2011,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(331,'Apprenez à monter votre ordinateur','apprenez-a-monter-votre-ordinateur','Découvrez l\'autonomie et la satisfaction de monter votre propre ordinateur avec ce guide pratique et exhaustif. Il vous mènera de la compréhension approfondie de chaque composant essentiel – du processeur à la carte mère en passant par les périphériques – jusqu\'à l\'assemblage complet de votre machine. Suivez des instructions claires et détaillées pour chaque étape, de la fixation des pièces au premier démarrage, et construisez le PC de vos rêves avec confiance et expertise.','CyberS@m',0,'covers/apprenez-a-monter-votre-ordinateur.png','books/Apprenez a monter votre ordinateur.pdf',140,2013,1,6,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(332,'Interagir avec le serveur FTP','interagir-avec-le-serveur-ftp','Maîtrisez l\'art de l\'interaction programmatique avec les serveurs FTP grâce à ce guide complet et accessible. Cet ouvrage vous accompagnera pas à pas, de l\'ouverture d\'une connexion sécurisée (FTPS) à la gestion avancée des fichiers et des répertoires. Apprenez à lister, télécharger, envoyer des fichiers, créer ou supprimer des dossiers, et même modifier les droits d\'accès. Idéal pour les développeurs, ce livre vous fournira les clés pour intégrer efficacement les fonctionnalités FTP dans vos applications et sécuriser vos échanges de données.','Despirithium',0,'covers/interagir-avec-le-serveur-ftp.png','books/Interagir avec le serveur ftp.pdf',11,2010,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(333,'Empêcher le téléchargement direct de fichiers multimédia','empecher-le-telechargement-direct-de-fichiers-multimedia','Vous diffusez des créations multimédia en ligne et souhaitez en empêcher le téléchargement direct ? Ce tutoriel essentiel vous dévoile une méthode astucieuse basée sur des tokens pour restreindre l\'accès à vos fichiers audio et vidéo, n\'autorisant qu\'une lecture temporaire en streaming. Apprenez à protéger vos œuvres en implémentant une solution robuste via PHP et une base de données, empêchant l\'accès non autorisé par simple URL. Bien que non infaillible face aux enregistreurs de flux, cette approche représente une barrière significative et professionnelle, adoptée par de nombreuses plateformes pour la sécurité de leurs contenus.','Christophe Tafani-Dereeper (christophetd)',0,'covers/empecher-le-telechargement-direct-de-fichiers-multimedia.png','books/Empecher le telechargement direct de fichiers multimedia.pdf',11,2012,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(334,'Recréez le style d\'Aero avec The GIMP !','recreez-le-style-daero-avec-the-gimp','Envie d\'offrir à vos créations un style visuel moderne et élégant sans recourir à des logiciels payants ? Ce guide pratique vous révèle comment reproduire l\'esthétique raffinée d\'Aero de Windows Vista et 7 en utilisant The GIMP, le puissant éditeur d\'images gratuit. Vous apprendrez à concevoir des fenêtres translucides, des boutons dynamiques et des icônes de dossiers au design soigné, étape par étape. Idéal pour enrichir vos sites web, interfaces logicielles ou projets personnels, ce livre rendra la maîtrise des outils essentiels de GIMP accessible et passionnante.','Thaledric',0,'covers/recreez-le-style-d-aero-avec-the-gimp.png','books/Recreez le style d aero avec the gimp.pdf',22,2010,1,5,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(335,'Le tri par sélection','le-tri-par-selection','Plongez dans l\'univers du tri par sélection, un algorithme fondamental reconnu pour sa facilité de mise en œuvre. Ce livre vous guide pas à pas, expliquant son principe clair à travers des exemples concrets, puis détaillant des implémentations pratiques en C pour les tableaux et les listes. Maîtrisez la décomposition des tâches, optimisez vos fonctions et comprenez la complexité de cet outil essentiel. Idéal pour les développeurs désireux d\'acquérir une base solide en algorithmique de tri.','sélection',0,'covers/le-tri-par-selection.png','books/Le tri par selection.pdf',8,2010,1,6,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(336,'Un anti brute-force léger et rapide','un-anti-brute-force-leger-et-rapide','La menace des attaques par force brute pèse sur votre site web ? Découvrez une approche révolutionnaire pour une protection légère et ultra-rapide, sans les contraintes d\'une base de données. Ce guide pratique vous enseigne comment mettre en place un système anti brute-force performant basé sur des fichiers, garantissant ainsi une sécurité renforcée tout en préservant la fluidité de l\'expérience utilisateur. Protégez efficacement vos membres et la réputation de votre site grâce à une solution ingénieuse et facile à intégrer.','ebola',0,'covers/un-anti-brute-force-leger-et-rapide.png','books/Un anti brute force leger et rapide.pdf',17,2011,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(337,'Stylisez votre site avec CSS3 !','stylisez-votre-site-avec-css3','Envie de doter vos sites web d\'un design moderne et élégant sans recourir à des artifices compliqués ? Ce guide vous plonge au cœur de CSS3 pour maîtriser les sélecteurs avancés, jouer avec les dégradés natifs, les ombres portées et les bordures créatives. Oubliez les images lourdes et les bidouillages : apprenez à styliser vos éléments nativement, avec des propriétés CSS puissantes et efficaces. Idéal pour tout développeur maîtrisant les bases du CSS, ce livre vous ouvre les portes d\'un webdesign nouvelle génération, plus propre et plus dynamique.','Adrien Guéret (KorHosik)',0,'covers/stylisez-votre-site-avec-css3.png','books/Stylisez votre site avec css3.pdf',68,2013,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(338,'Les services Web','les-services-web','Découvrez les rouages essentiels du Web moderne avec \"Les services Web\", l\'ouvrage indispensable pour comprendre comment les applications dialoguent et s\'interconnectent à l\'échelle mondiale. Explorez les architectures clés telles que REST, SOAP, WSDL et UDDI, qui ont propulsé le développement de géants comme eBay et Amazon en favorisant une interopérabilité sans précédent. Ce livre vous guidera à travers les aspects techniques, technologiques et fonctionnels, vous permettant de maîtriser la distribution d\'information entre plateformes hétérogènes. Plongez dans les solutions de communication faiblement couplées qui révolutionnent l\'intégration logicielle et l\'échange de données.','SoftDeath',0,'covers/les-services-web.png','books/Les services web.pdf',24,2011,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(339,'Désinstaller GNU/Linux et ne garder que Windows','desinstaller-gnulinux-et-ne-garder-que-windows','Vous avez installé GNU/Linux mais souhaitez désormais retrouver une configuration Windows exclusive sans les tracas habituels ? Ce guide pratique et détaillé vous accompagne pas à pas pour désinstaller proprement GNU/Linux et restaurer intégralement votre système Windows. Maîtrisez la restauration du bootloader et le redimensionnement sécurisé des partitions, évitant les erreurs courantes et les blocages inattendus. Retrouvez un PC optimisé pour Windows, prêt à l\'emploi, grâce à des instructions claires et une expertise accessible.','hOmer_dU_25',0,'covers/desinstaller-gnu-linux-et-ne-garder-que-windows.png','books/Desinstaller gnu linux et ne garder que windows.pdf',22,2010,1,7,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(340,'La percolation','la-percolation','Si la percolation vous évoque uniquement la machine à café, préparez-vous à une révélation scientifique ! Ce cours explore en profondeur ce principe fondamental qui régit l\'écoulement et la connexion à travers des structures poreuses ou des réseaux. Des mystères géologiques à la dynamique des écosystèmes, en passant par les réseaux d\'énergie et la physique, découvrez l\'incroyable diversité de ses applications et sa modélisation mathématique élégante. Un voyage passionnant qui transformera votre compréhension de nombreux phénomènes naturels et technologiques.','Mickaël Launay (GéoMl17)',0,'covers/la-percolation.png','books/La percolation.pdf',13,2012,1,6,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(341,'Apprenez à modéliser en 3D avec Autodesk Maya','apprenez-a-modeliser-en-3d-avec-autodesk-maya','Plongez au cœur de la modélisation 3D avec ce guide exhaustif dédié à Autodesk Maya, le logiciel de référence du secteur. Des fondamentaux de l\'interface aux techniques avancées de création polygonale et surfacique (NURBS), en passant par l\'organisation et l\'optimisation de vos scènes, cet ouvrage vous accompagnera pas à pas. Grâce à des travaux pratiques concrets et détaillés, de la voiture à la maison, vous développerez une expertise solide pour donner vie à toutes vos idées créatives et maîtriser les rouages de Maya.','Danyl Bekhoucha (Linko)',0,'covers/apprenez-a-modeliser-en-3d-avec-autodesk-maya.png','books/Apprenez a modeliser en 3d avec autodesk maya.pdf',692,2013,1,5,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(342,'Créer des interpolations avec Flash','creer-des-interpolations-avec-flash','Maîtrisez l\'art de l\'animation web dynamique avec Flash grâce à ce guide complet. Découvrez comment les interpolations de forme et de mouvement transforment vos objets et symboles, permettant à Flash de calculer automatiquement les étapes intermédiaires pour des transitions fluides et captivantes. De la gestion des objets particuliers aux repères de formes, ce tutoriel pratique et facile d\'accès vous guide pas à pas pour créer des animations professionnelles, le tout complété par un QCM pour valider vos acquis.','Haitham Ammar (HighTam)',0,'covers/creer-des-interpolations-avec-flash.png','books/Creer des interpolations avec flash.pdf',6,2011,1,6,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(343,'Héberger des dépôts Git avec gitosis','heberger-des-depots-git-avec-gitosis','Libérez-vous des contraintes des plateformes tierces et prenez les rênes de vos dépôts Git ! Ce livre vous guide pas à pas pour installer et configurer gitosis sur votre serveur GNU/Linux, vous offrant une solution d\'hébergement robuste et personnalisable. Vous apprendrez à gérer efficacement les utilisateurs, les dépôts et les groupes, tout en explorant le potentiel des hooks pour optimiser vos flux de travail. Une ressource indispensable pour tout développeur souhaitant une maîtrise totale de son infrastructure Git.','Dadouchi A.',0,'covers/heberger-des-depots-git-avec-gitosis.png','books/Heberger des depots git avec gitosis.pdf',9,2010,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(344,'Écrivez votre site web en C avec la CGI','ecrivez-votre-site-web-en-c-avec-la-cgi','Plongez dans l\'univers de la création web dynamique avec le langage C, votre seul et unique allié ! Ce guide pratique vous révèle comment exploiter la puissance de la CGI pour développer des fonctionnalités interactives telles que des compteurs de visites, des livres d\'or ou le traitement de formulaires, sans jamais quitter votre langage de prédilection. Idéal pour les développeurs C désireux d\'étendre leurs compétences au web, il prouve qu\'il est tout à fait possible de bâtir des sites web complets et performants sans recourir à d\'autres langages comme PHP. Préparez-vous à donner vie à vos pages web en utilisant uniquement ce que vous maîtrisez le mieux.','Dadouchi A.',0,'covers/ecrivez-votre-site-web-en-c-avec-la-cgi.png','books/Ecrivez votre site web en c avec la cgi.pdf',11,2010,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(345,'Le Safe Mode sous PHP','le-safe-mode-sous-php','Vous êtes bloqué, incapable d\'interagir avec les fichiers de votre FTP via PHP pour des uploads ou des suppressions, malgré des scripts que vous savez corrects ? Ce guide est conçu pour vous. Il lève le voile sur le Safe Mode de PHP, souvent responsable de ces blocages mystérieux, en expliquant précisément ses conséquences sur les fonctions vitales de vos applications. Apprenez des stratégies théoriques et pratiques éprouvées, illustrées par un exemple concret d\'upload d\'avatars, pour contourner ces restrictions et reprendre le contrôle total de vos scripts.','Zazou',0,'covers/le-safe-mode-sous-php.png','books/Le safe mode sous php.pdf',6,2009,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(346,'La virtualisation sous Linux','la-virtualisation-sous-linux','Passionné de Linux, mais parfois contraint par une application Windows indispensable ? Découvrez la puissance de la virtualisation avec ce guide pratique et accessible. Il vous accompagnera pas à pas dans l\'installation et la configuration de solutions éprouvées telles que VirtualBox et VMware Server. Apprenez à exécuter un système d\'exploitation invité directement au sein de votre environnement Linux, et ne faites plus de compromis entre la liberté de Linux et la compatibilité de Windows, le tout sans redémarrage !','Jérôme Deuchnord',0,'covers/la-virtualisation-sous-linux.png','books/La virtualisation sous linux.pdf',18,2010,1,7,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(347,'La programmation système en C sous Unix','la-programmation-systeme-en-c-sous-unix','Découvrez les arcanes de la programmation système en C sous Unix avec ce guide pratique et exhaustif. Ce livre vous ouvre les portes de la création d\'applications puissantes, en vous enseignant la manipulation des processus, des threads, des tubes et la gestion avancée des erreurs. Idéal pour les développeurs C souhaitant comprendre et interagir directement avec le cœur du système d\'exploitation, il transformera votre approche du développement logiciel. Préparez-vous à maîtriser les outils fondamentaux pour concevoir des programmes systèmes robustes et efficaces.','Lucas Pesenti (Lucas-84)',0,'covers/la-programmation-systeme-en-c-sous-unix.png','books/La programmation systeme en c sous unix.pdf',58,2012,1,4,'2026-07-29 08:53:19','2026-07-29 08:53:19'),(348,'Introduction à C++ 2011 (C++0x)','introduction-a-c-2011-c0x','Prêt à maîtriser les innovations de la norme C++11 (anciennement C++0x) ? Ce guide pratique vous plonge au cœur des fonctionnalités clés pour moderniser votre code, des énumérations fortement typées aux fonctions anonymes (lambdas), en passant par le mot-clé `auto` et les boucles basées sur un intervalle. Apprenez à configurer votre compilateur et à exploiter ces nouveautés pour écrire un code plus élégant, efficace et maintenable. Idéal pour les développeurs C++ souhaitant se familiariser rapidement avec les standards actuels et optimiser leurs pratiques.','antoyo',0,'covers/introduction-a-c-2011-c-0x.png','books/Introduction a c 2011 c 0x.pdf',25,2011,1,4,'2026-07-29 08:53:20','2026-07-29 08:53:20'),(349,'Gérez vos codes source avec Git','gerez-vos-codes-source-avec-git','Marre des problèmes de collaboration, des bugs inexpliqués et de la perte d\'historique sur vos projets de développement ? Découvrez comment Git, le système de gestion de versions distribué, révolutionnera votre façon de travailler. Ce guide complet vous apprendra à maîtriser Git, de l\'installation aux fonctionnalités avancées, vous permettant de suivre chaque modification, de collaborer efficacement et de corriger vos erreurs avec assurance. Que vous travailliez seul ou en équipe, transformez la gestion de votre code source en un atout majeur pour tous vos projets informatiques.','Mathieu Nebra (Mateo21)',0,'covers/gerez-vos-codes-source-avec-git.png','books/Gerez vos codes source avec git.pdf',33,2012,1,4,'2026-07-29 08:53:20','2026-07-29 08:53:20'),(350,'Conteneurs exotiques Boost','conteneurs-exotiques-boost','Explore les profondeurs de la bibliothèque Boost et maîtrisez des structures de données C++ qui transformeront votre approche du développement. Ce guide détaillé vous ouvre les portes des tuples pour une gestion flexible de données hétérogènes, des tampons circulaires pour une efficacité optimale, et des bimaps pour des recherches bidirectionnelles sophistiquées. Allez plus loin avec les tableaux multidimensionnels et les conteneurs intrusifs, pour des applications C++ plus performantes, plus robustes et adaptées aux défis les plus exigeants. Un ouvrage essentiel pour tout développeur C++ souhaitant dépasser les conteneurs standards.','Blue Sh4rk',0,'covers/conteneurs-exotiques-boost.png','books/Conteneurs exotiques boost.pdf',17,2011,1,4,'2026-07-29 08:53:20','2026-07-29 08:53:20'),(351,'Bases de traitement du signal','bases-de-traitement-du-signal','Plongez au cœur du traitement du signal, cette discipline fascinante à l\'intersection des mathématiques, de l\'électronique et de l\'informatique, qui façonne notre compréhension du monde numérique. Cet ouvrage, \"Bases de traitement du signal\", vous guidera à travers la description mathématique des signaux, leurs caractéristiques essentielles et les outils fondamentaux pour les analyser et les manipuler. Idéal pour les apprenants de tous horizons, il démystifie les concepts clés sans s\'enliser dans les détails d\'implémentation, vous préparant ainsi à explorer ses vastes applications, de l\'audio aux communications. Que vous soyez novice ou désireux de rafraîchir vos connaissances, ce livre est votre porte d\'entrée incontournable vers le signal processing.','(Lanfeust 313)',0,'covers/bases-de-traitement-du-signal.png','books/Bases de traitement du signal.pdf',33,2011,1,6,'2026-07-29 08:53:20','2026-07-29 08:53:20'),(352,'Audacity : prise en main','audacity-prise-en-main','Découvrez le monde de l\'édition audio avec \"Audacity : prise en main\", le guide idéal pour maîtriser ce logiciel gratuit, puissant et multi-plateformes. De l\'enregistrement simple via micro ou haut-parleurs à la création de montages multipistes complexes et à l\'application d\'effets sonores variés, chaque étape est clairement expliquée. Parfaitement adapté aux débutants, ce tutoriel vous offre toutes les clés pour une prise en main rapide et efficace d\'Audacity, transformant votre ordinateur en un véritable studio audio.','(pablounet)',0,'covers/audacity-prise-en-main.png','books/Audacity prise en main.pdf',10,2012,1,5,'2026-07-29 08:53:20','2026-07-29 08:53:20'),(353,'Apprenez à programmer avec Ada','apprenez-a-programmer-avec-ada','Plongez dans l\'univers de la programmation avec Ada grâce à ce guide complet, conçu pour vous accompagner des bases aux concepts les plus élaborés. De l\'installation de votre environnement de développement à la création de votre premier programme, vous explorerez pas à pas les variables, les structures conditionnelles, les boucles, les procédures, les fonctions, et les types composites comme les tableaux et les chaînes de caractères. Agrémenté d\'exercices pratiques et d\'un projet fil rouge (le jeu de Craps), cet ouvrage vous offre une approche pédagogique et concrète pour maîtriser Ada et développer vos propres applications robustes et fiables.','Kaji9',0,'covers/apprenez-a-programmer-avec-ada.png','books/Apprendre a programmer avec ada.pdf',311,2013,1,4,'2026-07-29 08:53:20','2026-07-29 08:53:20'),(354,'Présentation de KDE : les KIO-slaves','presentation-de-kde-les-kio-slaves','Découvrez comment les KIO-slaves transforment votre expérience de KDE en rendant l\'accès aux fichiers distants aussi simple et transparent que celui de vos documents locaux. Ce guide essentiel explore en détail cette fonctionnalité ingénieuse, qui permet à vos applications KDE favorites d\'interagir nativement avec des ressources variées, des serveurs FTP aux CD audio et pages de manuel, grâce à des adresses de type URL. Optimisez votre productivité en éditant directement du code sur un serveur distant depuis Kate, ou en naviguant sur votre espace web via Konqueror, le tout sans friction et sans client externe, simplifiant ainsi radicalement votre flux de travail.','bluestorm',0,'covers/presentation-de-kde-les-kio-slaves.png','books/Presentation de kde les kio slaves.pdf',8,2010,1,4,'2026-07-29 08:53:20','2026-07-29 08:53:20'),(355,'Adium','adium','Fatigué des clients de messagerie instantanée limités sur Mac OS X ? Ce guide complet vous invite à maîtriser Adium, le logiciel ultime pour communiquer sur de nombreux protocoles avec puissance et élégance. De son installation à la gestion de vos contacts, en passant par l\'exploitation des fonctionnalités avancées et la personnalisation poussée via les Xtras, chaque aspect d\'Adium est décortiqué. Apprenez même à créer et partager vos propres thèmes, icônes et sons pour une expérience sur mesure. Que vous soyez un utilisateur novice cherchant une solution fiable ou un passionné désireux de repousser les limites de la personnalisation, ce livre est votre passeport pour une communication instantanée réinventée.','Applemaniac',0,'covers/adium.png','books/Adium.pdf',57,2011,1,5,'2026-07-29 08:53:20','2026-07-29 08:53:20'),(356,'Créez une interface avec GTK+ !','creez-une-interface-avec-gtk','Plongez dans l\'univers de la création d\'interfaces graphiques avec GTK+ et donnez une dimension visuelle à vos applications ! Ce guide progressif vous accompagne dans l\'apprentissage de la conception de fenêtres, boutons, menus et autres widgets essentiels, même sans expérience préalable. Découvrez les nombreux avantages de cette bibliothèque libre et multiplateforme, compatible avec une multitude de langages de programmation. Idéal pour concrétiser vos projets avec une interface utilisateur intuitive et professionnelle.','guimers8 ,',0,'covers/creez-une-interface-avec-gtk.png','books/Creez une interface avec gtk.pdf',53,2010,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(357,'Créer un moteur de recherche avec Sphinx et PHP','creer-un-moteur-de-recherche-avec-sphinx-et-php','Envie de concevoir un moteur de recherche rapide et puissant, capable de gérer de vastes volumes de données sans la complexité des requêtes SQL traditionnelles ? Ce livre est votre guide complet pour maîtriser Sphinx, l\'un des moteurs de recherche les plus performants du marché, en l\'associant au langage PHP. De l\'installation sur différentes plateformes à l\'indexation optimisée, en passant par la pagination des résultats et l\'application de filtres avancés, vous apprendrez à bâtir un système de recherche professionnel et hautement efficace pour vos projets web.','Victor Thuillier (vyk12)',0,'covers/creer-un-moteur-de-recherche-avec-sphinx-et-php.png','books/Creer un moteur de recherche avec sphinx et php.pdf',17,2012,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(358,'Du Qt en Java avec Qt Jambi','du-qt-en-java-avec-qt-jambi','Envie de créer des interfaces graphiques élégantes et multi-plateformes directement en Java ? Ce livre vous immerge pas à pas dans l\'univers de Qt Jambi, le framework qui conjugue la puissance de Qt avec la souplesse de Java. De l\'installation à la conception de fenêtres interactives avec menus et boîtes de dialogue, en passant par la maîtrise des fondamentaux comme les signaux et les slots, vous développerez des applications fonctionnelles. Parfait pour les développeurs Java désireux d\'acquérir les compétences nécessaires pour bâtir des GUIs sophistiquées.','Natim',0,'covers/du-qt-en-java-avec-qt-jambi.png','books/Du qt en java avec qt jambi.pdf',44,2012,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(359,'Créer une installation','creer-une-installation','Passez au niveau supérieur dans la distribution de vos applications Windows ! Ce livre vous révèle comment transformer vos programmes en installations professionnelles, compressées et prêtes à l\'emploi. Découvrez Inno Setup, l\'outil open source plébiscité pour sa discrétion et sa puissance, et maîtrisez la création d\'installeurs sur mesure en toute simplicité. Offrez à vos utilisateurs une expérience d\'installation fluide et impeccable, quel que soit le langage de votre projet.','Mathieu Nebra (Mateo21)',0,'covers/creer-une-installation.png','books/Creer une installation.pdf',14,2012,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(360,'Compilez sous GNU/Linux !','compilez-sous-gnulinux','Envie de comprendre ce qui se passe vraiment derrière le bouton \"Compiler\" et de maîtriser chaque étape de la création de vos programmes sous GNU/Linux ? Ce livre est votre guide pratique pour exploiter pleinement les outils emblématiques que sont GCC et Make. Vous y apprendrez à compiler efficacement vos applications, gérer les bibliothèques statiques et dynamiques, et automatiser vos builds grâce à des Makefiles sophistiqués. Adoptez la console et transformez-vous en développeur GNU/Linux aguerri, capable de compiler vos projets avec précision et agilité.','kna',0,'covers/compilez-sous-gnu-linux.png','books/Compilez sous gnu linux.pdf',23,2009,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(361,'Création de paquets avec ArchLinux','creation-de-paquets-avec-archlinux','Vous rêvez de packager votre application favorite ou votre propre création pour ArchLinux mais ne savez pas par où commencer ? Ce guide complet vous plonge au cœur de la création de paquets en vous initiant au fichier PKGBUILD, la pierre angulaire de toute construction sous ArchLinux. Vous apprendrez à gérer les dépendances, intégrer les licences, maîtriser les fonctions de compilation et de redistribution, et découvrirez les astuces pour des PKGBUILD complexes et maintenables. Idéal pour tout utilisateur d\'ArchLinux souhaitant approfondir ses compétences et contribuer activement à l\'écosystème, ce tutoriel vous fournit les clés pour devenir un expert du packaging.','Dadouchi A.',0,'covers/creation-de-paquets-avec-archlinux.png','books/Creation de paquets avec archlinux.pdf',13,2010,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(362,'Page d\'erreur perso','page-derreur-perso','Marre des pages d\'erreur génériques qui nuisent à l\'image de votre site ? Ce tutoriel vous offre une solution simple et efficace pour personnaliser les messages \"404 Not Found\", \"500 Internal Error\" et bien d\'autres. Apprenez à utiliser un fichier `.htaccess` et du PHP pour concevoir des pages d\'erreur cohérentes avec votre charte graphique, tout en gérant l\'indexation des robots. Transformez ces imprévus en une opportunité d\'offrir une expérience utilisateur fluide et professionnelle, même lorsque l\'inattendu se produit.','Kakyokuu',0,'covers/page-d-erreur-perso.png','books/Page d erreur perso.pdf',8,2010,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(363,'Introduction aux opérateurs de bits','introduction-aux-operateurs-de-bits','Vous cherchez à optimiser la gestion des droits d\'accès, à manipuler efficacement de multiples propriétés booléennes ou à compacter vos paramètres fonctionnels ? Plongez dans \"Introduction aux opérateurs de bits\" pour maîtriser ces outils fondamentaux du programmeur. Ce guide clair et détaillé vous enseigne à exploiter la puissance du binaire et des opérateurs (&, |, ^, ~, <<, >>) avec des exemples concrets, notamment en PHP. Simplifiez votre code et gagnez en performance grâce à des techniques expliquées pas à pas, idéales pour tout développeur souhaitant affiner ses compétences.','infotoubib',0,'covers/introduction-aux-operateurs-de-bits.png','books/Introduction aux operateurs de bits.pdf',14,2011,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(364,'Profilage géographique','profilage-geographique','Découvrez le profilage géographique, une technique avancée utilisée par les forces de l\'ordre pour retrouver des criminels. Ce livre vous plonge au cœur de cette discipline fascinante, où sciences humaines, mathématiques et informatique s\'unissent pour élucider les enquêtes les plus complexes. Après avoir maîtrisé la théorie et les formules mathématiques qui la sous-tendent, vous développerez étape par étape votre propre programme de profilage. Une approche unique pour appliquer des connaissances intermédiaires et comprendre comment la technologie combat le crime.','The_Greek22',0,'covers/profilage-geographique.png','books/Profilage geographique.pdf',22,2011,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(365,'Un site web dynamique avec jQuery !','un-site-web-dynamique-avec-jquery','Transformez vos sites web en expériences dynamiques et interactives avec ce guide complet dédié à jQuery. Vous explorerez les bases du framework, de la manipulation des sélecteurs et des événements à la gestion du DOM et aux animations fluides. Apprenez également à intégrer des requêtes AJAX pour des applications web modernes et réactives. Grâce à des explications claires et des travaux pratiques, ce livre vous offre toutes les clés pour donner vie à vos projets et enrichir considérablement l\'expérience utilisateur.','Nassoub',0,'covers/un-site-web-dynamique-avec-jquery.png','books/Un site web dynamique avec jquery.pdf',149,2012,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(366,'Débuter dans l\'informatique embarquée avec Teensy','debuter-dans-linformatique-embarquee-avec-teensy','Plongez dans l\'univers captivant de l\'informatique embarquée avec ce guide pratique dédié à la carte Teensy, l\'outil idéal pour donner vie à vos projets électroniques. De l\'installation de l\'environnement Arduino à la maîtrise des entrées/sorties numériques, de la communication série et des interruptions, ce livre vous offre une progression pas à pas. Apprenez à programmer concrètement des systèmes embarqués et à interagir avec le monde réel de manière ludique et efficace. Idéal pour les débutants, il vous équipera des compétences fondamentales pour vos futures créations.','Grota',0,'covers/debuter-dans-l-informatique-embarquee-avec-teensy.png','books/Debuter dans l informatique embarquee avec teensy.pdf',17,2012,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(367,'Prenez en main Bootstrap','prenez-en-main-bootstrap','Fatigué de consacrer un temps infini au CSS pour construire des interfaces web modernes et responsives ? Ce guide complet est votre passeport pour maîtriser Bootstrap, le framework incontournable qui simplifie radicalement la création de l\'architecture et du style de vos pages. Vous explorerez la puissance de son système de grille, apprendrez à manipuler ses composants UI essentiels et découvrirez comment intégrer des fonctionnalités interactives avancées via ses plugins jQuery. De la mise en place d\'un template de base à la personnalisation poussée avec LESS, ce livre vous dotera des compétences nécessaires pour développer des sites élégants et fonctionnels en un temps record.','bestmomo',0,'covers/prenez-en-main-bootstrap.png','books/Prenez en main bootstrap.pdf',251,2014,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(368,'La Physique-Chimie en Seconde','la-physique-chimie-en-seconde','Plongez au cœur du programme de Physique-Chimie de Seconde avec cet ouvrage conçu pour rendre les sciences accessibles et passionnantes. À travers les thèmes captivants de la pratique du sport, de l\'exploration de l\'Univers et des enjeux de la santé, découvrez comment la physique et la chimie expliquent notre quotidien. Pensé pour tous, du lycéen en quête de bases solides au curieux souhaitant enrichir sa culture scientifique, ce guide aborde chaque notion clé avec clarté et bienveillance, en partant toujours de zéro.','Brice Errandonea',0,'covers/la-physique-chimie-en-seconde.png','books/La physique chimie en seconde.pdf',133,2011,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(369,'Les Threads en .NET','les-threads-en-net','Plongez au cœur de la performance applicative avec \"Les Threads en .NET\", un guide essentiel pour tout développeur C# souhaitant maîtriser l\'exécution concurrente. Ce tutoriel approfondi vous guidera à travers les concepts clés des threads, les mécanismes de synchronisation et l\'utilité cruciale des delegates pour une architecture logicielle flexible. Vous apprendrez à fluidifier vos applications en gérant les opérations lourdes sans blocage, à faciliter la communication réseau et à intégrer efficacement les threads dans vos Windows Forms. Dédié aux \"Zéros avertis\", ce livre promet de transformer la réactivité et la puissance de vos développements.','gretro',0,'covers/les-threads-en-net.png','books/Les threads en net.pdf',30,2011,1,4,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(370,'Créer un serveur FTP sous Windows','creer-un-serveur-ftp-sous-windows','Découvrez comment créer et configurer votre propre serveur FTP sous Windows grâce à ce guide clair et accessible, idéal pour les débutants. Ce tutoriel vous accompagnera pas à pas, des concepts fondamentaux du protocole FTP (modes actif et passif, sécurisation via SSL/TLS) à la configuration pratique de votre serveur, en passant par la gestion cruciale des ports et des adresses IP. Grâce à des explications concises et un vocabulaire dédié, vous démystifierez rapidement le transfert de fichiers. Prenez le contrôle de vos échanges de données et mettez en place un serveur fonctionnel en toute confiance.','tarkan-t29',0,'covers/creer-un-serveur-ftp-sous-windows.png','books/Creer un serveur ftp sous windows.pdf',14,2010,1,7,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(371,'Les premiers algorithmes de chiffrement','les-premiers-algorithmes-de-chiffrement','Découvrez les origines fascinantes de la cryptographie avec ce guide clair et accessible, qui vous dévoile les secrets des premières méthodes de chiffrement. Explorez des algorithmes emblématiques tels que le chiffre de César, le masque jetable, et le chiffre de Vigenère, tout en maîtrisant le vocabulaire essentiel et le principe de Kerckhoffs. Cet ouvrage vous initiera également aux principales techniques utilisées pour décrypter ces messages, de l\'analyse fréquentielle à l\'attaque par force brute. Une lecture incontournable pour quiconque souhaite comprendre les bases historiques et techniques de la sécurité des communications.','Lucas Pesenti (Lucas-84)',0,'covers/les-premiers-algorithmes-de-chiffrement.png','books/Les premiers algorithmes de chiffrement.pdf',12,2012,1,6,'2026-07-29 08:53:23','2026-07-29 08:53:23'),(372,'Piloter canvas avec KineticJS','piloter-canvas-avec-kineticjs','Maîtrisez l\'art de la création graphique web avec \"Piloter canvas avec KineticJS\" ! Ce livre est votre guide essentiel pour exploiter la puissance de l\'API Canvas de HTML5, simplifiée et enrichie par le framework KineticJS. Apprenez à dessiner des formes complexes, à gérer des interactions utilisateur et à concevoir des animations fluides et spectaculaires, depuis les transitions basiques jusqu\'à l\'animation de sprites. Idéal pour les développeurs JavaScript, cet ouvrage vous offre les clés pour développer des applications web visuellement riches et dynamiques, avec de nombreux exemples pratiques à l\'appui.','bestmomo',0,'covers/piloter-canvas-avec-kineticjs.png','books/Piloter canvas avec kineticjs.pdf',155,2012,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(373,'Des techniques modernes pour l\'agencement en colonnes','des-techniques-modernes-pour-lagencement-en-colonnes','Maîtrisez l\'art de l\'agencement en colonnes grâce à des techniques CSS modernes et élégantes, et dites adieu aux bidouillages et aux mises en page non sémantiques. Ce guide pratique vous plonge au cœur des propriétés `display: table` et des fonctionnalités CSS3 dédiées, vous permettant de créer des designs impeccables avec un code propre et maintenable. Apprenez pas à pas à structurer vos contenus avec professionnalisme et à optimiser l\'affichage pour une expérience utilisateur fluide. Un indispensable pour tout développeur souhaitant élever la qualité de ses intégrations web.','Mattéo DELABRE (m@tteo78)',0,'covers/des-techniques-modernes-pour-l-agencement-en-colonnes.png','books/Des techniques modernes pour l agencement en colonnes.pdf',14,2012,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(374,'Installer, configurer et utiliser Xampp sous Ubuntu','installer-configurer-et-utiliser-xampp-sous-ubuntu','Développeur PHP sous Ubuntu et à la recherche d\'un environnement de développement local simple et efficace ? Ce guide complet vous accompagne pas à pas dans l\'installation, la configuration et l\'utilisation de Xampp. Au-delà de la simple mise en route, il détaille les aspects cruciaux de la sécurisation de votre serveur (pages, MySQL, phpMyAdmin), ainsi que des astuces pour optimiser son usage. Idéal pour apprendre le PHP dans un environnement maîtrisé ou pour disposer d\'un serveur de test robuste et personnalisé.','unter',0,'covers/installer-configurer-et-utiliser-xampp-sous-ubuntu.png','books/Installer configurer et utiliser xampp sous ubuntu.pdf',10,2010,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(375,'Créer un système de newsletter','creer-un-systeme-de-newsletter','Vous aspirez à créer un lien privilégié avec vos visiteurs et à les tenir informés des actualités de votre site web ? Ce guide pratique vous accompagne pas à pas dans la conception d\'un système de newsletter robuste et sécurisé, en exploitant les fonctionnalités de PHP et une base de données MySQL. Vous apprendrez à gérer les inscriptions et désinscriptions via un processus de validation par e-mail, assurant ainsi une liste d\'abonnés fiable et pertinente. Idéal pour les développeurs souhaitant maîtriser les outils essentiels pour une communication numérique efficace.','NTag',0,'covers/creer-un-systeme-de-newsletter.png','books/Creer un systeme de newsletter.pdf',19,2011,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(376,'Programmez avec le langage C++','programmez-avec-le-langage-c','Lancez-vous dans l\'univers de la programmation C++ avec ce guide complet, conçu pour les débutants ambitieux et tous ceux souhaitant maîtriser les fondamentaux du langage. De l\'installation des outils de développement à la création de votre premier programme console, cet ouvrage vous accompagnera pas à pas à travers les concepts clés comme les variables, les structures de contrôle, les fonctions et la manipulation de fichiers. Progressivement, vous aborderez des concepts essentiels tels que la gestion de la mémoire via les pointeurs et mettrez vos connaissances en application à travers des exercices pratiques, culminant avec un projet complet. Avec des explications claires et de nombreux exemples concrets, ce livre est votre allié indispensable pour acquérir une solide autonomie en programmation C++.','Mathieu Nebra (Mateo21)',0,'covers/programmez-avec-le-langage-c.png','books/Programmez avec le langage c.pdf',612,2013,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(377,'Créer un avatar qui change','creer-un-avatar-qui-change','Envie de dynamiser votre profil en ligne avec un avatar unique qui évolue en permanence ? Ce guide pratique vous dévoile les secrets du PHP pour concevoir un avatar dynamique, capable de changer aléatoirement ou selon la date, jour après jour. Vous apprendrez à manipuler les fonctions clés, de `glob` à `array_rand` et `getdate()`, et surtout, comment transformer astucieusement votre script PHP en une image PNG pour le web. Idéal pour les débutants, ce tutoriel clair et concis vous permettra d\'ajouter une touche personnalisée et interactive à tous vos profils.','Almaju',0,'covers/creer-un-avatar-qui-change.png','books/Creer un avatar qui change.pdf',9,2010,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(378,'Le développement de jeux vidéo avec XNA','le-developpement-de-jeux-video-avec-xna','Vous rêvez de développer des jeux vidéo captivants pour PC, Xbox ou Windows Phone sans vous confronter à des librairies complexes ? Ce livre est votre allié idéal pour maîtriser XNA, le framework de Microsoft conçu pour démocratiser la création ludique. À travers une approche concrète et didactique, vous apprendrez les fondamentaux du développement 2D et 3D, de l\'interaction joueur à l\'intégration sonore, jusqu\'à la réalisation d\'un jeu complet comme Pong. Plongez dans l\'univers de la création de jeux et transformez vos idées en réalité avec facilité et efficacité, même avec des bases en C#.','Blue Sh4rk',0,'covers/le-developpement-de-jeux-video-avec-xna.png','books/Le developpement de jeux video avec xna.pdf',68,2011,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(379,'[Qt] Bien utiliser QtXml','qt-bien-utiliser-qtxml','Maîtrisez l\'intégration de données XML dans vos applications Qt grâce à ce guide essentiel dédié au module QtXml et à l\'approche DOM. Explorez les fondamentaux de l\'objet DOM pour créer, manipuler et interagir efficacement avec vos documents XML, de la simple lecture à l\'écriture de données. Chaque concept est illustré par des exemples de code concrets, vous permettant d\'implémenter rapidement des fonctionnalités robustes. Idéal pour les développeurs Qt ayant une connaissance des bases et du format XML, ce livre est votre allié pour enrichir vos projets avec une gestion avancée des données.','avito',0,'covers/qt-bien-utiliser-qtxml.png','books/Qt bien utiliser qtxml.pdf',15,2011,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(380,'La commande sed','la-commande-sed','Découvrez `sed`, l\'éditeur de flux emblématique d\'UNIX, et transformez radicalement votre approche de la manipulation de fichiers texte et de l\'optimisation de vos scripts. Loin de la complexité des manuels techniques, ce guide pratique vous emmène pas à pas, des fondamentaux de l\'adressage et de la substitution aux techniques avancées, pour exploiter pleinement la puissance de cet outil. Idéal pour les utilisateurs Linux familiers avec la ligne de commande et les expressions régulières, cet ouvrage est votre allié indispensable pour automatiser vos tâches et rendre vos applications encore plus performantes.','yoch',0,'covers/la-commande-sed.png','books/La commande sed.pdf',9,2010,1,5,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(381,'Compteur de téléchargements','compteur-de-telechargements','Optimisez la gestion de vos téléchargements et comprenez mieux les préférences de vos visiteurs grâce à ce guide pratique. Découvrez comment créer un compteur de téléchargements simple, rapide et léger, sans dépendre d\'une base de données, pour suivre avec précision la popularité de vos fichiers. De l\'installation des infrastructures à la mise en place du code PHP, en passant par les bonnes pratiques de sécurité essentielles pour se prémunir du Directory Traversal, chaque étape est clairement expliquée. Ce tutoriel, classé comme \"facile\", est indispensable pour tout webmaster souhaitant optimiser son site, économiser de l\'espace disque et affiner son offre de contenu.','ShadowBlade',0,'covers/compteur-de-telechargements.png','books/Compteur de telechargements.pdf',11,2011,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(382,'3D temps réel avec Irrlicht','3d-temps-reel-avec-irrlicht','Vous souhaitez vous lancer dans la programmation d\'applications 3D temps réel, mais les APIs bas niveau et les concepts mathématiques complexes vous freinent ? Ce guide complet vous invite à explorer Irrlicht, un moteur 3D libre, gratuit et puissant qui démystifie l\'affichage, les calculs et la gestion des ressources externes, vous permettant de vous concentrer sur la création. De l\'installation et la manipulation des modèles 3D à l\'intégration de GUI 2D, l\'éclairage, les systèmes de particules et les shaders avancés, ce livre vous accompagnera pas à pas. Armé de bonnes connaissances en C++, transformez vos idées en scènes interactives et visuellement riches, et donnez vie à vos mondes virtuels !','Fraggy',0,'covers/3d-temps-reel-avec-irrlicht.png','books/3d temps reel avec irrlicht.pdf',133,2011,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(383,'Faire des tableaux sous OOo Writer !','faire-des-tableaux-sous-ooo-writer','Vous souhaitez transformer vos données brutes en tableaux clairs et esthétiques, sans dépenser un centime en logiciel ? Ce guide pratique vous plonge dans l\'univers d\'OpenOffice.org Writer pour vous apprendre à créer, manipuler et sublimer vos tableaux. De l\'égalisation des lignes à l\'intégration de couleurs vives et de bordures élégantes, maîtrisez toutes les techniques pour une présentation impeccable. Idéal pour des horaires de cours percutants ou toute organisation de données, donnez à vos documents le style professionnel qu\'ils méritent.','Ishimaru Chiaki',0,'covers/faire-des-tableaux-sous-ooo-writer.png','books/Faire des tableaux sous ooo writer.pdf',16,2010,1,7,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(384,'L\'Axe Parser','laxe-parser','Découvrez comment transformer votre calculatrice TI-83+ ou TI-84+ en une véritable machine de programmation grâce à \"L\'Axe Parser\". Ce guide complet vous mène des bases de l\'installation et des premiers programmes jusqu\'aux techniques avancées de graphisme, d\'optimisation de code et de manipulation des spécificités de votre appareil. Apprenez à créer des jeux rapides et des applications complexes avec des niveaux de gris et des sprites détaillés, prouvant que performance et esthétique ne sont pas l\'apanage des ordinateurs. Que vous soyez débutant ou désireux de repousser les limites de votre calculatrice, ce livre vous offre les clés pour développer des programmes étonnants et acquérir des bases solides en programmation.','kindermoumoute ,',0,'covers/l-axe-parser.png','books/L axe parser.pdf',146,2013,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(385,'Configurer Hammer pour Steam','configurer-hammer-pour-steam','Vous rêvez de créer vos propres cartes pour des jeux mythiques comme Counter-Strike ou Half-Life sur Steam, mais les anciens tutoriels ne sont plus d\'actualité ? Ce guide complet est votre allié indispensable pour configurer le Valve Hammer Editor et tous les outils associés, tels que les compilateurs ZHLT et les fichiers FGD, spécifiquement pour les environnements Steam modernes. Dites adieu aux structures de fichiers obsolètes et maîtrisez le processus complet, du téléchargement des logiciels à la compilation finale de vos maps. Plongez dans l\'univers du mapping avec facilité et professionnalisme, et donnez vie à vos créations sur la plateforme de jeu la plus populaire.','MisterJ',0,'covers/configurer-hammer-pour-steam.png','books/Configurer hammer pour steam.pdf',8,2011,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(386,'Ajouter des utilisateurs en ligne à TYPSoft FTP Serveur','ajouter-des-utilisateurs-en-ligne-a-typsoft-ftp-serveur','Optimisez la gestion de vos utilisateurs sur TYPSoft FTP Serveur grâce à ce guide pratique et accessible. Découvrez comment ajouter des comptes de manière dynamique et en ligne, en exploitant la puissance de PHP pour une administration simplifiée. Ce tutoriel vous guidera à travers la compréhension approfondie du fichier `users.ini` et la configuration précise des droits d\'accès. Idéal pour les administrateurs et développeurs, il offre une approche pas à pas pour automatiser efficacement l\'intégration de nouveaux utilisateurs à votre serveur FTP.','Trykers',0,'covers/ajouter-des-utilisateurs-en-ligne-a-typsoft-ftp-serveur.png','books/Ajouter des utilisateurs en ligne a typsoft ftp serveur.pdf',11,2012,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(387,'Installer Xubuntu sur un vieux PC grace à l\'Alternate CD','installer-xubuntu-sur-un-vieux-pc-grace-a-lalternate-cd','Votre vieux PC peine sous Windows et vous songez à le remplacer ? Ce livre est la solution idéale pour lui offrir une seconde jeunesse ! Apprenez à installer Xubuntu, une distribution Linux légère et performante, spécifiquement conçue pour les machines à faibles ressources grâce à l\'Alternate CD. Redonnez vie à votre ancien ordinateur en le transformant en un système rapide, fonctionnel et gratuit, et découvrez les joies d\'une informatique optimisée sans dépenser un euro.','Renesis-3',0,'covers/installer-xubuntu-sur-un-vieux-pc-grace-a-l-alternate-cd.png','books/Installer xubuntu sur un vieux pc grace a l alternate cd.pdf',27,2013,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(388,'La const-correctness expliquée aux Zéros','la-const-correctness-expliquee-aux-zeros','Le terme \"const-correctness\" vous semble obscur en C++ ? Souvent ignorée ou mal comprise par les développeurs, cette notion est pourtant fondamentale pour un code robuste et performant. Cet ouvrage démystifie l\'utilisation du mot-clé `const`, depuis les bases de la déclaration de variables et fonctions jusqu\'aux optimisations clés comme le passage par référence constante. Explorez également les aspects plus avancés avec `const_cast` et `mutable` pour une maîtrise complète de la constance. Apprenez à écrire un C++ plus sûr, plus lisible et plus efficace, et faites de la const-correctness un allié indispensable dans vos projets.','De passage',0,'covers/la-const-correctness-expliquee-aux-zeros.png','books/La const correctness expliquee aux zeros.pdf',17,2011,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(389,'Les réseaux de zéro','les-reseaux-de-zero','\"Les réseaux de zéro\" vous invite à un voyage complet et accessible au cœur des technologies réseau, parfait pour quiconque souhaite comprendre cet univers depuis ses fondations. De la présentation des équipements essentiels et des topologies à l\'exploration approfondie des modèles OSI et TCP/IP, en passant par les subtilités de l\'adressage IP (subnetting, CIDR, IPv6) et des protocoles clés, ce livre couvre l\'essentiel. Idéal pour les débutants désireux de bâtir une expertise solide, cet ouvrage vous fournira les connaissances fondamentales et avancées pour maîtriser les mécanismes de communication numérique. Préparez-vous à déchiffrer les mystères des interconnexions et à construire votre propre savoir-faire réseau étape par étape.','junior0',0,'covers/les-reseaux-de-zero.png','books/Les reseaux de zero.pdf',134,2012,1,6,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(390,'Parser un format simple en Haskell avec Parsec','parser-un-format-simple-en-haskell-avec-parsec','Découvrez comment simplifier l\'analyse syntaxique avec Parsec, la puissante bibliothèque de parsing en Haskell. Ce guide pratique vous mène pas à pas dans la création de parsers élégants et efficaces, en vous permettant d\'écrire directement la grammaire de vos langages ou formats au sein de votre code Haskell. En vous appuyant sur l\'exemple concret des fichiers de configuration Desktop Entry, vous développerez une compétence essentielle pour exploiter divers formats de données. Idéal pour les développeurs Haskell de niveau intermédiaire désireux de maîtriser une tâche de programmation courante avec une approche fonctionnelle.','Mr.Tambourine',0,'covers/parser-un-format-simple-en-haskell-avec-parsec.png','books/Parser un format simple en haskell avec parsec.pdf',15,2010,1,6,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(391,'Les différents types d\'applications pouvant être développées avec le C#','les-differents-types-dapplications-pouvant-etre-developpees-avec-le-c','Oubliez les applications console : le C# est une porte ouverte sur un univers de développement graphique et interactif ! Ce livre explore la vaste étendue des possibilités offertes par le C#, vous montrant comment créer des applications Windows avec des interfaces riches, des sites web dynamiques, des jeux captivants et des services robustes. Il vous offre un aperçu concis des principales technologies, éveillant votre curiosité et vous aidant à choisir la voie qui vous passionne le plus pour vos projets futurs.','nico.pyright',0,'covers/les-differents-types-d-applications-pouvant-etre-developpees-avec-le-c.png','books/Les differents types d applications pouvant etre developpees avec le c.pdf',63,2012,1,5,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(392,'Apprenez à programmer en C# sur .NET','apprenez-a-programmer-en-c-sur-net','Découvrez le monde fascinant de la programmation avec C# et le framework .NET, un langage essentiel pour le développement Windows et au-delà. Ce livre vous guide pas à pas, des fondamentaux de la syntaxe aux concepts avancés comme les interfaces graphiques (WinForms), la gestion des erreurs et les collections de données. Que vous soyez débutant ou que vous souhaitiez maîtriser C#, cet ouvrage complet et progressif vous offre toutes les clés pour créer vos propres applications robustes et performantes.','Narvarth',0,'covers/apprenez-a-programmer-en-c-sur-net.png','books/Apprenez a programmer en c sur net.pdf',131,2012,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(393,'[C++] Les pointeurs sur fonctions','c-les-pointeurs-sur-fonctions','Les pointeurs peuvent vous paraître complexes, mais les pointeurs sur fonctions en C++ sont un outil irremplaçable pour rendre votre code dynamique et flexible. Ce guide vous révèle comment résoudre élégamment le défi de la sélection et du passage de fonctions, vous évitant les recompilations fastidieuses ou les `switch` encombrants. Apprenez à les déclarer, les affecter et les utiliser, y compris pour les fonctions membres, et débloquez une compétence essentielle pour interagir avec les bibliothèques C traditionnelles. Maîtrisez cette notion fondamentale pour écrire un code C++ plus puissant et adaptatif.','Matthieu Schaller (Nanoc)',0,'covers/c-les-pointeurs-sur-fonctions.png','books/C les pointeurs sur fonctions.pdf',11,2011,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(394,'L\'algorithme min-max','lalgorithme-min-max','Plongez au cœur de l\'intelligence artificielle et découvrez comment les ordinateurs \"réfléchissent\" dans les jeux de stratégie comme les échecs ou le morpion. Ce livre vous guide à travers les principes fondamentaux de l\'algorithme Min-Max, une technique essentielle pour concevoir des IA de jeux. Vous y explorerez en détail son fonctionnement, ses fonctions clés, et appliquerez concrètement ces connaissances à un projet pratique. Une introduction claire et accessible au monde passionnant de la programmation d\'IA pour les jeux.','martin9_36',0,'covers/l-algorithme-min-max.png','books/L algorithme min max.pdf',13,2011,1,7,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(395,'Faire des animations avec SDLP_Anim','faire-des-animations-avec-sdlp-anim','Plongez dans l\'univers captivant de l\'animation en C/C++ et donnez vie à vos projets graphiques avec ce guide dédié à SDLP_Anim, un outil intuitif et simple d\'utilisation. Conçu par l\'auteur lui-même, cet ouvrage vous accompagnera pas à pas dans la création d\'animations, qu\'elles soient séquentielles ou déclenchées par des événements. À travers des explications claires, des fonctions détaillées et des exercices pratiques, vous maîtriserez toutes les techniques pour dynamiser vos applications. Indispensable pour tout développeur C/C++ souhaitant ajouter une dimension visuelle enrichissante à ses créations.','pOpOp99O0',0,'covers/faire-des-animations-avec-sdlp-anim.png','books/Faire des animations avec sdlp anim.pdf',23,2012,1,4,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(396,'Calculer une plage d\'adresses avec la méthode magique','calculer-une-plage-dadresses-avec-la-methode-magique','Vous trouvez les calculs de masques de sous-réseau complexes et fastidieux, surtout face aux cas les plus ardus ? Ce guide vous présente la \"méthode magique\", une approche simple, rapide et infaillible pour maîtriser les plages d\'adresses IP sans passer par le binaire. Apprenez à définir précisément les adresses de réseau, de broadcast, et à découper efficacement vos sous-réseaux, même dans les configurations les plus complexes, en un temps record. Gagnez en assurance et en efficacité, et transformez ce qui était une corvée en un processus intuitif et maîtrisé.','elalitte',0,'covers/calculer-une-plage-d-adresses-avec-la-methode-magique.png','books/Calculer une plage d adresses avec la methode magique.pdf',12,2010,1,6,'2026-07-29 08:53:24','2026-07-29 08:53:24'),(397,'L\'écran graphique en TI-Basic','lecran-graphique-en-ti-basic','Fatigué des programmes TI-Basic visuellement monotones sur l\'écran HOME de votre calculatrice ? Ce livre est votre passeport pour l\'écran graphique, vous permettant de créer des applications esthétiques et interactives. Apprenez les fondamentaux des repères, la manipulation des pixels et des points, l\'affichage de texte, ainsi que les techniques de dessin avancées et le tracé de fonctions mathématiques pour des graphiques dynamiques. Conçu pour être facile d\'accès, il transformera radicalement l\'apparence et l\'interactivité de vos programmes TI-Basic.','myst6re',0,'covers/l-ecran-graphique-en-ti-basic.png','books/L ecran graphique en ti basic.pdf',22,2026,0,6,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(398,'Un lecteur MP3 en flash','un-lecteur-mp3-en-flash','Maîtrisez la création d\'un lecteur MP3 Flash exportable et personnalisable, l\'outil idéal pour enrichir l\'interactivité de vos pages web et blogs. Ce guide pratique vous accompagne étape par étape, depuis la mise en place des éléments visuels interactifs jusqu\'à l\'intégration complète du code ActionScript. Vous apprendrez à gérer les fonctionnalités essentielles de lecture, pause et arrêt, en déclarant variables et fonctions avec clarté. Offrez à vos utilisateurs une expérience multimédia fluide et créez un lecteur unique dont vous maîtriserez chaque aspect.','Gora',0,'covers/un-lecteur-mp3-en-flash.png','books/Un lecteur mp3 en flash.pdf',9,2026,0,5,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(399,'Stocker et sérialiser des objets avec Qt','stocker-et-serialiser-des-objets-avec-qt','Vous êtes un développeur C++ avec Qt et vous cherchez à stocker ou transférer vos objets de manière simple et efficace ? Ce guide pratique vous ouvre les portes de la sérialisation d\'objets grâce aux outils puissants de Qt. Découvrez comment utiliser `QVariant` et `QDataStream` pour transformer n\'importe quel objet, même complexe et sans accès à son code source, en un flux de données gérable. Simplifiez considérablement la persistance de vos données avec une approche épurée et très peu de code à ajouter, pour des applications toujours plus robustes.','Julien Rosset (Darkelfe)',0,'covers/stocker-et-serialiser-des-objets-avec-qt.png','books/Stocker et serialiser des objets avec qt.pdf',17,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(400,'[PHP] Utiliser un débogueur pour PHP : Xdebug','php-utiliser-un-debogueur-pour-php-xdebug','Optimisez radicalement vos cycles de développement PHP et dites adieu aux sessions de débogage inefficaces grâce à ce guide essentiel. Ce livre vous plonge au cœur de Xdebug, l\'extension indispensable pour PHP, en vous guidant pas à pas de son installation et configuration à son utilisation basique. Découvrez également ses fonctionnalités avancées de traçage, d\'analyse des variables et de profiling, pour une compréhension approfondie et une optimisation précise de vos applications. Transformez votre approche du débogage et développez des applications PHP plus robustes et performantes.','ililoyd',0,'covers/php-utiliser-un-debogueur-pour-php-xdebug.png','books/Php utiliser un debogueur pour php xdebug.pdf',19,2008,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(401,'Première image Photoréaliste','premiere-image-photorealiste','Vous rêvez de créer votre première image photoréaliste avec Blender, mais la complexité du logiciel vous décourage ? Ce guide pratique vous mène pas à pas de la modélisation et l\'application de matériaux complexes (comme le chrome de Suzanne) à l\'intégration de textures photoréalistes et de bump-maps pour un sol crédible. Idéal pour ceux qui maîtrisent déjà les bases de l\'interface, il vous révélera des astuces précieuses pour obtenir rapidement des rendus de qualité impressionnante qui épateront votre entourage.','riton',0,'covers/premiere-image-photorealiste.png','books/Premiere image photorealiste.pdf',14,2026,0,7,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(402,'Les interfaces graphiques avec OCaml','les-interfaces-graphiques-avec-ocaml','Vous aspirez à doter vos programmes OCaml d\'interfaces graphiques modernes et conviviales ? Loin des limitations des bibliothèques standard, ce guide essentiel vous introduit à LablGTK, la solution robuste pour développer des applications visuellement attrayantes. S\'adressant aux développeurs OCaml possédant des bases solides, il décrypte les concepts avancés du langage exploités par LablGTK et offre des exemples pratiques pour une maîtrise rapide de la création d\'interfaces GTK de qualité. Développez avec confiance des applications OCaml à l\'expérience utilisateur optimisée.','Cacophrene',0,'covers/les-interfaces-graphiques-avec-ocaml.png','books/Les interfaces graphiques avec ocaml.pdf',13,2026,0,6,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(403,'Plantage au boot suite au formatage d\'un OS','plantage-au-boot-suite-au-formatage-dun-os','Votre ordinateur refuse de démarrer après la suppression d\'un système d\'exploitation, laissant votre machine en panne ? Ne paniquez plus ! Ce guide complet vous offre la solution pour corriger les erreurs de boot les plus courantes. Apprenez à restaurer votre Master Boot Record (MBR) sous Windows XP ou d\'anciennes versions de Windows, avec des instructions claires, pas à pas, incluant les ajustements nécessaires du BIOS pour démarrer votre dépannage et retrouver un PC fonctionnel rapidement.','flobard',0,'covers/plantage-au-boot-suite-au-formatage-d-un-os.png','books/Plantage au boot suite au formatage d un os.pdf',5,2000,0,6,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(404,'Faire un menu d\'accès rapide','faire-un-menu-dacces-rapide','Optimisez votre productivité et l\'accès à vos applications favorites grâce à ce guide pratique. Découvrez comment créer votre propre menu d\'accès rapide, directement intégré à la barre des tâches de Windows, sans aucune ligne de code ni plugin complexe. Ce tutoriel clair vous accompagnera pas à pas pour organiser tous vos raccourcis, jeux et fichiers, et même créer des sous-menus personnalisés. Transformez votre expérience utilisateur et accédez à l\'essentiel d\'un simple clic, pour un poste de travail toujours plus efficace et élégant.','Benoît CRAUET (Kermi)',0,'covers/faire-un-menu-d-acces-rapide.png','books/Faire un menu d acces rapide.pdf',8,2026,0,10,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(405,'Un wiki avec Yaws en 13 minutes 37 secondes','un-wiki-avec-yaws-en-13-minutes-37-secondes','Défiez le temps et construisez votre propre wiki fonctionnel en un clin d\'œil grâce à ce guide ingénieux centré sur le serveur web Yaws. Destiné aux programmeurs Erlang expérimentés et aux esprits curieux, cet ouvrage vous plonge dans la configuration et l\'utilisation directe de Yaws, se distinguant des frameworks web habituels. Vous apprendrez à intégrer la base de données Mnesia, gérer les requêtes GET et POST, et créer des pages dynamiques, tout en évitant la complexité d\'une architecture MVC. Un parcours pratique et concret pour maîtriser Yaws et développer votre wiki, du concept à l\'amélioration.','rks`',0,'covers/un-wiki-avec-yaws-en-13-minutes-37-secondes.png','books/Un wiki avec yaws en 13 minutes 37 secondes.pdf',16,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(406,'Stocker les sessions dans votre base de données','stocker-les-sessions-dans-votre-base-de-donnees','Améliorez considérablement la sécurité et la gestion de vos applications web en découvrant comment stocker efficacement vos sessions PHP dans une base de données. Ce guide pratique vous révèle les failles des méthodes de stockage par défaut et vous enseigne, étape par étape, à utiliser `session_set_save_handler` pour une personnalisation complète. Maîtrisez la mise en place d\'une solution robuste, de la création de la table aux callbacks, et assurez une protection accrue contre les accès non autorisés et les limites d\'hébergement. Prenez le contrôle total de la persistance des données de vos utilisateurs et renforcez la fiabilité de vos projets web.','F_D_V',0,'covers/stocker-les-sessions-dans-votre-base-de-donnees.png','books/Stocker les sessions dans votre base de donnees.pdf',11,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(407,'Les suites de Syracuse','les-suites-de-syracuse','Plongez dans le monde captivant des suites de Syracuse, une énigme mathématique qui défie les chercheurs depuis près d\'un siècle. Cet ouvrage vous initie à leur définition, leur origine historique et la célèbre conjecture de Collatz, un problème fascinant et encore irrésolu. Pour aller plus loin, il propose une implémentation concrète de l\'algorithme en OCaml, vous invitant à explorer ces séquences par vous-même. Que vous soyez passionné de théorie mathématique ou de programmation fonctionnelle, ce livre est une porte d\'entrée incontournable vers un défi algorithmique intemporel.','Olivier Strebler (shareman)',0,'covers/les-suites-de-syracuse.png','books/Les suites de syracuse.pdf',5,2008,0,6,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(408,'Créez un jeu de Sokoban en Flash !','creez-un-jeu-de-sokoban-en-flash','Maîtrisez Flash et ActionScript pour donner vie à votre propre jeu de Sokoban, un classique indémodable du jeu de réflexion. Ce guide pratique vous accompagnera pas à pas, de la mise en place des niveaux à la gestion des déplacements complexes, des collisions et du score, sans oublier l\'intégration d\'une fonction d\'annulation. Idéal pour les développeurs possédant des bases en ActionScript, il vous permettra d\'adopter des habitudes de programmation professionnelles et de généraliser votre code pour créer une multitude de tableaux. Transformez vos connaissances en un projet concret, ludique et complet, prêt à être partagé !','Webanix',0,'covers/creez-un-jeu-de-sokoban-en-flash.png','books/Creez un jeu de sokoban en flash.pdf',24,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(409,'Installer Linux dans Windows avec coLinux','installer-linux-dans-windows-avec-colinux','Ce guide pratique vous propose une approche révolutionnaire pour intégrer GNU/Linux à votre système Windows sans les contraintes d\'une machine virtuelle lourde ou d\'un dual-boot. Découvrez comment coLinux, un portage ingénieux du noyau Linux, vous permet de faire fonctionner une distribution Ubuntu complète, avec son environnement de bureau KDE via XMing, directement sur votre PC comme une application native. De l\'installation détaillée à la configuration du serveur graphique et au partage de fichiers, vous maîtriserez toutes les étapes pour exploiter la puissance de Linux avec une facilité déconcertante. Idéal pour l\'apprentissage ou le développement, ce livre déverrouille un nouveau monde de possibilités informatiques, accessible et performant.','Fififox',0,'covers/installer-linux-dans-windows-avec-colinux.png','books/Installer linux dans windows avec colinux.pdf',13,2026,0,6,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(410,'Un karaoké avec Ultrastar','un-karaoke-avec-ultrastar','Envie de transformer votre PC en une véritable machine à karaoké, gratuitement ? Ce guide essentiel vous plonge dans l\'univers d\'Ultrastar, l\'alternative libre et riche en fonctionnalités aux jeux de chant console. De l\'installation pas à pas à la gestion de votre bibliothèque musicale, en passant par la configuration des outils et l\'organisation de soirées mémorables en \"Mode Fête\", vous maîtriserez toutes les facettes de ce logiciel. Allez au-delà du simple chant en découvrant comment ajouter vos chansons préférées et, surtout, comment créer de toutes pièces vos propres pistes karaoké personnalisées, une liberté rare dans le monde des jeux musicaux.','ska_boy',0,'covers/un-karaoke-avec-ultrastar.png','books/Un karaoke avec ultrastar.pdf',20,2026,0,6,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(411,'Comment parser facilement du XML','comment-parser-facilement-du-xml','Vous maîtrisez les bases du XML mais cherchez à en exploiter tout le potentiel ? Ce guide pratique vous révèle comment parser et transformer vos documents XML avec une facilité déconcertante. Plongez dans les secrets de XSLT et XPATH pour convertir efficacement vos données en formats variés, du XML au XHTML. Idéal pour les développeurs intermédiaires, ce tutoriel vous offre une méthode élégante et standardisée pour manipuler le XML.','Crabe05',0,'covers/comment-parser-facilement-du-xml.png','books/Comment parser facilement du xml.pdf',18,2001,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(412,'Deplacement avec le clavier','deplacement-avec-le-clavier','Plongez dans le monde de l\'animation interactive avec ce guide essentiel, conçu pour vous faire maîtriser le déplacement d\'objets ou de personnages via le clavier dans Flash. Ce livre vous accompagne pas à pas, de la création de fichiers et de clips aux concepts d\'occurrences, en passant par l\'intégration de vos propres images ou la conception simple de formes. Idéal pour les débutants, il introduit également la puissance de l\'ActionScript pour donner vie à vos créations. Apprenez à rendre vos animations réactives et engageantes avec une facilité surprenante.','Blue112',0,'covers/deplacement-avec-le-clavier.png','books/Deplacement avec le clavier.pdf',7,2026,0,7,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(413,'Installation et configuration de GRUB','installation-et-configuration-de-grub','Libérez le plein potentiel de votre machine grâce à ce guide essentiel sur l\'installation et la configuration du célèbre bootloader GNU GRUB. Conçu pour les débutants, il vous accompagnera pas à pas depuis les bases de son fonctionnement jusqu\'à la personnalisation avancée de votre menu de démarrage. Maîtrisez la gestion de vos systèmes multi-boot, résolvez les problèmes courants et naviguez entre vos OS avec une facilité et une confiance inégalées.','Sébastian',0,'covers/installation-et-configuration-de-grub.png','books/Installation et configuration de grub.pdf',10,2026,0,6,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(414,'Régler les problèmes de collisions','regler-les-problemes-de-collisions','Fatigué des collisions imprécises qui cassent l\'immersion de vos jeux Flash ? Ce livre explore en détail les défis posés par `hitTest` et vous propose trois stratégies efficaces pour les résoudre : le retour en arrière, le repositionnement chirurgical et une solution itérative par boucle. Apprenez à implémenter ces techniques pour garantir des interactions fluides et réalistes. Offrez une expérience de jeu impeccable à vos utilisateurs.','isagaw',0,'covers/regler-les-problemes-de-collisions.png','books/Regler les problemes de collisions.pdf',7,2026,0,5,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(415,'Les piles et les files en C++','les-piles-et-les-files-en-c','Maîtrisez les structures de données essentielles que sont les piles et les files en C++ grâce à ce guide complet et accessible. Découvrez comment le langage et la Standard Template Library (STL) simplifient considérablement leur implémentation, de la gestion LIFO et FIFO à l\'ensemble des opérations clés comme l\'ajout, la suppression et l\'accès aux éléments. Parfait pour les programmeurs C++ désireux d\'intégrer efficacement ces outils fondamentaux dans leurs projets, ce livre vous éclairera avec des explications claires et des exemples concrets.','Xavinou',0,'covers/les-piles-et-les-files-en-c.png','books/Les piles et les files en c.pdf',15,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(416,'Écrire du PHP dans des fichiers HTML','ecrire-du-php-dans-des-fichiers-html','Fatigué de la tâche répétitive de renommer vos fichiers HTML en PHP pour y intégrer des fonctionnalités dynamiques ? Ce guide indispensable vous offre la solution en vous apprenant à faire interpréter le PHP directement dans vos fichiers .html, ou toute autre extension souhaitée, sans reconfiguration majeure. Que vous ayez accès à la configuration de votre serveur ou que vous cherchiez une approche rapide via .htaccess, ce livre vous montrera comment automatiser votre site avec une efficacité redoutable et une simplicité déconcertante. Optimisez votre flux de travail et donnez vie à vos pages statiques en quelques manipulations clés !','flobard',0,'covers/ecrire-du-php-dans-des-fichiers-html.png','books/Ecrire du php dans des fichiers html.pdf',5,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(417,'Du rewriting réalisé avec du PHP','du-rewriting-realise-avec-du-php','Rendez vos URLs plus esthétiques et SEO-friendly, même si votre hébergeur ne propose pas de réécriture native ! Cet ouvrage vous dévoile une astuce PHP intelligente pour simuler l\'URL Rewriting, contournant ainsi les limitations courantes. À travers des exemples concrets, notamment pour un système de news, maîtrisez cette technique essentielle pour créer des liens clairs, améliorer l\'expérience utilisateur et optimiser le référencement de vos sites web. Transformez vos adresses web en véritables atouts grâce à cette méthode rigoureuse et efficace.','Jérémy_B',0,'covers/du-rewriting-realise-avec-du-php.png','books/Du rewriting realise avec du php.pdf',10,2008,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(418,'Un système d\'affiliation pour votre site','un-systeme-daffiliation-pour-votre-site','Développez la visibilité de votre boutique en ligne et augmentez vos ventes grâce à un système d\'affiliation performant. Ce guide pratique vous accompagne pas à pas dans la création d\'un programme qui rémunère vos partenaires uniquement sur des internautes qualifiés, garantissant un retour sur investissement optimal. Vous maîtriserez les concepts clés, de l\'identification fiable des visiteurs affiliés à la gestion des données via PHP et SQL, pour bâtir un dispositif robuste et autonome. Mettez en œuvre votre propre programme pour transformer vos partenaires en de véritables vecteurs de croissance.','kidsinhalf',0,'covers/un-systeme-d-affiliation-pour-votre-site.png','books/Un systeme d affiliation pour votre site.pdf',10,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(419,'Compilez l\'AS3 gratuitement et légalement sous Windows/Linux','compilez-las3-gratuitement-et-legalement-sous-windowslinux','Marre des licences coûteuses ou des contraintes logicielles pour développer en ActionScript 3 ? Ce guide essentiel vous ouvre les portes de la compilation AS3, gratuitement et légalement, sur Windows comme sur Linux. Découvrez comment installer et maîtriser le Flex SDK pour créer vos propres fichiers SWF, puis optimiser votre code grâce à des astuces précieuses. Programmez sans limites, avec des outils performants et multiplateformes, tout en respectant votre budget et la légalité.','neamar',0,'covers/compilez-l-as3-gratuitement-et-legalement-sous-windows-linux.png','books/Compilez l as3 gratuitement et legalement sous windows linux.pdf',17,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(420,'Créer une vidéo d\'un jeu (WoW, CS, etc.)','creer-une-video-dun-jeu-wow-cs-etc','Immortalisez vos plus belles actions de jeu et partagez-les avec le monde ! Ce guide pratique vous accompagne pas à pas, de l\'enregistrement de vos parties sur des titres comme World of Warcraft ou Counter-Strike avec Fraps, jusqu\'au montage final.\n\nDécouvrez une méthode simple pour configurer votre logiciel, réaliser vos captures vidéo et assembler vos séquences via Windows Movie Maker, même sans expérience préalable. Que vous souhaitiez montrer vos frags ou partager des astuces, ce tutoriel \"Facile\" vous donne toutes les clés pour publier vos créations sur le web.','MisterJ',0,'covers/creer-une-video-d-un-jeu-wow-cs-etc.png','books/Creer une video d un jeu wow cs etc.pdf',12,2000,0,7,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(421,'Warcraft III et les cinématiques','warcraft-iii-et-les-cinematiques','Plongez au cœur de l\'univers de Warcraft III et apprenez à donner vie à vos propres récits captivants grâce à ce guide dédié à la création de cinématiques. Que vous soyez débutant ou que vous ayez déjà quelques notions de l\'éditeur, découvrez une approche simple et progressive pour maîtriser les outils essentiels de la mise en scène. De la manipulation des déclencheurs aux placements de caméra, en passant par la gestion des unités et des variables, ce tutoriel pratique vous guidera étape par étape pour concevoir des séquences narratives immersives et mémorables. Libérez votre imagination et transformez vos idées en de véritables mini-films pour enrichir vos cartes et campagnes.','Exoflux',0,'covers/warcraft-iii-et-les-cinematiques.png','books/Warcraft iii et les cinematiques.pdf',19,2026,0,7,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(422,'Créer son serveur TeamSpeak 2 RC2','creer-son-serveur-teamspeak-2-rc2','Envie de maîtriser la création de votre propre serveur TeamSpeak 2 RC2 pour des communications vocales fluides en équipe ou entre amis ? Ce guide complet et accessible vous accompagne pas à pas, du téléchargement du logiciel à la mise en ligne, en passant par la gestion détaillée des permissions et la création de canaux personnalisés. Idéal pour les chefs de groupe comme pour les utilisateurs curieux, il rendra l\'installation et l\'administration de votre serveur TeamSpeak un jeu d\'enfant. Apprenez à surmonter les défis de l\'IP dynamique et offrez à votre communauté une plateforme de dialogue vocale performante et sécurisée.','kobalt',0,'covers/creer-son-serveur-teamspeak-2-rc2.png','books/Creer son serveur teamspeak 2 rc2.pdf',16,2026,0,5,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(423,'Domptez votre calculatrice avec le Basic Casio !','domptez-votre-calculatrice-avec-le-basic-casio','Envie de transformer votre calculatrice Casio en un véritable outil de création ? Ce guide pratique vous ouvre les portes de la programmation Basic, vous permettant de dompter ses fonctionnalités cachées avec aisance. Des bases essentielles aux boucles, conditions, fonctions avancées et graphismes captivants, vous apprendrez à créer des programmes élaborés, des jeux interactifs aux affichages dynamiques. Maîtrisez la manipulation des listes, des matrices et les puissantes fonctions DrawStat pour concrétiser toutes vos idées et exploiter pleinement le potentiel de votre calculatrice Casio Graph + à +.','pylaterreur',0,'covers/domptez-votre-calculatrice-avec-le-basic-casio.png','books/Domptez votre calculatrice avec le basic casio.pdf',53,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(424,'[C++] Les templates','c-les-templates','Optimisez votre code C++ et dépassez les contraintes de la surcharge de fonctions grâce aux templates. Ce guide essentiel vous invite à maîtriser cette fonctionnalité avancée pour écrire des fonctions génériques, plus performantes et d\'une clarté incomparable. Vous apprendrez à créer des patrons de fonctions, à gérer leurs paramètres et à les spécialiser pour des cas spécifiques. Plongez dans les templates C++ pour élever la qualité de votre développement et accélérer votre productivité.','foester',0,'covers/c-les-templates.png','books/C les templates.pdf',10,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(425,'Exécuter PHP en CLI (Console)','executer-php-en-cli-console','Vous pensiez que PHP était uniquement destiné à créer des pages web ? Découvrez une toute nouvelle dimension avec ce guide essentiel sur l\'exécution de PHP en ligne de commande (CLI). Apprenez à transformer votre workflow en automatisant des tâches répétitives et en créant des scripts puissants, bien au-delà des applications web traditionnelles. Ce livre ouvre des possibilités insoupçonnées pour les développeurs désireux d\'élargir leurs compétences et de maximiser l\'efficacité de leurs projets.','Anonymous59',0,'covers/executer-php-en-cli-console.png','books/Executer php en cli console.pdf',14,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(426,'Introduction à la 3D','introduction-a-la-3d','Plongez au cœur de la création 3D avec Flash et ActionScript, en bâtissant les fondations par vous-même. Loin des moteurs pré-intégrés, cet ouvrage intermédiaire vous guide pas à pas, s\'appuyant sur une solide compréhension de la trigonométrie pour manipuler des scènes tridimensionnelles. Vous apprendrez à implémenter des rotations complexes, à assembler des formes 3D comme des cubes, et à les enrichir de textures personnalisées. Un guide pratique essentiel pour les développeurs désireux de maîtriser les mécanismes profonds de la 3D interactive, plutôt que de simples outils.','heero78',0,'covers/introduction-a-la-3d.png','books/Introduction a la 3d.pdf',29,2026,0,6,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(427,'Le dessin facile avec les Casio Graph 35+ et 25+','le-dessin-facile-avec-les-casio-graph-35-et-25','Marre des chiffres ? Transformez votre calculatrice Casio Graph 35+ ou 25+ en un atelier de création artistique ! Ce guide pratique vous dévoile comment explorer les fonctionnalités intégrées de votre appareil pour réaliser facilement des dessins et du pixel art, du simple tracé à la maîtrise d\'outils plus avancés. L\'intérêt ? Tout se fait directement sur votre machine, sans aucun câble PC ni ligne de code nécessaire. Idéal pour égayer vos temps morts ou développer votre créativité, ce livre est votre passeport pour le dessin numérique sur Casio.','Timst',0,'covers/le-dessin-facile-avec-les-casio-graph-35-et-25.png','books/Le dessin facile avec les casio graph 35 et 25.pdf',8,2026,0,6,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(428,'[C++] Les conversions de types','c-les-conversions-de-types','Optimisez la robustesse et la flexibilité de vos applications C++ en maîtrisant l\'art des conversions de types. Ce livre vous guide à travers l\'utilisation experte des `static_cast`, `reinterpret_cast`, `const_cast` et `dynamic_cast`, vous apprenant à choisir le bon outil pour chaque scénario et à gérer les erreurs potentielles. Devenez un programmeur C++ plus rigoureux et confiant en assimilant ces mécanismes fondamentaux, illustrés par des exemples concrets pour une compréhension claire et sûre.','Olivier Strebler (shareman)',0,'covers/c-les-conversions-de-types.png','books/C les conversions de types.pdf',8,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(429,'Apprendre le TI-basic pas-à-pas','apprendre-le-ti-basic-pas-a-pas','Découvrez la programmation TI-Basic avec ce guide pas-à-pas, idéal pour les lycéens et étudiants équipés d\'une calculatrice graphique TI. Maîtrisez les rudiments, de la gestion des variables aux boucles et conditions, et apprenez à manipuler l\'écran et les touches pour des interactions avancées. Grâce à des mini-TPs concrets et un projet de création de jeu complet, vous mettrez rapidement en pratique vos connaissances et débloquerez tout le potentiel de votre TI. Ce livre est votre passeport pour transformer votre calculatrice en un outil de programmation puissant et personnalisé.','Jicks',0,'covers/apprendre-le-ti-basic-pas-a-pas.png','books/Apprendre le ti basic pas a pas.pdf',58,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(430,'Jouer à Unreal Tournament GOTY sur Linux','jouer-a-unreal-tournament-goty-sur-linux','Découvrez comment libérer tout le potentiel de votre système Linux pour revivre l\'expérience mythique d\'Unreal Tournament GOTY. Ce guide complet vous accompagne pas à pas, de la préparation à l\'installation, jusqu\'au lancement de ce FPS multijoueur intemporel. Plongez dans des modes de jeu emblématiques comme le Deathmatch et la Capture de Drapeau, et maîtrisez l\'art du frag sur votre plateforme favorite. Ne laissez plus la compatibilité être un frein : jouez à un classique indémodable comme il se doit.','DiFFtY',0,'covers/jouer-a-unreal-tournament-goty-sur-linux.png','books/Jouer a unreal tournament goty sur linux.pdf',6,2026,0,7,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(431,'Installation et utilisation d\'un serveur SSH sous Debian Etch','installation-et-utilisation-dun-serveur-ssh-sous-debian-etch','Vous souhaitez sécuriser vos connexions à distance et prendre le contrôle de vos serveurs en toute confiance ? Ce guide pratique vous accompagne pas à pas dans l\'installation et la configuration d\'un serveur SSH robuste sous Debian Etch, expliquant clairement les options essentielles pour une sécurité optimale. Apprenez à mettre en place ce protocole indispensable, puis connectez-vous aisément à votre serveur depuis n\'importe quel poste de travail, qu\'il tourne sous Linux ou Windows. Maîtrisez l\'accès sécurisé à distance et protégez vos données dès aujourd\'hui.','greatman',0,'covers/installation-et-utilisation-d-un-serveur-ssh-sous-debian-etch.png','books/Installation et utilisation d un serveur ssh sous debian etch.pdf',8,2006,0,5,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(432,'Récupérer des fichiers après un vidage de la corbeille','recuperer-des-fichiers-apres-un-vidage-de-la-corbeille','Vous avez vidé votre corbeille par erreur et craignez d\'avoir perdu des fichiers importants ? Ce guide essentiel démystifie la récupération de données et vous offre les clés pour restaurer vos documents, photos ou vidéos même après un vidage. Apprenez comment vos fichiers persistent sur votre disque dur et suivez des étapes claires, illustrées par l\'utilisation d\'un logiciel gratuit, pour les retrouver efficacement. De plus, découvrez comment garantir une suppression définitive de vos informations sensibles, reprenant ainsi le contrôle total de vos données numériques.','Cartouche',0,'covers/recuperer-des-fichiers-apres-un-vidage-de-la-corbeille.png','books/Recuperer des fichiers apres un vidage de la corbeille.pdf',5,2026,0,7,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(433,'Erlang Graphical Drawer','erlang-graphical-drawer','Explorez le potentiel du module `egd` et dotez vos applications Erlang de capacités graphiques percutantes. Ce guide vous accompagne de la création de formes basiques à la génération de graphiques complexes — illustrant, par exemple, l\'activité d\'un canal IRC — avec une exportation aisée au format PNG. Au-delà des simples tracés, découvrez comment intégrer harmonieusement ces visualisations directement au cœur de vos systèmes Erlang pour une valeur ajoutée significative et une meilleure compréhension de vos données.','rks`',0,'covers/erlang-graphical-drawer.png','books/Erlang graphical drawer.pdf',12,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(434,'Manipulation d\'extensions avec la base de registre','manipulation-dextensions-avec-la-base-de-registre','Plongez au cœur de votre système Windows avec ce guide indispensable qui vous enseigne la manipulation directe de la base de registre. Découvrez comment créer, modifier et supprimer manuellement les extensions de fichiers, personnaliser leurs icônes et définir des actions uniques, bien au-delà des options par défaut. Cet ouvrage exhaustif, fruit d\'une compilation rigoureuse et de connaissances expertes, vous offre les clés d\'une personnalisation avancée et sécurisée pour maîtriser votre environnement Windows comme jamais auparavant.','Julien Rosset (Darkelfe)',0,'covers/manipulation-d-extensions-avec-la-base-de-registre.png','books/Manipulation d extensions avec la base de registre.pdf',23,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(435,'Avant-goût du langage : une todo-list distribuée','avant-gout-du-langage-une-todo-list-distribuee','Programmeurs, êtes-vous prêts à explorer des solutions innovantes aux défis complexes du parallélisme et des systèmes distribués ? Cet avant-goût du langage Erlang, né des exigences robustes des télécommunications, vous offre une immersion rapide dans une approche différente pour concevoir des applications concurrentes et tolérantes aux pannes. À travers l\'élaboration d\'une application concrète comme une todo-list distribuée, saisissez les concepts fondamentaux qui distinguent Erlang, sans vous encombrer de la syntaxe détaillée. Découvrez pourquoi ce langage surprenant est une piste sérieuse pour l\'avenir de vos projets distribués et laissez-vous tenter d\'en savoir plus.','bluestorm',0,'covers/avant-gout-du-langage-une-todo-list-distribuee.png','books/Avant gout du langage une todo list distribuee.pdf',8,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(436,'Utiliser l\'écran graphique de la TI','utiliser-lecran-graphique-de-la-ti','Maîtrisez l\'écran graphique de votre calculatrice TI pour aller bien au-delà des fonctions mathématiques de base. Ce guide complet vous mènera de la configuration détaillée de l\'affichage à l\'utilisation avancée des fonctions de dessin, pixel par pixel. Découvrez comment programmer un menu interactif, animer un personnage, et même développer des jeux complexes comme un Morpion ou un RPG complet en TI-Basic. Idéal pour les utilisateurs de TI-83, TI-84 et modèles supérieurs désireux de pousser leurs compétences en programmation TI-Basic à un niveau créatif.','dark link38',0,'covers/utiliser-l-ecran-graphique-de-la-ti.png','books/Utiliser l ecran graphique de la ti.pdf',56,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(437,'Les scripts sous Photoshop','les-scripts-sous-photoshop','Démystifiez l\'automatisation de Photoshop et transformez votre flux de travail grâce à la puissance des scripts. Ce guide pratique et détaillé vous démontrera qu\'il est facile de créer et d\'utiliser ces petits programmes sans écrire une seule ligne de code, vous permettant d\'exécuter des opérations complexes en un seul clic. Finies les opérations fastidieuses : apprenez à maîtriser ces outils pour gagner un temps précieux et optimiser chaque projet, même si les scripts vous intimident. De la préparation à l\'enregistrement de votre premier script, en passant par les fonctions avancées, vous trouverez toutes les clés pour une boîte à outils Photoshop performante et personnalisée.','Zopieux',0,'covers/les-scripts-sous-photoshop.png','books/Les scripts sous photoshop.pdf',15,2026,0,7,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(438,'Un favicon pour votre site','un-favicon-pour-votre-site','Saviez-vous que la petite icône affichée à côté de l\'adresse de votre site web peut renforcer votre identité numérique ? Ce guide pratique vous révèle comment créer et intégrer facilement cette image distinctive, même si vous partez de zéro, en transformant une simple idée en un élément visuel percutant. De la conception pas à pas avec des outils accessibles jusqu\'à l\'insertion via les balises HTML, découvrez toutes les astuces pour assurer l\'affichage impeccable de votre favicon sur tous les navigateurs. Ne laissez plus votre site passer inaperçu : apprenez en quelques étapes simples à ajouter cette touche professionnelle qui marque les esprits.','Xerto',0,'covers/un-favicon-pour-votre-site.png','books/Un favicon pour votre site.pdf',6,2026,0,5,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(439,'Les bases du FTP sous MS-DOS','les-bases-du-ftp-sous-ms-dos','Maîtrisez les bases essentielles du FTP dans l\'environnement MS-DOS avec ce guide pratique et didactique. Idéal pour les professionnels et les passionnés se retrouvant sans client FTP graphique, cet ouvrage vous accompagnera pas à pas, depuis la connexion initiale jusqu\'à la gestion avancée des fichiers et dossiers. Vous apprendrez à vous connecter, naviguer, transférer des données et administrer votre session avec assurance, acquérant ainsi une autonomie précieuse. Un savoir-faire fondamental pour relever les défis de l\'informatique en ligne de commande.','Gregoo',0,'covers/les-bases-du-ftp-sous-ms-dos.png','books/Les bases du ftp sous ms dos.pdf',18,2026,0,7,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(440,'[Qt] Compilez facilement sous Linux !','qt-compilez-facilement-sous-linux','Développeur Qt sous Linux, vous en avez assez des commandes répétitives pour compiler vos projets ? Ce guide pratique vous propose deux méthodes ingénieuses pour automatiser cette tâche et simplifier radicalement votre flux de travail. Que vous soyez un utilisateur d\'Ubuntu/Gnome souhaitant exploiter les scripts Nautilus, ou que vous cherchiez une solution plus universelle via un exécutable dédié, vous trouverez ici la réponse. Ne perdez plus de temps en console et consacrez-vous pleinement au développement de vos applications Qt avec une efficacité inégalée.','Minishlink',0,'covers/qt-compilez-facilement-sous-linux.png','books/Qt compilez facilement sous linux.pdf',8,2026,0,4,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(441,'Hot Code Swapping','hot-code-swapping','Fatigué de devoir redémarrer vos serveurs et déconnecter vos utilisateurs à chaque mise à jour ou correction ? Ce livre vous initie au Hot Code Swapping, une technique avancée permettant de modifier le code d\'une application en cours d\'exécution sans aucune interruption. Axé sur des exemples pratiques avec le langage Erlang, il vous guidera pour construire des systèmes d\'une résilience et d\'une adaptabilité exceptionnelles. Découvrez comment maintenir vos services opérationnels 24h/24, 7j/7, tout en assurant une évolution continue et une gestion élégante des imprévus.','rks`',0,'covers/hot-code-swapping.png','books/Hot code swapping.pdf',8,2026,0,7,'2026-07-29 13:23:37','2026-07-29 13:23:37'),(442,'Les hacks CSS pour Internet Explorer','les-hacks-css-pour-internet-explorer','Internet Explorer met vos nerfs à rude épreuve avec ses interprétations CSS capricieuses ? Ce guide pratique vous révèle les \"hacks CSS\" indispensables pour maîtriser les défis de compatibilité et garantir un affichage uniforme sur tous les navigateurs. Explorez des techniques éprouvées comme `!important`, `* html` et les commentaires conditionnels, expliquées pas à pas. Ne laissez plus IE gâcher votre design : transformez vos frustrations en solutions élégantes et professionnelles.','swilmet',0,'covers/les-hacks-css-pour-internet-explorer.png','books/Les hacks css pour internet explorer.pdf',6,2001,0,5,'2026-07-29 13:23:37','2026-07-29 13:23:37');
